package com.craftwise;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

/**
 * RuneLite configuration interface for CraftWise.
 * All settings persist across RuneLite sessions via RuneLite's ConfigManager.
 */
@ConfigGroup(CraftWiseConfig.CONFIG_GROUP)
public interface CraftWiseConfig extends Config
{
	String CONFIG_GROUP = "craftwise";

	enum PriceCalculationMode
	{
		INSTANT_BUY_SELL("Instant Buy / Instant Sell (Conservative)"),
		PATIENT_BUY_SELL("Patient Offers (Low Buy / High Sell)"),
		OPTIMISTIC_MARKET("Optimistic Market (Min Buy / Max Sell)"),
		AVERAGE_MARKET("Average Market (5m / 1h Avg)"),
		INSTANT_BUY("Instant Buy (High Buy / High Sell)"),
		INSTANT_SELL("Instant Sell (Low Buy / Low Sell)"),
		CUSTOM("Custom User Prices");

		private final String label;

		PriceCalculationMode(String label)
		{
			this.label = label;
		}

		public String getLabel()
		{
			return label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	enum RankingMode
	{
		HIGHEST_XP_PER_HOUR("Highest XP / Hour"),
		HIGHEST_PROFIT_PER_HOUR("Highest Profit / Hour"),
		HIGHEST_PROFIT_PER_ITEM("Highest Profit / Action"),
		LOWEST_COST_PER_XP("Lowest GP / XP"),
		LOWEST_TOTAL_COST_TO_TARGET("Lowest Total Cost to Target"),
		BEST_XP_PROFIT_BALANCE("Best Balance of XP & Profit"),
		BEST_WITHIN_BUDGET("Best Method Within Budget");

		private final String label;

		RankingMode(String label)
		{
			this.label = label;
		}

		public String getLabel()
		{
			return label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigSection(
		name = "Market & Pricing",
		description = "Configure OSRS Wiki Real-time Prices API polling, price assumptions, and GE tax.",
		position = 0
	)
	String SECTION_PRICES = "prices";

	@ConfigSection(
		name = "Recommendations & Display",
		description = "Configure default ranking mode, number formatting, and method visibility.",
		position = 1
	)
	String SECTION_DISPLAY = "display";

	@ConfigSection(
		name = "Training & Budget Defaults",
		description = "Configure default GP budget, target Crafting level, and offline level fallback.",
		position = 2
	)
	String SECTION_PLANNER = "planner";

	@ConfigSection(
		name = "Market Watcher & Alerts",
		description = "Configure profit opportunity thresholds, noise filters, and alert notifications.",
		position = 3
	)
	String SECTION_WATCHER = "watcher";

	@ConfigSection(
		name = "Custom Overrides",
		description = "Persisted custom item prices and custom XP/hour rates.",
		position = 4,
		closedByDefault = true
	)
	String SECTION_OVERRIDES = "overrides";

	@Range(min = 30, max = 3600)
	@ConfigItem(
		keyName = "priceRefreshIntervalSeconds",
		name = "Price refresh interval (s)",
		description = "Background refresh interval in seconds for fetching OSRS Wiki prices (30 to 3600).",
		section = SECTION_PRICES,
		position = 1
	)
	default int priceRefreshIntervalSeconds()
	{
		return 60;
	}

	@ConfigItem(
		keyName = "priceCalculationMode",
		name = "Price calculation mode",
		description = "Select how input material costs and output selling prices are determined.",
		section = SECTION_PRICES,
		position = 2
	)
	default PriceCalculationMode priceCalculationMode()
	{
		return PriceCalculationMode.INSTANT_BUY_SELL;
	}

	@ConfigItem(
		keyName = "includeGeTax",
		name = "Apply Grand Exchange tax",
		description = "Deduct the 2% OSRS GE seller tax (0 GP under 50 GP, capped at 5M GP per item) from output revenue.",
		section = SECTION_PRICES,
		position = 3
	)
	default boolean includeGeTax()
	{
		return true;
	}

	@ConfigItem(
		keyName = "preferredRankingMode",
		name = "Default ranking mode",
		description = "Default sort and recommendation mode for CraftWise.",
		section = SECTION_DISPLAY,
		position = 1
	)
	default RankingMode preferredRankingMode()
	{
		return RankingMode.BEST_XP_PROFIT_BALANCE;
	}

	@ConfigItem(
		keyName = "compactNumbers",
		name = "Compact GP & XP numbers",
		description = "Format large numbers using K, M, and B suffixes (e.g. 1.25M gp).",
		section = SECTION_DISPLAY,
		position = 2
	)
	default boolean compactNumbers()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showFutureUnlocks",
		name = "Include future level unlocks",
		description = "Include methods above your current Crafting level in general tables.",
		section = SECTION_DISPLAY,
		position = 3
	)
	default boolean showFutureUnlocks()
	{
		return false;
	}

	@Range(min = 0, max = 2147483647)
	@ConfigItem(
		keyName = "defaultBudgetGp",
		name = "Default GP budget",
		description = "Default available budget in GP for the budget optimiser and planner.",
		section = SECTION_PLANNER,
		position = 1
	)
	default int defaultBudgetGp()
	{
		return 5_000_000;
	}

	@Range(min = 2, max = 99)
	@ConfigItem(
		keyName = "defaultTargetLevel",
		name = "Default target level",
		description = "Default target Crafting level (2 to 99).",
		section = SECTION_PLANNER,
		position = 2
	)
	default int defaultTargetLevel()
	{
		return 99;
	}

	@Range(min = 1, max = 99)
	@ConfigItem(
		keyName = "manualFallbackLevel",
		name = "Offline fallback level",
		description = "Manual Crafting level used when not logged into RuneLite or when manual override is enabled.",
		section = SECTION_PLANNER,
		position = 3
	)
	default int manualFallbackLevel()
	{
		return 70;
	}

	@ConfigItem(
		keyName = "customPricesJson",
		name = "Custom prices (JSON)",
		description = "Serialized custom item price overrides (managed from the in-plugin Settings & Calculator).",
		section = SECTION_OVERRIDES,
		position = 1
	)
	default String customPricesJson()
	{
		return "{}";
	}

	@ConfigItem(
		keyName = "customXpRatesJson",
		name = "Custom XP/hr rates (JSON)",
		description = "Serialized custom actions/hour or XP/hour overrides (managed from in-plugin Settings).",
		section = SECTION_OVERRIDES,
		position = 2
	)
	default String customXpRatesJson()
	{
		return "{}";
	}

	@ConfigItem(
		keyName = "enableMarketAlerts",
		name = "Enable Market Alerts",
		description = "Notify when watched or scanned Crafting recipes cross configured profit thresholds.",
		section = SECTION_WATCHER,
		position = 1
	)
	default boolean enableMarketAlerts()
	{
		return true;
	}

	@ConfigItem(
		keyName = "playAlertSound",
		name = "Play Alert Sound",
		description = "Play a system audio chime alongside desktop notification when an alert triggers.",
		section = SECTION_WATCHER,
		position = 2
	)
	default boolean playAlertSound()
	{
		return false;
	}

	@ConfigItem(
		keyName = "alertOnNewlyProfitable",
		name = "Alert: Newly Profitable",
		description = "Alert when a previously unprofitable recipe turns profitable.",
		section = SECTION_WATCHER,
		position = 3
	)
	default boolean alertOnNewlyProfitable()
	{
		return true;
	}

	@ConfigItem(
		keyName = "alertOnBreakEven",
		name = "Alert: Reaches Break-Even",
		description = "Alert when a recipe reaches near break-even from a loss state.",
		section = SECTION_WATCHER,
		position = 4
	)
	default boolean alertOnBreakEven()
	{
		return true;
	}

	@ConfigItem(
		keyName = "alertOnWatchedLoss",
		name = "Alert: Watched Turns Unprofitable",
		description = "Alert when a watched recipe falls below break-even into a loss.",
		section = SECTION_WATCHER,
		position = 5
	)
	default boolean alertOnWatchedLoss()
	{
		return true;
	}

	@Range(min = 1, max = 10000000)
	@ConfigItem(
		keyName = "alertMinProfitGp",
		name = "Alert Profit / Craft (GP)",
		description = "Minimum GP profit per action to trigger a profit threshold alert.",
		section = SECTION_WATCHER,
		position = 6
	)
	default int alertMinProfitGp()
	{
		return 500;
	}

	@Range(min = 1, max = 100000000)
	@ConfigItem(
		keyName = "alertMinInventoryProfitGp",
		name = "Alert Profit / Inv (GP)",
		description = "Minimum GP profit per full inventory to trigger an inventory alert.",
		section = SECTION_WATCHER,
		position = 7
	)
	default int alertMinInventoryProfitGp()
	{
		return 5000;
	}

	@Range(min = 1, max = 500)
	@ConfigItem(
		keyName = "alertMinImprovementPercent",
		name = "Alert Margin Improvement (%)",
		description = "Minimum percentage-point margin improvement to classify/alert as Improving.",
		section = SECTION_WATCHER,
		position = 8
	)
	default int alertMinImprovementPercent()
	{
		return 10;
	}

	@Range(min = 1, max = 1440)
	@ConfigItem(
		keyName = "alertCooldownMinutes",
		name = "Alert Cooldown (mins)",
		description = "Minimum cooldown per recipe/condition before another notification can fire.",
		section = SECTION_WATCHER,
		position = 9
	)
	default int alertCooldownMinutes()
	{
		return 15;
	}

	@Range(min = 1, max = 1000000)
	@ConfigItem(
		keyName = "highProfitThresholdGp",
		name = "High Profit Threshold (GP)",
		description = "Minimum net profit per action required to label an opportunity as HIGH PROFIT.",
		section = SECTION_WATCHER,
		position = 10
	)
	default int highProfitThresholdGp()
	{
		return 250;
	}
}

package com.craftwise;

import com.craftwise.bank.BankInventoryScanner;
import com.craftwise.data.CraftingDataManager;
import com.craftwise.market.MarketWatcherService.AlertEvent;
import com.craftwise.ui.CraftWisePanel;
import com.craftwise.ui.CraftWiseTheme;
import com.google.inject.Provides;
import java.awt.Toolkit;
import java.awt.TrayIcon;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Main RuneLite plugin entry point for CraftWise.
 */
@PluginDescriptor(
	name = "CraftWise",
	internalName = "craftwise",
	description = "OSRS Crafting training, profit/loss & Grand Exchange analysis tool powered by live OSRS Wiki prices",
	tags = {
		"crafting",
		"profit",
		"calculator",
		"training",
		"xp",
		"grand exchange",
		"skilling",
		"jewellery",
		"gems",
		"leather"
	}
)
public class CraftWisePlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(CraftWisePlugin.class);

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private CraftWiseConfig config;

	@Inject
	private CraftingDataManager dataManager;

	@Inject
	private Client client;

	@Inject
	private Notifier notifier;

	private CraftWisePanel panel;
	private NavigationButton navButton;

	@Provides
	CraftWiseConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CraftWiseConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		log.info("[CraftWise] Starting CraftWise plugin...");
		dataManager.setAlertDispatcher(this::handleMarketAlert);
		dataManager.startUp(getPluginDirectory());
		dataManager.scanContainersOnClientThread();

		panel = new CraftWisePanel(dataManager);
		BufferedImage icon = CraftWiseTheme.createToolbarIcon();

		navButton = NavigationButton.builder()
			.tooltip("CraftWise — Crafting Training & GE Analyzer")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();

		if (clientToolbar != null)
		{
			clientToolbar.addNavigation(navButton);
		}
	}

	@Override
	protected void shutDown() throws Exception
	{
		log.info("[CraftWise] Shutting down CraftWise plugin...");
		if (clientToolbar != null && navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		if (dataManager != null)
		{
			dataManager.setAlertDispatcher(null);
			dataManager.shutDown();
		}
		panel = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (dataManager == null || event == null)
		{
			return;
		}
		dataManager.refreshPlayerStatsFromClient();
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			dataManager.onLoggedOut();
		}
		else if (event.getGameState() == GameState.LOGGED_IN)
		{
			dataManager.scanContainersOnClientThread();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (dataManager == null || event == null || event.getItemContainer() == null)
		{
			return;
		}
		int containerId = event.getContainerId();
		if (containerId == InventoryID.BANK.getId())
		{
			boolean open = client != null && BankInventoryScanner.isBankInterfaceOpen(client);
			dataManager.scanBankContainer(event.getItemContainer(), open);
		}
		else if (containerId == InventoryID.INVENTORY.getId())
		{
			dataManager.scanInventoryContainer(event.getItemContainer());
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (dataManager == null || event == null)
		{
			return;
		}
		if (event.getGroupId() == InterfaceID.BANKMAIN && client != null)
		{
			dataManager.scanBankContainer(client.getItemContainer(InventoryID.BANK), true);
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (dataManager == null || event == null)
		{
			return;
		}
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			dataManager.onBankClosed();
		}
	}

	private void handleMarketAlert(AlertEvent alert)
	{
		if (alert == null || config == null || !config.enableMarketAlerts())
		{
			return;
		}
		if (panel != null)
		{
			javax.swing.SwingUtilities.invokeLater(() -> {
				if (panel != null)
				{
					panel.onMarketAlert(alert);
				}
			});
		}
		if (notifier != null)
		{
			notifier.notify("[CraftWise " + alert.getAlertType() + "] " + alert.getMessage(), TrayIcon.MessageType.INFO);
		}
		if (config.playAlertSound())
		{
			try
			{
				Toolkit.getDefaultToolkit().beep();
			}
			catch (Throwable ignored)
			{
			}
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (dataManager != null && event != null && event.getSkill() == Skill.CRAFTING)
		{
			dataManager.refreshPlayerStatsFromClient();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (dataManager != null)
		{
			dataManager.refreshPlayerStatsFromClient();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event == null || !CraftWiseConfig.CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}
		if (dataManager != null)
		{
			dataManager.syncFromConfig();
			dataManager.recalculateAll();
			if (panel != null)
			{
				javax.swing.SwingUtilities.invokeLater(panel::refreshAll);
			}
		}
	}

	public CraftWisePanel getPanel()
	{
		return panel;
	}

	public CraftingDataManager getDataManager()
	{
		return dataManager;
	}
}

package com.craftwise.api;

import com.craftwise.model.ItemPrice;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import lombok.Builder;
import lombok.Data;

/**
 * Parses and validates JSON payloads from the OSRS Wiki Real-time Prices API
 * and the official OSRS Wiki MediaWiki API.
 * Strictly preserves missing/null prices as {@code null} (never 0 GP).
 */
public class ApiResponseHandler
{
	@Data
	@Builder
	public static class TimeseriesPoint
	{
		private final long timestamp;
		private final Long avgHighPrice;
		private final Long avgLowPrice;
		private final long highPriceVolume;
		private final long lowPriceVolume;

		public Long getMidpointPrice()
		{
			boolean validH = avgHighPrice != null && avgHighPrice > 0L;
			boolean validL = avgLowPrice != null && avgLowPrice > 0L;
			if (validH && validL)
			{
				return Math.round((avgHighPrice + avgLowPrice) / 2.0);
			}
			return validH ? avgHighPrice : (validL ? avgLowPrice : null);
		}
	}

	public enum MarketTrend
	{
		RISING("Increasing"),
		FALLING("Decreasing"),
		STABLE("Stable"),
		VOLATILE("Volatile"),
		UNKNOWN("Insufficient Data");

		private final String label;

		MarketTrend(String label)
		{
			this.label = label;
		}

		public String getLabel()
		{
			return label;
		}
	}

	@Data
	@Builder
	public static class TimeseriesData
	{
		private final int itemId;
		private final String timestep;
		@Builder.Default
		private final List<TimeseriesPoint> points = Collections.emptyList();
		private final Long latestPrice;
		private final Long earliestPrice;
		private final Long minPrice;
		private final Long maxPrice;
		private final double averagePrice;
		private final double percentChange;
		private final double volatilityPercent;
		private final boolean unusualSpike;
		private final MarketTrend trend;
	}

	@Data
	@Builder
	public static class WikiPageInfo
	{
		private final String title;
		private final String canonicalUrl;
		private final String extract;
		private final long revisionId;
		private final boolean missing;
	}

	public Map<Integer, ItemPrice> parseLatestResponse(String json, long fetchedAtEpochSec) throws IOException
	{
		JsonObject root = parseJsonObject(json, "/latest");
		JsonObject data = getObjectOrThrow(root, "data", "/latest");

		Map<Integer, ItemPrice> result = new HashMap<>(data.size());
		for (Map.Entry<String, JsonElement> entry : data.entrySet())
		{
			Integer itemId = tryParseInt(entry.getKey());
			if (itemId == null || itemId <= 0 || !entry.getValue().isJsonObject())
			{
				continue;
			}
			JsonObject obj = entry.getValue().getAsJsonObject();
			Long high = getNullablePositiveLong(obj, "high");
			Long low = getNullablePositiveLong(obj, "low");
			long highTime = getLongOrZero(obj, "highTime");
			long lowTime = getLongOrZero(obj, "lowTime");

			result.put(itemId, ItemPrice.builder()
				.itemId(itemId)
				.highPrice(high)
				.highTime(highTime)
				.lowPrice(low)
				.lowTime(lowTime)
				.fetchedAtEpochSec(fetchedAtEpochSec)
				.stale(false)
				.build());
		}
		return result;
	}

	public Map<Integer, ItemPrice> parseMappingResponse(String json) throws IOException
	{
		if (json == null || json.trim().isEmpty())
		{
			throw new IOException("Empty /mapping response from OSRS Wiki API.");
		}
		JsonElement parsed;
		try
		{
			parsed = new JsonParser().parse(json);
		}
		catch (JsonSyntaxException ex)
		{
			throw new IOException("Malformed JSON from /mapping: " + ex.getMessage(), ex);
		}
		if (!parsed.isJsonArray())
		{
			throw new IOException("Expected JSON array from /mapping.");
		}

		JsonArray array = parsed.getAsJsonArray();
		Map<Integer, ItemPrice> map = new HashMap<>(array.size());
		for (JsonElement elem : array)
		{
			if (!elem.isJsonObject())
			{
				continue;
			}
			JsonObject obj = elem.getAsJsonObject();
			int id = (int) getLongOrZero(obj, "id");
			if (id <= 0)
			{
				continue;
			}
			String name = getStringOrNull(obj, "name");
			String examine = getStringOrNull(obj, "examine");
			boolean members = obj.has("members") && !obj.get("members").isJsonNull() && obj.get("members").getAsBoolean();
			int limit = (int) getLongOrZero(obj, "limit");
			int highAlch = (int) getLongOrZero(obj, "highalch");
			int lowAlch = (int) getLongOrZero(obj, "lowalch");
			int value = (int) getLongOrZero(obj, "value");

			map.put(id, ItemPrice.builder()
				.itemId(id)
				.name(name)
				.examine(examine)
				.members(members)
				.buyLimit(limit)
				.highAlch(highAlch)
				.lowAlch(lowAlch)
				.storeValue(value)
				.build());
		}
		return map;
	}

	public Map<String, Integer> buildNameToIdIndex(Map<Integer, ItemPrice> mapping)
	{
		if (mapping == null || mapping.isEmpty())
		{
			return Collections.emptyMap();
		}
		Map<String, Integer> index = new HashMap<>(mapping.size());
		for (ItemPrice item : mapping.values())
		{
			if (item.getName() != null && !item.getName().isEmpty())
			{
				index.putIfAbsent(item.getName().trim().toLowerCase(Locale.ROOT), item.getItemId());
			}
		}
		return index;
	}

	public void mergeRollingAverageResponse(
		Map<Integer, ItemPrice> prices,
		String json,
		boolean isFiveMinute,
		long fetchedAtEpochSec) throws IOException
	{
		if (prices == null)
		{
			return;
		}
		String endpoint = isFiveMinute ? "/5m" : "/1h";
		JsonObject root = parseJsonObject(json, endpoint);
		JsonObject data = getObjectOrThrow(root, "data", endpoint);

		for (Map.Entry<String, JsonElement> entry : data.entrySet())
		{
			Integer itemId = tryParseInt(entry.getKey());
			if (itemId == null || itemId <= 0 || !entry.getValue().isJsonObject())
			{
				continue;
			}
			JsonObject obj = entry.getValue().getAsJsonObject();
			Long avgHigh = getNullablePositiveLong(obj, "avgHighPrice");
			Long avgLow = getNullablePositiveLong(obj, "avgLowPrice");
			long volHigh = Math.max(0L, getLongOrZero(obj, "highPriceVolume"));
			long volLow = Math.max(0L, getLongOrZero(obj, "lowPriceVolume"));

			ItemPrice existing = prices.get(itemId);
			ItemPrice.ItemPriceBuilder builder = existing != null
				? existing.toBuilder()
				: ItemPrice.builder().itemId(itemId).fetchedAtEpochSec(fetchedAtEpochSec).stale(false);

			if (isFiveMinute)
			{
				builder.avg5mHigh(avgHigh).avg5mLow(avgLow).vol5mHigh(volHigh).vol5mLow(volLow);
			}
			else
			{
				builder.avg1hHigh(avgHigh).avg1hLow(avgLow).vol1hHigh(volHigh).vol1hLow(volLow);
			}
			prices.put(itemId, builder.build());
		}
	}

	public TimeseriesData parseTimeseriesResponse(String json, int itemId, String timestep) throws IOException
	{
		JsonObject root = parseJsonObject(json, "/timeseries");
		if (!root.has("data") || !root.get("data").isJsonArray())
		{
			throw new IOException("Expected 'data' array in /timeseries response.");
		}
		JsonArray array = root.getAsJsonArray("data");
		List<TimeseriesPoint> points = new ArrayList<>(array.size());
		for (JsonElement elem : array)
		{
			if (!elem.isJsonObject())
			{
				continue;
			}
			JsonObject obj = elem.getAsJsonObject();
			long ts = getLongOrZero(obj, "timestamp");
			if (ts <= 0L)
			{
				continue;
			}
			Long avgHigh = getNullablePositiveLong(obj, "avgHighPrice");
			Long avgLow = getNullablePositiveLong(obj, "avgLowPrice");
			long volHigh = Math.max(0L, getLongOrZero(obj, "highPriceVolume"));
			long volLow = Math.max(0L, getLongOrZero(obj, "lowPriceVolume"));
			points.add(TimeseriesPoint.builder()
				.timestamp(ts)
				.avgHighPrice(avgHigh)
				.avgLowPrice(avgLow)
				.highPriceVolume(volHigh)
				.lowPriceVolume(volLow)
				.build());
		}

		points.sort(Comparator.comparingLong(TimeseriesPoint::getTimestamp));
		return summarizeTimeseries(itemId, timestep, points);
	}

	public TimeseriesData summarizeTimeseries(int itemId, String timestep, List<TimeseriesPoint> points)
	{
		if (points == null || points.isEmpty())
		{
			return TimeseriesData.builder()
				.itemId(itemId)
				.timestep(timestep)
				.points(Collections.emptyList())
				.trend(MarketTrend.UNKNOWN)
				.build();
		}

		List<Long> mids = new ArrayList<>();
		long min = Long.MAX_VALUE;
		long max = Long.MIN_VALUE;
		double sum = 0.0;
		for (TimeseriesPoint p : points)
		{
			Long mid = p.getMidpointPrice();
			if (mid != null && mid > 0L)
			{
				mids.add(mid);
				if (mid < min)
				{
					min = mid;
				}
				if (mid > max)
				{
					max = mid;
				}
				sum += mid;
			}
		}

		if (mids.isEmpty())
		{
			return TimeseriesData.builder()
				.itemId(itemId)
				.timestep(timestep)
				.points(Collections.unmodifiableList(points))
				.trend(MarketTrend.UNKNOWN)
				.build();
		}

		long earliest = mids.get(0);
		long latest = mids.get(mids.size() - 1);
		double avg = sum / mids.size();
		double pctChange = earliest > 0L ? ((latest - earliest) * 100.0) / earliest : 0.0;

		double varianceSum = 0.0;
		for (Long m : mids)
		{
			double diff = m - avg;
			varianceSum += diff * diff;
		}
		double stdDev = Math.sqrt(varianceSum / mids.size());
		double volatilityPct = avg > 0.0 ? (stdDev * 100.0) / avg : 0.0;
		boolean unusual = Math.abs(pctChange) >= 12.0 || volatilityPct >= 8.0;

		MarketTrend trend;
		if (mids.size() < 3)
		{
			trend = MarketTrend.UNKNOWN;
		}
		else if (volatilityPct >= 10.0)
		{
			trend = MarketTrend.VOLATILE;
		}
		else if (pctChange >= 2.0)
		{
			trend = MarketTrend.RISING;
		}
		else if (pctChange <= -2.0)
		{
			trend = MarketTrend.FALLING;
		}
		else
		{
			trend = MarketTrend.STABLE;
		}

		return TimeseriesData.builder()
			.itemId(itemId)
			.timestep(timestep)
			.points(Collections.unmodifiableList(points))
			.earliestPrice(earliest)
			.latestPrice(latest)
			.minPrice(min)
			.maxPrice(max)
			.averagePrice(avg)
			.percentChange(pctChange)
			.volatilityPercent(volatilityPct)
			.unusualSpike(unusual)
			.trend(trend)
			.build();
	}

	public WikiPageInfo parseWikiQueryResponse(String json, String requestedTitle) throws IOException
	{
		JsonObject root = parseJsonObject(json, "wiki api.php");
		JsonObject query = root.has("query") && root.get("query").isJsonObject()
			? root.getAsJsonObject("query")
			: null;
		if (query == null || !query.has("pages") || !query.get("pages").isJsonObject())
		{
			return WikiPageInfo.builder()
				.title(requestedTitle)
				.missing(true)
				.build();
		}
		JsonObject pages = query.getAsJsonObject("pages");
		for (Map.Entry<String, JsonElement> entry : pages.entrySet())
		{
			if (!entry.getValue().isJsonObject())
			{
				continue;
			}
			JsonObject page = entry.getValue().getAsJsonObject();
			boolean missing = page.has("missing") || "-1".equals(entry.getKey());
			String title = getStringOrNull(page, "title");
			String fullUrl = getStringOrNull(page, "fullurl");
			String extract = getStringOrNull(page, "extract");
			long revId = getLongOrZero(page, "lastrevid");
			return WikiPageInfo.builder()
				.title(title != null ? title : requestedTitle)
				.canonicalUrl(fullUrl)
				.extract(extract)
				.revisionId(revId)
				.missing(missing)
				.build();
		}
		return WikiPageInfo.builder().title(requestedTitle).missing(true).build();
	}

	private static JsonObject parseJsonObject(String json, String context) throws IOException
	{
		if (json == null || json.trim().isEmpty())
		{
			throw new IOException("Empty response body from " + context);
		}
		try
		{
			JsonElement elem = new JsonParser().parse(json);
			if (!elem.isJsonObject())
			{
				throw new IOException("Expected JSON object from " + context);
			}
			return elem.getAsJsonObject();
		}
		catch (JsonSyntaxException ex)
		{
			throw new IOException("Invalid JSON from " + context + ": " + ex.getMessage(), ex);
		}
	}

	private static JsonObject getObjectOrThrow(JsonObject parent, String member, String context) throws IOException
	{
		if (!parent.has(member) || !parent.get(member).isJsonObject())
		{
			throw new IOException("Missing '" + member + "' object in " + context + " response.");
		}
		return parent.getAsJsonObject(member);
	}

	private static Long getNullablePositiveLong(JsonObject obj, String key)
	{
		if (obj == null || !obj.has(key) || obj.get(key).isJsonNull())
		{
			return null;
		}
		try
		{
			long value = obj.get(key).getAsLong();
			return value > 0L ? value : null;
		}
		catch (Exception ex)
		{
			return null;
		}
	}

	private static long getLongOrZero(JsonObject obj, String key)
	{
		if (obj == null || !obj.has(key) || obj.get(key).isJsonNull())
		{
			return 0L;
		}
		try
		{
			return obj.get(key).getAsLong();
		}
		catch (Exception ex)
		{
			return 0L;
		}
	}

	private static String getStringOrNull(JsonObject obj, String key)
	{
		if (obj == null || !obj.has(key) || obj.get(key).isJsonNull())
		{
			return null;
		}
		try
		{
			return obj.get(key).getAsString();
		}
		catch (Exception ex)
		{
			return null;
		}
	}

	private static Integer tryParseInt(String value)
	{
		try
		{
			return Integer.parseInt(value);
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}
}

package com.craftwise.api;

import com.craftwise.api.ApiResponseHandler.TimeseriesData;
import com.craftwise.model.ItemPrice;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.Reader;
import java.lang.reflect.Type;
import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantReadWriteLock;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.util.Filepath;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Thread-safe local price and timeseries cache with disk persistence and expiration tracking.
 * Ensures CraftWise never blocks on repeated identical requests and degrades gracefully offline.
 */
@Singleton
public class PriceCache
{
	private static final Logger log = LoggerFactory.getLogger(PriceCache.class);
	private static final long DEFAULT_STALE_THRESHOLD_SEC = 180L;
	private static final long DEFAULT_TIMESERIES_TTL_SEC = 300L;

	private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();
	private final Map<Integer, ItemPrice> livePrices = new ConcurrentHashMap<>();
	private final Map<Integer, ItemPrice> mappingMetadata = new ConcurrentHashMap<>();
	private final Map<String, CachedTimeseries> timeseriesCache = new ConcurrentHashMap<>();
	private volatile Filepath cacheFile;
	private final Gson gson;

	private volatile long lastPriceUpdateEpochSec = 0L;
	private volatile long lastMappingUpdateEpochSec = 0L;
	private volatile long staleThresholdSec = DEFAULT_STALE_THRESHOLD_SEC;

	private static class CachedTimeseries
	{
		final TimeseriesData data;
		final long cachedAtEpochSec;

		CachedTimeseries(TimeseriesData data, long cachedAtEpochSec)
		{
			this.data = data;
			this.cachedAtEpochSec = cachedAtEpochSec;
		}
	}

	private static class DiskCachePayload
	{
		long savedAtEpochSec;
		Map<Integer, ItemPrice> prices;
	}

	@Inject
	public PriceCache(Gson gson)
	{
		this(null, gson);
	}

	public PriceCache(Filepath cacheFile, Gson gson)
	{
		this.cacheFile = cacheFile;
		this.gson = Objects.requireNonNull(gson, "Gson must be provided via RuneLite @Inject.");
		loadFromDisk();
	}

	public synchronized void initializeStorage(Filepath cacheFile)
	{
		this.cacheFile = cacheFile;
		loadFromDisk();
	}

	public void setStaleThresholdSec(long staleThresholdSec)
	{
		this.staleThresholdSec = Math.max(30L, staleThresholdSec);
	}

	public long getLastPriceUpdateEpochSec()
	{
		return lastPriceUpdateEpochSec;
	}

	public long getLastMappingUpdateEpochSec()
	{
		return lastMappingUpdateEpochSec;
	}

	public boolean isEmpty()
	{
		lock.readLock().lock();
		try
		{
			return livePrices.isEmpty();
		}
		finally
		{
			lock.readLock().unlock();
		}
	}

	public boolean isStale(long nowEpochSec)
	{
		if (lastPriceUpdateEpochSec <= 0L)
		{
			return true;
		}
		return (nowEpochSec - lastPriceUpdateEpochSec) > staleThresholdSec;
	}

	public void savePrices(Map<Integer, ItemPrice> prices, long fetchedAtEpochSec)
	{
		if (prices == null || prices.isEmpty())
		{
			return;
		}
		lock.writeLock().lock();
		try
		{
			livePrices.clear();
			for (Map.Entry<Integer, ItemPrice> entry : prices.entrySet())
			{
				livePrices.put(entry.getKey(), entry.getValue().toBuilder().stale(false).build());
			}
			lastPriceUpdateEpochSec = fetchedAtEpochSec;
		}
		finally
		{
			lock.writeLock().unlock();
		}
		saveToDisk(fetchedAtEpochSec, prices);
	}

	public Map<Integer, ItemPrice> getPricesSnapshot(boolean markStale)
	{
		lock.readLock().lock();
		try
		{
			if (livePrices.isEmpty())
			{
				return Collections.emptyMap();
			}
			Map<Integer, ItemPrice> copy = new HashMap<>(livePrices.size());
			for (Map.Entry<Integer, ItemPrice> e : livePrices.entrySet())
			{
				ItemPrice p = e.getValue();
				copy.put(e.getKey(), markStale ? p.toBuilder().stale(true).build() : p);
			}
			return Collections.unmodifiableMap(copy);
		}
		finally
		{
			lock.readLock().unlock();
		}
	}

	public ItemPrice getPrice(int itemId)
	{
		lock.readLock().lock();
		try
		{
			return livePrices.get(itemId);
		}
		finally
		{
			lock.readLock().unlock();
		}
	}

	public void saveMapping(Map<Integer, ItemPrice> mapping, long fetchedAtEpochSec)
	{
		if (mapping == null || mapping.isEmpty())
		{
			return;
		}
		mappingMetadata.clear();
		mappingMetadata.putAll(mapping);
		lastMappingUpdateEpochSec = fetchedAtEpochSec;
	}

	public Map<Integer, ItemPrice> getMappingSnapshot()
	{
		return Collections.unmodifiableMap(new HashMap<>(mappingMetadata));
	}

	public boolean needsMappingRefresh(long nowEpochSec, long ttlSeconds)
	{
		return mappingMetadata.isEmpty() || (nowEpochSec - lastMappingUpdateEpochSec) > ttlSeconds;
	}

	public void putTimeseries(int itemId, String timestep, TimeseriesData data, long nowEpochSec)
	{
		if (data == null || timestep == null)
		{
			return;
		}
		timeseriesCache.put(itemId + ":" + timestep, new CachedTimeseries(data, nowEpochSec));
	}

	public TimeseriesData getFreshTimeseries(int itemId, String timestep, long nowEpochSec)
	{
		CachedTimeseries cached = timeseriesCache.get(itemId + ":" + timestep);
		if (cached == null)
		{
			return null;
		}
		if ((nowEpochSec - cached.cachedAtEpochSec) <= DEFAULT_TIMESERIES_TTL_SEC)
		{
			return cached.data;
		}
		return null;
	}

	public TimeseriesData getAnyTimeseries(int itemId, String timestep)
	{
		CachedTimeseries cached = timeseriesCache.get(itemId + ":" + timestep);
		return cached != null ? cached.data : null;
	}

	private void loadFromDisk()
	{
		Filepath file = this.cacheFile;
		if (file == null || !file.exists())
		{
			return;
		}
		try (Reader reader = file.openReader())
		{
			Type type = new TypeToken<DiskCachePayload>() {}.getType();
			DiskCachePayload payload = gson.fromJson(reader, type);
			if (payload != null && payload.prices != null && !payload.prices.isEmpty())
			{
				long nowSec = Instant.now().getEpochSecond();
				boolean stale = (nowSec - payload.savedAtEpochSec) > staleThresholdSec;
				lock.writeLock().lock();
				try
				{
					for (Map.Entry<Integer, ItemPrice> entry : payload.prices.entrySet())
					{
						if (entry.getValue() != null)
						{
							livePrices.put(entry.getKey(), entry.getValue().toBuilder().stale(stale).build());
						}
					}
					lastPriceUpdateEpochSec = payload.savedAtEpochSec;
				}
				finally
				{
					lock.writeLock().unlock();
				}
				log.debug("[CraftWise] Loaded {} cached item prices from {}", payload.prices.size(), cacheFile);
			}
		}
		catch (Exception ex)
		{
			log.debug("[CraftWise] Could not load disk price cache: {}", ex.getMessage());
		}
	}

	private void saveToDisk(long savedAtEpochSec, Map<Integer, ItemPrice> prices)
	{
		Filepath file = this.cacheFile;
		if (file == null)
		{
			return;
		}
		try
		{
			Filepath parent = file.getParent();
			if (parent != null && !parent.exists())
			{
				parent.createDirectories();
			}
			DiskCachePayload payload = new DiskCachePayload();
			payload.savedAtEpochSec = savedAtEpochSec;
			payload.prices = new HashMap<>(prices);
			file.write(gson.toJson(payload));
		}
		catch (IOException ex)
		{
			log.debug("[CraftWise] Unable to persist disk price cache: {}", ex.getMessage());
		}
	}
}

package com.craftwise.api;

import com.craftwise.api.ApiResponseHandler.WikiPageInfo;
import java.io.IOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Client for the official Old School RuneScape Wiki MediaWiki API
 * ({@code https://oldschool.runescape.wiki/api.php}).
 * Used for verifying canonical Wiki references and fetching page summaries on demand.
 * Caches responses aggressively to avoid redundant requests.
 */
@Singleton
public class WikiDataClient
{
	private static final Logger log = LoggerFactory.getLogger(WikiDataClient.class);
	public static final String WIKI_API_URL = "https://oldschool.runescape.wiki/api.php";

	private final OkHttpClient httpClient;
	private final ApiResponseHandler responseHandler;
	private final Map<String, WikiPageInfo> pageCache = new ConcurrentHashMap<>();

	@Inject
	public WikiDataClient(OkHttpClient httpClient)
	{
		if (httpClient == null)
		{
			throw new IllegalArgumentException("OkHttpClient must be provided via RuneLite @Inject.");
		}
		this.httpClient = httpClient.newBuilder()
			.connectTimeout(8, TimeUnit.SECONDS)
			.readTimeout(12, TimeUnit.SECONDS)
			.build();
		this.responseHandler = new ApiResponseHandler();
	}

	public WikiPageInfo getCachedPageInfo(String pageTitle)
	{
		if (pageTitle == null)
		{
			return null;
		}
		return pageCache.get(pageTitle.trim());
	}

	/**
	 * Queries the OSRS Wiki API for canonical page info and summary extract.
	 * Returns cached data immediately if already fetched during this session.
	 */
	public WikiPageInfo fetchPageInfo(String pageTitle) throws IOException
	{
		if (pageTitle == null || pageTitle.trim().isEmpty())
		{
			throw new IllegalArgumentException("Page title must not be empty.");
		}
		String normalized = pageTitle.trim();
		WikiPageInfo cached = pageCache.get(normalized);
		if (cached != null)
		{
			return cached;
		}

		String encodedTitle = URLEncoder.encode(normalized, StandardCharsets.UTF_8);
		String url = WIKI_API_URL
			+ "?action=query&prop=info|extracts&inprop=url&exintro=1&explaintext=1&redirects=1&format=json&titles="
			+ encodedTitle;

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", WikiPriceClient.USER_AGENT)
			.header("Accept", "application/json")
			.get()
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful())
			{
				throw new IOException("OSRS Wiki API returned HTTP " + response.code() + " for " + normalized);
			}
			ResponseBody body = response.body();
			if (body == null)
			{
				throw new IOException("Empty response from OSRS Wiki API for " + normalized);
			}
			WikiPageInfo info = responseHandler.parseWikiQueryResponse(body.string(), normalized);
			pageCache.put(normalized, info);
			return info;
		}
		catch (IOException ex)
		{
			log.debug("[CraftWise] WikiDataClient query failed for '{}': {}", normalized, ex.getMessage());
			throw ex;
		}
	}
}

package com.craftwise.api;

import com.craftwise.api.ApiResponseHandler.TimeseriesData;
import com.craftwise.model.ItemPrice;
import java.io.IOException;
import java.time.Instant;
import java.util.Collections;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Official OSRS Wiki Real-time Prices API client for CraftWise.
 * Supports bulk /latest, /mapping, /5m, /1h, and /timeseries endpoints.
 * Attempts /api/v2/osrs and seamlessly falls back to /api/v1/osrs if v2 is unavailable.
 */
@Singleton
public class WikiPriceClient
{
	private static final Logger log = LoggerFactory.getLogger(WikiPriceClient.class);

	public static final String V2_BASE_URL = "https://prices.runescape.wiki/api/v2/osrs";
	public static final String V1_BASE_URL = "https://prices.runescape.wiki/api/v1/osrs";
	public static final String USER_AGENT =
		"CraftWise-RuneLite-Plugin/1.0.0 (OSRS Crafting Profit & Training Analyzer)";

	private static final long MAPPING_TTL_SECONDS = 6L * 3600L;

	private final OkHttpClient httpClient;
	private final PriceCache priceCache;
	private final ApiResponseHandler responseHandler;

	private volatile String activeBaseUrl = V2_BASE_URL;
	private volatile boolean liveConnected = false;
	private volatile String statusMessage = "Initializing OSRS Wiki Price API...";
	private volatile Map<String, Integer> nameToIdIndex = Collections.emptyMap();

	@Inject
	public WikiPriceClient(OkHttpClient httpClient, PriceCache priceCache)
	{
		this(httpClient, priceCache, new ApiResponseHandler());
	}

	public WikiPriceClient(OkHttpClient httpClient, PriceCache priceCache, ApiResponseHandler responseHandler)
	{
		if (httpClient == null)
		{
			throw new IllegalArgumentException("OkHttpClient must be provided via RuneLite @Inject.");
		}
		if (priceCache == null)
		{
			throw new IllegalArgumentException("PriceCache must be provided.");
		}
		this.httpClient = httpClient.newBuilder()
			.connectTimeout(8, TimeUnit.SECONDS)
			.readTimeout(12, TimeUnit.SECONDS)
			.writeTimeout(8, TimeUnit.SECONDS)
			.build();
		this.priceCache = priceCache;
		this.responseHandler = responseHandler != null ? responseHandler : new ApiResponseHandler();
	}

	public String getActiveBaseUrl()
	{
		return activeBaseUrl;
	}

	public boolean isLiveConnected()
	{
		return liveConnected;
	}

	public String getStatusMessage()
	{
		return statusMessage;
	}

	public PriceCache getPriceCache()
	{
		return priceCache;
	}

	public Map<String, Integer> getNameToIdIndex()
	{
		return nameToIdIndex;
	}

	/**
	 * Fetches bulk GE pricing from /latest, /mapping (if expired/empty), /5m, and /1h.
	 * Updates {@link PriceCache} on success. On failure, throws IOException after updating status.
	 */
	public synchronized Map<Integer, ItemPrice> fetchAllPrices() throws IOException
	{
		long nowSec = Instant.now().getEpochSecond();
		try
		{
			String latestJson = executeWithFallback("/latest");
			Map<Integer, ItemPrice> prices = responseHandler.parseLatestResponse(latestJson, nowSec);
			if (prices.isEmpty())
			{
				throw new IOException("OSRS Wiki /latest returned 0 item entries.");
			}

			if (priceCache.needsMappingRefresh(nowSec, MAPPING_TTL_SECONDS))
			{
				try
				{
					String mappingJson = executeWithFallback("/mapping");
					Map<Integer, ItemPrice> mapping = responseHandler.parseMappingResponse(mappingJson);
					if (!mapping.isEmpty())
					{
						priceCache.saveMapping(mapping, nowSec);
						nameToIdIndex = responseHandler.buildNameToIdIndex(mapping);
					}
				}
				catch (Exception ex)
				{
					log.debug("[CraftWise] Non-fatal /mapping fetch error: {}", ex.getMessage());
				}
			}

			mergeMappingIntoPrices(prices, priceCache.getMappingSnapshot());

			try
			{
				String fiveMinJson = executeWithFallback("/5m");
				responseHandler.mergeRollingAverageResponse(prices, fiveMinJson, true, nowSec);
			}
			catch (Exception ex)
			{
				log.debug("[CraftWise] Non-fatal /5m fetch error: {}", ex.getMessage());
			}

			try
			{
				String oneHourJson = executeWithFallback("/1h");
				responseHandler.mergeRollingAverageResponse(prices, oneHourJson, false, nowSec);
			}
			catch (Exception ex)
			{
				log.debug("[CraftWise] Non-fatal /1h fetch error: {}", ex.getMessage());
			}

			priceCache.savePrices(prices, nowSec);
			liveConnected = true;
			statusMessage = "Live (" + prices.size() + " items via OSRS Wiki API)";
			return priceCache.getPricesSnapshot(false);
		}
		catch (IOException ex)
		{
			liveConnected = false;
			statusMessage = "Offline — Using cached prices (" + ex.getMessage() + ")";
			throw ex;
		}
	}

	/**
	 * Fetches /timeseries?timestep=...&id=... with in-memory TTL caching.
	 */
	public TimeseriesData fetchTimeseries(int itemId, String timestep) throws IOException
	{
		String safeStep = (timestep == null || timestep.trim().isEmpty()) ? "1h" : timestep.trim();
		long nowSec = Instant.now().getEpochSecond();

		TimeseriesData fresh = priceCache.getFreshTimeseries(itemId, safeStep, nowSec);
		if (fresh != null)
		{
			return fresh;
		}

		try
		{
			String endpoint = "/timeseries?timestep=" + safeStep + "&id=" + itemId;
			String json = executeWithFallback(endpoint);
			TimeseriesData data = responseHandler.parseTimeseriesResponse(json, itemId, safeStep);
			priceCache.putTimeseries(itemId, safeStep, data, nowSec);
			return data;
		}
		catch (IOException ex)
		{
			TimeseriesData stale = priceCache.getAnyTimeseries(itemId, safeStep);
			if (stale != null)
			{
				return stale;
			}
			throw ex;
		}
	}

	private void mergeMappingIntoPrices(Map<Integer, ItemPrice> prices, Map<Integer, ItemPrice> mapping)
	{
		if (mapping == null || mapping.isEmpty())
		{
			return;
		}
		for (Map.Entry<Integer, ItemPrice> entry : mapping.entrySet())
		{
			int id = entry.getKey();
			ItemPrice meta = entry.getValue();
			ItemPrice current = prices.get(id);
			if (current != null)
			{
				prices.put(id, current.toBuilder()
					.name(meta.getName())
					.examine(meta.getExamine())
					.members(meta.isMembers())
					.buyLimit(meta.getBuyLimit())
					.highAlch(meta.getHighAlch())
					.lowAlch(meta.getLowAlch())
					.storeValue(meta.getStoreValue())
					.build());
			}
			else
			{
				prices.put(id, meta);
			}
		}
	}

	private String executeWithFallback(String endpointPath) throws IOException
	{
		try
		{
			return executeGetWithRetry(activeBaseUrl + endpointPath);
		}
		catch (IOException primaryEx)
		{
			if (V2_BASE_URL.equals(activeBaseUrl))
			{
				log.debug("[CraftWise] v2 endpoint failed ({}), falling back to v1 API...", primaryEx.getMessage());
				String body = executeGetWithRetry(V1_BASE_URL + endpointPath);
				activeBaseUrl = V1_BASE_URL;
				return body;
			}
			throw primaryEx;
		}
	}

	private String executeGetWithRetry(String url) throws IOException
	{
		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.header("Accept", "application/json")
			.get()
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			int code = response.code();
			if (response.isSuccessful())
			{
				ResponseBody body = response.body();
				if (body == null)
				{
					throw new IOException("Empty HTTP body from " + url);
				}
				return body.string();
			}

			if (code == 429)
			{
				throw new IOException("HTTP 429 rate-limited on " + url);
			}
			throw new IOException("HTTP " + code + " for " + url);
		}
	}
}

