	/**
	 * Matches a single recipe against player-owned materials.
	 * Distinguishes reusable tools/moulds from consumed ingredients and computes shortages cleanly.
	 */
	public static BankRecipeMatch matchRecipe(
		CraftingRecipe recipe,
		CraftingResult marketResult,
		SnapshotView snapshot,
		long requestedTargetCrafts,
		boolean includeNotedFromInventory,
		Map<Integer, ItemPrice> prices,
		Map<String, Integer> nameToIdIndex,
		PriceCalculationMode mode,
		Map<Integer, CustomPriceOverride> customPrices)
	{
		if (recipe == null)
		{
			return null;
		}
		long targetCrafts = requestedTargetCrafts > 0L
			? requestedTargetCrafts
			: Math.max(1L, InventoryCalculator.calculateCraftsPerInventory(recipe));

		List<RecipeInput> inputs = recipe.getInputs();
		List<MaterialAllocation> allocations = new ArrayList<>();
		java.util.Set<Integer> checkedToolIds = new java.util.HashSet<>();
		List<String> missingToolNames = new ArrayList<>();
		long maxUsableCrafts = Long.MAX_VALUE;
		long invOnlyCrafts = Long.MAX_VALUE;
		long notedIncludedCrafts = Long.MAX_VALUE;
		long additionalCostForTarget = 0L;
		boolean additionalPricesComplete = true;

		for (RecipeInput in : inputs)
		{
			OwnedItemCount count = snapshot != null ? snapshot.getCount(in.getItemId()) : null;
			long bankQ = count != null ? count.getBankQty() : 0L;
			long invU = count != null ? count.getInventoryUnnotedQty() : 0L;
			long invN = count != null ? count.getInventoryNotedQty() : 0L;
			long man = count != null ? count.getManualAdjustmentQty() : 0L;

			long usable = bankQ + invU + man + (includeNotedFromInventory ? invN : 0L);
			long allIncludingNoted = bankQ + invU + invN + man;

			if (!in.isConsumed())
			{
				checkedToolIds.add(in.getItemId());
				// Reusable tool/mould placed directly in inputs -> never scales with craft count
				long reqTool = (long) Math.ceil(Math.max(1.0, in.getQuantity()));
				long missingTool = Math.max(0L, reqTool - usable);
				Long buyP = resolveUnitBuyPrice(in.getItemId(), in.getItemName(), prices, nameToIdIndex, mode, customPrices);
				long toolCost = 0L;
				if (missingTool > 0L)
				{
					missingToolNames.add(in.getItemName() != null ? in.getItemName() : ("Item #" + in.getItemId()));
					if (buyP != null && buyP > 0L)
					{
						toolCost = missingTool * buyP;
						additionalCostForTarget += toolCost;
					}
					else if (in.getItemId() != ItemID.COINS_995)
					{
						additionalPricesComplete = false;
					}
				}
				if (usable < reqTool)
				{
					maxUsableCrafts = 0L;
				}
				if (invU < reqTool)
				{
					invOnlyCrafts = 0L;
				}
				if (allIncludingNoted < reqTool)
				{
					notedIncludedCrafts = 0L;
				}
				allocations.add(MaterialAllocation.builder()
					.itemId(in.getItemId())
					.itemName(in.getItemName())
					.consumed(false)
					.requiredPerCraft(in.getQuantity())
					.ownedBankQty(bankQ)
					.ownedInvUnnotedQty(invU)
					.ownedInvNotedQty(invN)
					.combinedUsableQty(usable)
					.remainingAfterMaxCrafts(usable)
					.missingForTargetCrafts(missingTool)
					.estimatedUnitBuyPrice(buyP)
					.additionalCostForTargetGp(toolCost)
					.build());
				continue;
			}

			double perCraft = Math.max(1e-9, in.getQuantity());
			long cUsable = (long) Math.floor((usable + 1e-9) / perCraft);
			long cInv = (long) Math.floor((invU + 1e-9) / perCraft);
			long cAll = (long) Math.floor((allIncludingNoted + 1e-9) / perCraft);

			maxUsableCrafts = Math.min(maxUsableCrafts, cUsable);
			invOnlyCrafts = Math.min(invOnlyCrafts, cInv);
			notedIncludedCrafts = Math.min(notedIncludedCrafts, cAll);

			long neededForTarget = (long) Math.ceil((perCraft * targetCrafts) - 1e-9);
			long missingForTarget = Math.max(0L, neededForTarget - usable);
			Long buyP = in.getItemId() == ItemID.COINS_995
				? Long.valueOf(1L)
				: resolveUnitBuyPrice(in.getItemId(), in.getItemName(), prices, nameToIdIndex, mode, customPrices);

			long addCost = 0L;
			if (missingForTarget > 0L)
			{
				if (buyP != null && buyP > 0L)
				{
					addCost = missingForTarget * buyP;
					additionalCostForTarget += addCost;
				}
				else
				{
					additionalPricesComplete = false;
				}
			}

			allocations.add(MaterialAllocation.builder()
				.itemId(in.getItemId())
				.itemName(in.getItemName())
				.consumed(true)
				.requiredPerCraft(perCraft)
				.ownedBankQty(bankQ)
				.ownedInvUnnotedQty(invU)
				.ownedInvNotedQty(invN)
				.combinedUsableQty(usable)
				.remainingAfterMaxCrafts(0L) // populated below once overall bottleneck is known
				.missingForTargetCrafts(missingForTarget)
				.estimatedUnitBuyPrice(buyP)
				.additionalCostForTargetGp(addCost)
				.build());
		}

		// Also verify reusable tools & moulds declared on CraftingRecipe.requiredTools / requiredMoulds
		for (String toolName : recipe.getAllToolsAndMoulds())
		{
			if (toolName == null || toolName.trim().isEmpty())
			{
				continue;
			}
			Integer toolId = resolveToolItemId(toolName, nameToIdIndex);
			if (toolId == null || !checkedToolIds.add(toolId))
			{
				continue;
			}
			OwnedItemCount count = snapshot != null ? snapshot.getCount(toolId) : null;
			long bankQ = count != null ? count.getBankQty() : 0L;
			long invU = count != null ? count.getInventoryUnnotedQty() : 0L;
			long invN = count != null ? count.getInventoryNotedQty() : 0L;
			long man = count != null ? count.getManualAdjustmentQty() : 0L;

			long usable = bankQ + invU + man + (includeNotedFromInventory ? invN : 0L);
			long allIncludingNoted = bankQ + invU + invN + man;
			long missingTool = usable < 1L ? 1L : 0L;
			Long buyP = resolveUnitBuyPrice(toolId, toolName, prices, nameToIdIndex, mode, customPrices);
			long toolCost = 0L;
			if (missingTool > 0L)
			{
				missingToolNames.add(toolName);
				if (buyP != null && buyP > 0L)
				{
					toolCost = buyP;
					additionalCostForTarget += toolCost;
				}
				maxUsableCrafts = 0L;
			}
			if (invU < 1L)
			{
				invOnlyCrafts = 0L;
			}
			if (allIncludingNoted < 1L)
			{
				notedIncludedCrafts = 0L;
			}
			allocations.add(MaterialAllocation.builder()
				.itemId(toolId)
				.itemName(toolName)
				.consumed(false)
				.requiredPerCraft(1.0)
				.ownedBankQty(bankQ)
				.ownedInvUnnotedQty(invU)
				.ownedInvNotedQty(invN)
				.combinedUsableQty(usable)
				.remainingAfterMaxCrafts(usable)
				.missingForTargetCrafts(missingTool)
				.estimatedUnitBuyPrice(buyP)
				.additionalCostForTargetGp(toolCost)
				.build());
		}

		if (maxUsableCrafts == Long.MAX_VALUE)
		{
			maxUsableCrafts = 0L;
		}
		if (invOnlyCrafts == Long.MAX_VALUE)
		{
			invOnlyCrafts = 0L;
		}
		if (notedIncludedCrafts == Long.MAX_VALUE)
		{
			notedIncludedCrafts = 0L;
		}

		// Populate true remaining quantities after performing maxUsableCrafts
		List<MaterialAllocation> finalAllocs = new ArrayList<>(allocations.size());
		for (MaterialAllocation a : allocations)
		{
			long used = a.isConsumed() ? Math.round(maxUsableCrafts * a.getRequiredPerCraft()) : 0L;
			long rem = Math.max(0L, a.getCombinedUsableQty() - used);
			finalAllocs.add(MaterialAllocation.builder()
				.itemId(a.getItemId())
				.itemName(a.getItemName())
				.consumed(a.isConsumed())
				.requiredPerCraft(a.getRequiredPerCraft())
				.ownedBankQty(a.getOwnedBankQty())
				.ownedInvUnnotedQty(a.getOwnedInvUnnotedQty())
				.ownedInvNotedQty(a.getOwnedInvNotedQty())
				.combinedUsableQty(a.getCombinedUsableQty())
				.remainingAfterMaxCrafts(rem)
				.missingForTargetCrafts(a.getMissingForTargetCrafts())
				.estimatedUnitBuyPrice(a.getEstimatedUnitBuyPrice())
				.additionalCostForTargetGp(a.getAdditionalCostForTargetGp())
				.build());
		}

		// Craftable capacity coverage against targetCrafts (never just ingredient-type count)
		double coveragePct = targetCrafts > 0L
			? Math.min(100.0, (maxUsableCrafts * 100.0) / targetCrafts)
			: 0.0;
		// Also give partial credit when >0% of target inputs exist so multi-input near-ready recipes surface cleanly
		if (coveragePct == 0.0 && maxUsableCrafts == 0L && !inputs.isEmpty())
		{
			double minRatio = 1.0;
			double avgRatio = 0.0;
			int consumedCount = 0;
			for (MaterialAllocation a : finalAllocs)
			{
				if (a.isConsumed() && a.getRequiredPerCraft() > 0.0)
				{
					double req = a.getRequiredPerCraft() * targetCrafts;
					double r = Math.min(1.0, a.getCombinedUsableQty() / req);
					minRatio = Math.min(minRatio, r);
					avgRatio += r;
					consumedCount++;
				}
			}
			if (consumedCount > 0 && (avgRatio / consumedCount) > 0.0)
			{
				// Partial materials exist for at least 1 ingredient, bottleneck currently 0 complete crafts
				coveragePct = Math.min(49.0, (avgRatio / consumedCount) * 49.0);
			}
		}
		CoverageTier tier = classifyCoverage(maxUsableCrafts, targetCrafts, coveragePct);

		double xpFromStock = maxUsableCrafts * recipe.getXpPerAction();
		double profFromStock = (marketResult != null && marketResult.isPriceDataComplete())
			? maxUsableCrafts * marketResult.getProfitPerCraft()
			: 0.0;
		double revFromStock = (marketResult != null && marketResult.isPriceDataComplete())
			? maxUsableCrafts * marketResult.getGrossRevenuePerCraft()
			: 0.0;
		double taxFromStock = (marketResult != null && marketResult.isPriceDataComplete())
			? maxUsableCrafts * marketResult.getGeTaxPerCraft()
			: 0.0;

		return BankRecipeMatch.builder()
			.recipe(recipe)
			.marketResult(marketResult)
			.maxCompleteCrafts(maxUsableCrafts)
			.readyInventoryOnlyCrafts(invOnlyCrafts)
			.maxCraftsIncludingNoted(notedIncludedCrafts)
			.targetCraftsEvaluated(targetCrafts)
			.coveragePercent(coveragePct)
			.coverageTier(tier)
			.totalXpFromOwnedStock(xpFromStock)
			.totalProfitFromOwnedStock(profFromStock)
			.expectedRevenueFromOwnedStock(revFromStock)
			.geTaxFromOwnedStock(taxFromStock)
			.missingForTargetCostGp(additionalCostForTarget)
			.additionalPricesComplete(additionalPricesComplete)
			.missingTools(!missingToolNames.isEmpty())
			.missingToolNames(Collections.unmodifiableList(missingToolNames))
			.allocations(Collections.unmodifiableList(finalAllocs))
			.build();
	}

	private static Integer resolveToolItemId(String toolName, Map<String, Integer> nameToIdIndex)
	{
		String norm = toolName.trim().toLowerCase(java.util.Locale.US);
		Integer known = TOOL_NAME_TO_ID.get(norm);
		if (known != null)
		{
			return known;
		}
		if (nameToIdIndex != null)
		{
			return nameToIdIndex.get(norm);
		}
		return null;
	}

	private static CoverageTier classifyCoverage(long maxCompleteCrafts, long targetCrafts, double pct)
	{
		if (targetCrafts > 0L && maxCompleteCrafts >= targetCrafts)
		{
			return CoverageTier.READY_100;
		}
		if (pct >= 75.0 && maxCompleteCrafts > 0L)
		{
			return CoverageTier.READY_75;
		}
		if (pct > 0.0 || maxCompleteCrafts > 0L)
		{
			return CoverageTier.PARTIAL;
		}
		return CoverageTier.NOT_READY;
	}

	public static List<BankRecipeMatch> matchAndRankAll(
		List<CraftingResult> marketResults,
		SnapshotView snapshot,
		long targetCraftsPerRecipe,
		boolean includeNotedFromInventory,
		int playerLevel,
		boolean membersAllowed,
		boolean includeQuestLocked,
		boolean includeUnlockRequired,
		boolean craftableNowOnly,
		boolean profitableWithBankOnly,
		BankRecommendationMode rankMode,
		Map<Integer, ItemPrice> prices,
		Map<String, Integer> nameToIdIndex,
		PriceCalculationMode mode,
		Map<Integer, CustomPriceOverride> customPrices)
	{
		if (marketResults == null || marketResults.isEmpty())
		{
			return Collections.emptyList();
		}

		List<BankRecipeMatch> matches = new ArrayList<>();
		for (CraftingResult res : marketResults)
		{
			if (res == null || res.getRecipe() == null)
			{
				continue;
			}
			CraftingRecipe rec = res.getRecipe();
			if (rec.getVerificationStatus() == VerificationStatus.UNSUPPORTED)
			{
				continue;
			}
			if (rec.getRequiredLevel() > playerLevel)
			{
				continue;
			}
			if (!membersAllowed && rec.isMembers())
			{
				continue;
			}
			if (!includeQuestLocked && rec.hasQuestRequirement())
			{
				continue;
			}
			if (!includeUnlockRequired && rec.hasUnlockRequirement())
			{
				continue;
			}

			BankRecipeMatch m = matchRecipe(
				rec, res, snapshot, targetCraftsPerRecipe, includeNotedFromInventory,
				prices, nameToIdIndex, mode, customPrices);
			if (m == null)
			{
				continue;
			}
			if (craftableNowOnly && !m.isCraftableNow())
			{
				continue;
			}
			if (profitableWithBankOnly && !m.isProfitableWithOwnedStock())
			{
				continue;
			}
			matches.add(m);
		}

		BankRecommendationMode effectiveRank = rankMode != null ? rankMode : BankRecommendationMode.BEST_WITH_MY_BANK;
		switch (effectiveRank)
		{
			case MOST_XP_FROM_BANK:
				matches.sort(Comparator.comparingDouble(BankRecipeMatch::getTotalXpFromOwnedStock).reversed());
				break;
			case MOST_PROFIT_FROM_BANK:
				matches.sort(Comparator.comparingDouble(BankRecipeMatch::getTotalProfitFromOwnedStock).reversed());
				break;
			case LEAST_ADDITIONAL_GP:
				matches.sort(Comparator
					.comparingDouble((BankRecipeMatch m) -> m.isCraftableNow() ? 0 : 1)
					.thenComparingLong(BankRecipeMatch::getMissingForTargetCostGp)
					.thenComparing(Comparator.comparingDouble(BankRecipeMatch::getTotalXpFromOwnedStock).reversed()));
				break;
			case BEST_MATERIAL_CONVERSION:
				matches.sort(Comparator.comparingDouble((BankRecipeMatch m) ->
					m.getMarketResult() != null && m.getMarketResult().isPriceDataComplete()
						? m.getMarketResult().getProfitPerCraft()
						: -1e9).reversed());
				break;
			case BEST_WITH_MY_BANK:
			default:
				matches.sort(Comparator
					.comparingInt((BankRecipeMatch m) -> m.isCraftableNow() ? 0 : 1)
					.thenComparing(Comparator.comparingDouble((BankRecipeMatch m) ->
						(m.getTotalXpFromOwnedStock() * 0.6) + Math.max(-50_000.0, m.getTotalProfitFromOwnedStock())).reversed()));
				break;
		}
		return Collections.unmodifiableList(matches);
	}

	/**
	 * Feature 2.6: Analyzes owned Crafting materials directly: SELL MATERIALS vs CRAFT MATERIALS.
	 */
	public static List<BankMaterialValueEntry> analyzeOwnedMaterials(
		SnapshotView snapshot,
		List<CraftingResult> marketResults,
		int playerLevel,
		boolean includeNotedFromInventory,
		Map<Integer, ItemPrice> prices,
		Map<String, Integer> nameToIdIndex,
		PriceCalculationMode mode,
		boolean includeGeTax,
		Map<Integer, CustomPriceOverride> customPrices)
	{
		if (snapshot == null || snapshot.getItems().isEmpty())
		{
			return Collections.emptyList();
		}

		// Index verified recipes consuming each itemId
		Map<Integer, List<CraftingResult>> consumers = new LinkedHashMap<>();
		for (CraftingResult r : marketResults)
		{
			if (r == null || r.getRecipe() == null)
			{
				continue;
			}
			CraftingRecipe rec = r.getRecipe();
			if (rec.getVerificationStatus() == VerificationStatus.UNSUPPORTED || rec.getRequiredLevel() > playerLevel)
			{
				continue;
			}
			for (RecipeInput in : rec.getInputs())
			{
				if (in.isConsumed() && in.getItemId() != ItemID.COINS_995)
				{
					consumers.computeIfAbsent(in.getItemId(), k -> new ArrayList<>()).add(r);
				}
			}
		}

		List<BankMaterialValueEntry> entries = new ArrayList<>();
		for (OwnedItemCount count : snapshot.getItems().values())
		{
			List<CraftingResult> uses = consumers.get(count.getItemId());
			if (uses == null || uses.isEmpty())
			{
				continue;
			}
			long ownedUsable = includeNotedFromInventory ? count.getCombinedIncludingNotedQty() : count.getCombinedUsableQty();
			if (ownedUsable <= 0L)
			{
				continue;
			}

			ItemPrice ip = ProfitCalculator.resolveItemPrice(count.getItemId(), count.getItemName(), prices, nameToIdIndex);
			Long sellP = resolveUnitSellPrice(ip, mode, customPrices, count.getItemId());
			long sellNetValue = 0L;
			if (sellP != null && sellP > 0L)
			{
				long taxUnit = GETransactionCalculator.calculateTaxPerItem(sellP, count.getItemId(), false, includeGeTax);
				sellNetValue = (sellP - taxUnit) * ownedUsable;
			}

			// Find highest net-value conversion among eligible recipes using this item
			CraftingResult bestUse = null;
			long bestCraftNetTotal = Long.MIN_VALUE;
			long bestCraftsPossible = 0L;
			long bestSecondaryAddCost = 0L;

			for (CraftingResult cr : uses)
			{
				if (!cr.isPriceDataComplete())
				{
					continue;
				}
				double qtyPerCraft = 1.0;
				for (RecipeInput in : cr.getRecipe().getInputs())
				{
					if (in.isConsumed() && in.getItemId() == count.getItemId())
					{
						qtyPerCraft = Math.max(1e-6, in.getQuantity());
						break;
					}
				}
				long craftsFromThisItem = (long) Math.floor((ownedUsable + 1e-9) / qtyPerCraft);
				if (craftsFromThisItem <= 0L)
				{
					continue;
				}
				long grossCraftNet = Math.round(craftsFromThisItem * cr.getNetRevenuePerCraft());
				long addSecCost = 0L;
				for (RecipeInput in : cr.getRecipe().getInputs())
				{
					if (!in.isConsumed() || in.getItemId() == count.getItemId())
					{
						continue;
					}
					long neededSec = Math.round(craftsFromThisItem * in.getQuantity());
					OwnedItemCount secOwned = snapshot.getCount(in.getItemId());
					long haveSec = secOwned != null
						? (includeNotedFromInventory ? secOwned.getCombinedIncludingNotedQty() : secOwned.getCombinedUsableQty())
						: 0L;
					long buySec = Math.max(0L, neededSec - haveSec);
					if (buySec > 0L)
					{
						Long secP = in.getItemId() == ItemID.COINS_995
							? Long.valueOf(1L)
							: resolveUnitBuyPrice(in.getItemId(), in.getItemName(), prices, nameToIdIndex, mode, customPrices);
						if (secP != null && secP > 0L)
						{
							addSecCost += buySec * secP;
						}
					}
				}
				long netAfterSec = grossCraftNet - addSecCost;
				if (netAfterSec > bestCraftNetTotal)
				{
					bestCraftNetTotal = netAfterSec;
					bestUse = cr;
					bestCraftsPossible = craftsFromThisItem;
					bestSecondaryAddCost = addSecCost;
				}
			}

			String bestName = bestUse != null ? bestUse.getRecipe().getName() : uses.get(0).getRecipe().getName();
			String bestId = bestUse != null ? bestUse.getRecipe().getId() : uses.get(0).getRecipe().getId();
			long advantage = (bestUse != null && sellP != null) ? (bestCraftNetTotal - sellNetValue) : 0L;
			String label = (bestUse == null || sellP == null)
				? "MISSING MARKET"
				: (advantage >= 0L ? "CRAFT (Est.)" : "SELL RAW (Est.)");

			entries.add(BankMaterialValueEntry.builder()
				.itemId(count.getItemId())
				.itemName(count.getItemName())
				.bankQty(count.getBankQty())
				.invUnnotedQty(count.getInventoryUnnotedQty())
				.invNotedQty(count.getInventoryNotedQty())
				.totalOwnedQty(ownedUsable)
				.unitSellPrice(sellP)
				.netSellValueAfterTaxGp(sellNetValue)
				.bestRecipeId(bestId)
				.bestRecipeName(bestName)
				.craftableUsingOwnedQty(bestCraftsPossible)
				.estimatedCraftProfitGp(bestUse != null ? bestCraftNetTotal : 0L)
				.additionalSecondaryCostGp(bestSecondaryAddCost)
				.craftAdvantageVsSellingGp(advantage)
				.comparisonLabel(label)
				.estimateNote("Assumes current GE prices; execution not guaranteed.")
				.build());
		}

		entries.sort(Comparator.comparingLong(BankMaterialValueEntry::getNetSellValueAfterTaxGp).reversed());
		return Collections.unmodifiableList(entries);
	}

	/**
	 * Feature 2.5: Compares Plan A (consume eligible bank stock first without double-counting)
	 * vs Plan B (ignore existing bank stock & follow optimal cheapest market route).
	 */
	public static BankTrainingComparison compareBankTrainingPlans(
		SnapshotView snapshot,
		List<CraftingResult> allResults,
		int startLevel,
		long startXp,
		int targetLevel,
		long budgetGp,
		int temporaryBoost,
		boolean membersAllowed,
		boolean includeQuestLocked,
		boolean includeUnlockRequired,
		boolean includeNotedFromInventory,
		boolean includeGeTax)
	{
		return compareBankTrainingPlans(
			snapshot, allResults, startLevel, startXp, targetLevel, budgetGp, temporaryBoost,
			membersAllowed, includeQuestLocked, includeUnlockRequired, includeNotedFromInventory, includeGeTax,
			Collections.emptyMap(), Collections.emptyMap(), PriceCalculationMode.INSTANT_BUY_SELL);
	}

	/**
	 * Feature 2.5: Compares Plan A (consume eligible bank stock first without double-counting)
	 * vs Plan B (ignore existing bank stock & follow optimal cheapest market route),
	 * resolving live GE sell value of owned Crafting ingredients from {@code prices}.
	 */
	public static BankTrainingComparison compareBankTrainingPlans(
		SnapshotView snapshot,
		List<CraftingResult> allResults,
		int startLevel,
		long startXp,
		int targetLevel,
		long budgetGp,
		int temporaryBoost,
		boolean membersAllowed,
		boolean includeQuestLocked,
		boolean includeUnlockRequired,
		boolean includeNotedFromInventory,
		boolean includeGeTax,
		Map<Integer, ItemPrice> prices,
		Map<String, Integer> nameToIdIndex,
		PriceCalculationMode mode)
	{
		int sLvl = Math.max(1, Math.min(98, startLevel));
		int tLvl = Math.max(sLvl + 1, Math.min(99, targetLevel));
		long curXp = Math.max(startXp, XPTable.getXpForLevel(sLvl));
		long tgtXp = XPTable.getXpForLevel(tLvl);
		long totalXpNeeded = Math.max(0L, tgtXp - curXp);

		// Compute pure Plan B (market-optimal route ignoring bank)
		List<ComparedPlan> marketPlans = TrainingPlanComparisonCalculator.buildSideBySidePlans(
			allResults,
			OptimizerOptions.builder()
				.currentLevel(sLvl)
				.currentXp(curXp)
				.targetLevel(tLvl)
				.temporaryBoost(temporaryBoost)
				.membersAllowed(membersAllowed)
				.includeQuestLocked(includeQuestLocked)
				.includeUnlockRequired(includeUnlockRequired)
				.availableBudgetGp(budgetGp)
				.build()
		);
		TrainingPlan planB = null;
		for (ComparedPlan cp : marketPlans)
		{
			if (cp.getStrategy() == PlanStrategy.PLAN_B_CHEAPEST && cp.isFeasible())
			{
				planB = cp.getPlan();
				break;
			}
		}

		// Mutable pool of owned item counts so we NEVER double-count materials across bank segments
		Map<Integer, Double> mutableOwned = new LinkedHashMap<>();
		if (snapshot != null)
		{
			for (Map.Entry<Integer, Long> e : snapshot.toCombinedUsableMap(includeNotedFromInventory).entrySet())
			{
				mutableOwned.put(e.getKey(), (double) e.getValue());
			}
		}

		// Collect eligible recipes sorted by highest XP/hr then profit
		List<CraftingResult> candidates = new ArrayList<>();
		for (CraftingResult r : allResults)
		{
			if (r == null || r.getRecipe() == null || r.getRecipe().getVerificationStatus() == VerificationStatus.UNSUPPORTED)
			{
				continue;
			}
			CraftingRecipe rec = r.getRecipe();
			if (rec.getXpPerAction() <= 0.0)
			{
				continue;
			}
			if (!membersAllowed && rec.isMembers())
			{
				continue;
			}
			if (!includeQuestLocked && rec.hasQuestRequirement())
			{
				continue;
			}
			if (!includeUnlockRequired && rec.hasUnlockRequirement())
			{
				continue;
			}
			candidates.add(r);
		}
		candidates.sort(Comparator.comparingDouble(CraftingResult::getXpPerAction).reversed());

		List<BankPlanSegment> bankSegments = new ArrayList<>();
		long xpCursor = curXp;
		double bankCraftedNetGain = 0.0;
		double bankHrs = 0.0;

		boolean madeProgress = true;
		while (madeProgress && xpCursor < tgtXp)
		{
			madeProgress = false;
			int effLvl = XPTable.getLevelForXp(xpCursor);
			for (CraftingResult cand : candidates)
			{
				CraftingRecipe rec = cand.getRecipe();
				int usableLvl = rec.isBoostable() ? effLvl + temporaryBoost : effLvl;
				if (rec.getRequiredLevel() > usableLvl)
				{
					continue;
				}
				long maxCrafts = computeCraftsFromMutablePool(rec, mutableOwned);
				if (maxCrafts <= 0L)
				{
					continue;
				}
				long actionsToGoal = (long) Math.ceil((tgtXp - xpCursor) / rec.getXpPerAction());
				long doCrafts = Math.min(maxCrafts, Math.max(1L, actionsToGoal));
				consumeFromMutablePool(rec, mutableOwned, doCrafts);

				double xpGained = doCrafts * rec.getXpPerAction();
				double grossVal = cand.isPriceDataComplete() ? doCrafts * cand.getGrossRevenuePerCraft() : 0.0;
				double taxVal = cand.isPriceDataComplete() ? doCrafts * cand.getGeTaxPerCraft() : 0.0;
				double netGain = grossVal - taxVal; // materials came from bank (0 new GP spent)
				bankSegments.add(BankPlanSegment.builder()
					.recipe(rec)
					.craftsUsingBankStock(doCrafts)
					.xpGained(xpGained)
					.grossValueGp(grossVal)
					.taxGp(taxVal)
					.externalMissingCostGp(0.0)
					.netGainGp(netGain)
					.build());
				xpCursor += Math.round(xpGained);
				bankCraftedNetGain += netGain;
				bankHrs += cand.getActionsPerHour() > 0.0 ? doCrafts / cand.getActionsPerHour() : 0.0;
				madeProgress = true;
				break;
			}
		}

		long xpCovered = Math.min(totalXpNeeded, Math.max(0L, xpCursor - curXp));
		long xpRemaining = Math.max(0L, totalXpNeeded - xpCovered);

		TrainingPlan planARemaining = null;
		double planAAddSpend = 0.0;
		double planARemProfit = 0.0;
		double planARemHrs = 0.0;
		if (xpRemaining > 0L)
		{
			int remStartLvl = XPTable.getLevelForXp(curXp + xpCovered);
			List<ComparedPlan> remPlans = TrainingPlanComparisonCalculator.buildSideBySidePlans(
				allResults,
				OptimizerOptions.builder()
					.currentLevel(remStartLvl)
					.currentXp(curXp + xpCovered)
					.targetLevel(tLvl)
					.temporaryBoost(temporaryBoost)
					.membersAllowed(membersAllowed)
					.includeQuestLocked(includeQuestLocked)
					.includeUnlockRequired(includeUnlockRequired)
					.availableBudgetGp(budgetGp)
					.build()
			);
			for (ComparedPlan cp : remPlans)
			{
				if (cp.getStrategy() == PlanStrategy.PLAN_B_CHEAPEST && cp.isFeasible() && cp.getPlan() != null)
				{
					planARemaining = cp.getPlan();
					planAAddSpend = cp.getPlan().getTotalMaterialCost();
					planARemProfit = cp.getPlan().getTotalNetProfit();
					planARemHrs = cp.getPlan().getTotalEstimatedHours();
					break;
				}
			}
		}

		// Estimate net liquidation value of owned Crafting materials in bank/inventory if sold on GE instead
		long bankSellValue = 0L;
		if (snapshot != null && prices != null && !prices.isEmpty())
		{
			java.util.Set<Integer> craftingMaterialIds = new java.util.HashSet<>();
			for (CraftingResult cr : allResults)
			{
				if (cr == null || cr.getRecipe() == null)
				{
					continue;
				}
				for (RecipeInput in : cr.getRecipe().getInputs())
				{
					if (in.isConsumed())
					{
						craftingMaterialIds.add(in.getItemId());
					}
				}
			}
			for (OwnedItemCount c : snapshot.getItems().values())
			{
				if (!craftingMaterialIds.contains(c.getItemId()))
				{
					continue;
				}
				long q = includeNotedFromInventory ? c.getCombinedIncludingNotedQty() : c.getCombinedUsableQty();
				if (q <= 0L)
				{
					continue;
				}
				ItemPrice ip = ProfitCalculator.resolveItemPrice(c.getItemId(), c.getItemName(), prices, nameToIdIndex);
				Long unitSell = resolveUnitSellPrice(ip, mode != null ? mode : PriceCalculationMode.INSTANT_BUY_SELL, null, c.getItemId());
				if (unitSell != null && unitSell > 0L)
				{
					long netPerUnit = GETransactionCalculator.calculateNetRevenuePerItem(
						unitSell, c.getItemId(), false, includeGeTax);
					bankSellValue += Math.max(0L, q * netPerUnit);
				}
			}
		}

		double planATotalNet = bankCraftedNetGain + planARemProfit;
		double planBTotalNet = planB != null ? planB.getTotalNetProfit() : 0.0;
		String advice;
		if (xpCovered == 0L)
		{
			advice = "No eligible bank materials found; Plan A matches the market route (Plan B).";
		}
		else if (planB == null)
		{
			advice = String.format(java.util.Locale.US,
				"Bank materials provide %,d XP (%+, .0f GP est. output value after tax).",
				xpCovered, bankCraftedNetGain).replace(", ", ",");
		}
		else if (planATotalNet >= planBTotalNet)
		{
			advice = String.format(java.util.Locale.US,
				"Plan A covers %,d XP from bank and leaves %,.0f GP remaining purchase cost.",
				xpCovered, planAAddSpend);
		}
		else
		{
			advice = String.format(java.util.Locale.US,
				"Plan B may yield higher net value than crafting raw bank items; check Material Value comparison.",
				xpCovered);
		}

		return BankTrainingComparison.builder()
			.startLevel(sLvl)
			.targetLevel(tLvl)
			.xpRequiredTotal(totalXpNeeded)
			.xpCoveredByBank(xpCovered)
			.xpRemainingAfterBank(xpRemaining)
			.bankUsedSegments(Collections.unmodifiableList(bankSegments))
			.planARemainingRoute(planARemaining)
			.planATotalAdditionalSpendGp(planAAddSpend)
			.planANetProfitLossGp(planATotalNet)
			.planATotalHours(bankHrs + planARemHrs)
			.planBCheapestFullRoute(planB)
			.planBNetProfitLossGp(planBTotalNet)
			.planBTotalHours(planB != null ? planB.getTotalEstimatedHours() : 0.0)
			.ownedBankCraftingSellValueGp(bankSellValue)
			.adviceSummary(advice)
			.build();
	}

	public static ShoppingListSummary buildBankAwareShoppingList(
		CraftingRecipe recipe,
		long actions,
		SnapshotView snapshot,
		boolean includeNotedFromInventory,
		Map<Integer, ItemPrice> prices,
		Map<String, Integer> nameToIdIndex,
		PriceCalculationMode mode,
		Map<Integer, CustomPriceOverride> customPrices,
		ShoppingSortOrder sortOrder)
	{
		Map<Integer, Long> owned = snapshot != null
			? snapshot.toCombinedUsableMap(includeNotedFromInventory)
			: Collections.emptyMap();
		return ShoppingListCalculator.fromSingleRecipe(
			recipe, actions, owned, prices, nameToIdIndex, mode, customPrices, sortOrder);
	}

	private static long computeCraftsFromMutablePool(CraftingRecipe recipe, Map<Integer, Double> pool)
	{
		long cap = Long.MAX_VALUE;
		for (RecipeInput in : recipe.getInputs())
		{
			double have = pool.getOrDefault(in.getItemId(), 0.0);
			if (!in.isConsumed())
			{
				if (have < Math.max(1.0, in.getQuantity()))
				{
					return 0L;
				}
				continue;
			}
			long possible = (long) Math.floor((have + 1e-9) / Math.max(1e-9, in.getQuantity()));
			cap = Math.min(cap, possible);
		}
		return cap == Long.MAX_VALUE ? 0L : cap;
	}

	private static void consumeFromMutablePool(CraftingRecipe recipe, Map<Integer, Double> pool, long crafts)
	{
		for (RecipeInput in : recipe.getInputs())
		{
			if (!in.isConsumed())
			{
				continue;
			}
			double cur = pool.getOrDefault(in.getItemId(), 0.0);
			double next = Math.max(0.0, cur - (in.getQuantity() * crafts));
			pool.put(in.getItemId(), next);
		}
	}

	private static Long resolveUnitBuyPrice(
		int itemId,
		String itemName,
		Map<Integer, ItemPrice> prices,
		Map<String, Integer> nameToIdIndex,
		PriceCalculationMode mode,
		Map<Integer, CustomPriceOverride> customPrices)
	{
		if (itemId == ItemID.COINS_995)
		{
			return 1L;
		}
		if (customPrices != null)
		{
			CustomPriceOverride ov = customPrices.get(itemId);
			if (ov != null && ov.getBuyPrice() != null && ov.getBuyPrice() > 0L)
			{
				return ov.getBuyPrice();
			}
		}
		ItemPrice ip = ProfitCalculator.resolveItemPrice(itemId, itemName, prices, nameToIdIndex);
		if (ip == null)
		{
			return null;
		}
		return mode == PriceCalculationMode.CUSTOM ? ip.getAverageMarketPrice() : ip.resolveBuyPrice(mode, null);
	}

	private static Long resolveUnitSellPrice(
		ItemPrice ip,
		PriceCalculationMode mode,
		Map<Integer, CustomPriceOverride> customPrices,
		int itemId)
	{
		if (customPrices != null)
		{
			CustomPriceOverride ov = customPrices.get(itemId);
			if (ov != null && ov.getSellPrice() != null && ov.getSellPrice() > 0L)
			{
				return ov.getSellPrice();
			}
		}
		if (ip == null)
		{
			return null;
		}
		return mode == PriceCalculationMode.CUSTOM ? ip.getAverageMarketPrice() : ip.resolveSellPrice(mode, null);
	}
}

package com.craftwise.bank;

import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;

/**
 * Safe RuneLite container reader for Bank and Inventory materials (Feature 2.1 & 2.10).
 * Only accesses supported RuneLite ItemContainers and ItemManager APIs on the client thread.
 * Excludes bank placeholders, distinguishes noted vs unnoted inventory items, and never
 * assumes an unvisited bank is empty.
 */
public final class BankInventoryScanner
{
	public static final int NOTED_TEMPLATE_ID = 799;

	private BankInventoryScanner()
	{
	}

	/**
	 * Checks whether the OSRS bank main interface is legitimately open.
	 * Must be called on the client thread.
	 */
	public static boolean isBankInterfaceOpen(Client client)
	{
		if (client == null)
		{
			return false;
		}
		try
		{
			Widget bankWidget = client.getWidget(InterfaceID.BANKMAIN, 0);
			return bankWidget != null && !bankWidget.isHidden();
		}
		catch (Throwable ignored)
		{
			return false;
		}
	}

	/**
	 * Scans an accessible {@link ItemContainer} belonging to {@link InventoryID#BANK}.
	 * Must be called on the client thread when the bank container is accessible.
	 */
	public static void scanBank(
		ItemContainer bankContainer,
		ItemManager itemManager,
		OwnedMaterialSnapshot targetSnapshot,
		boolean bankOpen,
		long epochSec)
	{
		if (bankContainer == null || targetSnapshot == null)
		{
			return;
		}
		Map<Integer, Long> qtyMap = new LinkedHashMap<>();
		Map<Integer, String> nameMap = new LinkedHashMap<>();
		Item[] items = bankContainer.getItems();
		if (items != null)
		{
			for (Item item : items)
			{
				if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
				{
					continue;
				}
				int rawId = item.getId();
				int canonicalId = itemManager != null ? itemManager.canonicalize(rawId) : rawId;
				ItemComposition comp = itemManager != null ? itemManager.getItemComposition(rawId) : null;
				if (comp != null && comp.getPlaceholderTemplateId() != -1)
				{
					// Bank placeholder entry (quantity is 0 or placeholder template) -> never count as owned
					continue;
				}
				qtyMap.merge(canonicalId, (long) item.getQuantity(), Long::sum);
				ItemComposition canonComp = itemManager != null ? itemManager.getItemComposition(canonicalId) : comp;
				if (canonComp != null && canonComp.getName() != null)
				{
					nameMap.put(canonicalId, canonComp.getName());
				}
			}
		}
		targetSnapshot.updateBankContents(qtyMap, nameMap, bankOpen, epochSec);
	}

	/**
	 * Scans the player's {@link InventoryID#INVENTORY} container, separating unnoted vs noted items.
	 * Must be called on the client thread.
	 */
	public static void scanInventory(
		ItemContainer invContainer,
		ItemManager itemManager,
		OwnedMaterialSnapshot targetSnapshot,
		long epochSec)
	{
		if (invContainer == null || targetSnapshot == null)
		{
			return;
		}
		Map<Integer, Long> unnotedMap = new LinkedHashMap<>();
		Map<Integer, Long> notedMap = new LinkedHashMap<>();
		Map<Integer, String> nameMap = new LinkedHashMap<>();
		Item[] items = invContainer.getItems();
		if (items != null)
		{
			for (Item item : items)
			{
				if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
				{
					continue;
				}
				int rawId = item.getId();
				ItemComposition comp = itemManager != null ? itemManager.getItemComposition(rawId) : null;
				boolean isNoted = comp != null && comp.getNote() == NOTED_TEMPLATE_ID;
				int canonicalId = itemManager != null ? itemManager.canonicalize(rawId) : rawId;
				if (isNoted)
				{
					notedMap.merge(canonicalId, (long) item.getQuantity(), Long::sum);
				}
				else
				{
					unnotedMap.merge(canonicalId, (long) item.getQuantity(), Long::sum);
				}
				ItemComposition canonComp = itemManager != null ? itemManager.getItemComposition(canonicalId) : comp;
				if (canonComp != null && canonComp.getName() != null)
				{
					nameMap.put(canonicalId, canonComp.getName());
				}
			}
		}
		targetSnapshot.updateInventoryContents(unnotedMap, notedMap, nameMap, epochSec);
	}
}

package com.craftwise.bank;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.Reader;
import java.lang.reflect.Type;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Thread-safe snapshot of player-owned Crafting materials across Bank and Inventory,
 * keeping bank, unnoted inventory, and noted inventory quantities cleanly separated.
 */
@Slf4j
public class OwnedMaterialSnapshot
{
	@Getter
	@RequiredArgsConstructor
	public enum BankDataState
	{
		UNAVAILABLE("BANK DATA UNAVAILABLE"),
		LIVE_OPEN("Bank Open (Live Sync)"),
		SNAPSHOT_CLOSED("Bank Closed (Last Scan)");

		private final String label;

		@Override
		public String toString()
		{
			return label;
		}
	}

	@Data
	@Builder
	@NoArgsConstructor
	@AllArgsConstructor
	public static class OwnedItemCount
	{
		private int itemId;
		private String itemName;
		private long bankQty;
		private long inventoryUnnotedQty;
		private long inventoryNotedQty;
		private long manualAdjustmentQty;

		/**
		 * Total directly craftable/usable quantity across bank + unnoted inventory + manual count
		 * (excludes noted inventory items until unnoted at a bank).
		 */
		public long getCombinedUsableQty()
		{
			return Math.max(0L, bankQty + inventoryUnnotedQty + manualAdjustmentQty);
		}

		/**
		 * Total owned quantity including noted items currently held in inventory.
		 */
		public long getCombinedIncludingNotedQty()
		{
			return Math.max(0L, bankQty + inventoryUnnotedQty + inventoryNotedQty + manualAdjustmentQty);
		}
	}

	@Data
	@Builder
	public static class SnapshotView
	{
		private final BankDataState bankDataState;
		private final long lastBankScanEpochSec;
		private final long lastInventoryScanEpochSec;
		@Builder.Default
		private final Map<Integer, OwnedItemCount> items = Collections.emptyMap();

		public boolean isBankScanned()
		{
			return bankDataState != BankDataState.UNAVAILABLE;
		}

		public OwnedItemCount getCount(int itemId)
		{
			return items != null ? items.get(itemId) : null;
		}

		public Map<Integer, Long> toCombinedUsableMap(boolean includeNotedFromInventory)
		{
			if (items == null || items.isEmpty())
			{
				return Collections.emptyMap();
			}
			Map<Integer, Long> out = new LinkedHashMap<>(items.size());
			for (Map.Entry<Integer, OwnedItemCount> e : items.entrySet())
			{
				OwnedItemCount c = e.getValue();
				long q = includeNotedFromInventory ? c.getCombinedIncludingNotedQty() : c.getCombinedUsableQty();
				if (q > 0L)
				{
					out.put(e.getKey(), q);
				}
			}
			return Collections.unmodifiableMap(out);
		}
	}

	private static final Type OVERRIDE_TYPE = new TypeToken<Map<Integer, Long>>()
	{
	}.getType();

	private volatile Filepath manualFile;
	private final Gson gson;
	private volatile BankDataState bankDataState = BankDataState.UNAVAILABLE;
	private volatile long lastBankScanEpochSec = 0L;
	private volatile long lastInventoryScanEpochSec = 0L;

	private final Map<Integer, Long> bankQuantities = new LinkedHashMap<>();
	private final Map<Integer, Long> invUnnotedQuantities = new LinkedHashMap<>();
	private final Map<Integer, Long> invNotedQuantities = new LinkedHashMap<>();
	private final Map<Integer, String> itemNames = new LinkedHashMap<>();
	private final Map<Integer, Long> manualOwnedOverrides = new LinkedHashMap<>();

	public OwnedMaterialSnapshot(Gson gson)
	{
		this(null, gson);
	}

	public OwnedMaterialSnapshot(Filepath manualFile, Gson gson)
	{
		this.manualFile = manualFile;
		this.gson = gson.newBuilder().setPrettyPrinting().create();
		loadManualOverrides();
	}

	public synchronized void initializeStorage(Filepath manualFile)
	{
		this.manualFile = manualFile;
		loadManualOverrides();
	}

	public synchronized void loadManualOverrides()
	{
		manualOwnedOverrides.clear();
		Filepath file = this.manualFile;
		if (file == null || !file.exists())
		{
			return;
		}
		try (Reader reader = file.openReader())
		{
			Map<Integer, Long> loaded = gson.fromJson(reader, OVERRIDE_TYPE);
			if (loaded != null)
			{
				manualOwnedOverrides.putAll(loaded);
			}
		}
		catch (Exception ex)
		{
			log.warn("Failed to load CraftWise manual owned quantities from {}", file, ex);
		}
	}

	public synchronized void saveManualOverrides()
	{
		Filepath file = this.manualFile;
		if (file == null)
		{
			return;
		}
		try
		{
			Filepath parent = file.getParent();
			if (parent != null && !parent.exists())
			{
				parent.createDirectories();
			}
			file.write(gson.toJson(new LinkedHashMap<>(manualOwnedOverrides)));
		}
		catch (IOException ex)
		{
			log.warn("Failed to save CraftWise manual owned quantities to {}", file, ex);
		}
	}

	public synchronized void setManualOwnedQuantity(int itemId, String itemName, long quantity)
	{
		if (itemId <= 0)
		{
			return;
		}
		if (itemName != null && !itemName.trim().isEmpty())
		{
			itemNames.put(itemId, itemName.trim());
		}
		if (quantity <= 0L)
		{
			manualOwnedOverrides.remove(itemId);
		}
		else
		{
			manualOwnedOverrides.put(itemId, quantity);
		}
		saveManualOverrides();
	}

	public synchronized void clearManualOverrides()
	{
		manualOwnedOverrides.clear();
		saveManualOverrides();
	}

	public synchronized Map<Integer, Long> getManualOwnedOverrides()
	{
		return Collections.unmodifiableMap(new LinkedHashMap<>(manualOwnedOverrides));
	}

	public synchronized void updateBankContents(
		Map<Integer, Long> newBankQtyById,
		Map<Integer, String> namesById,
		boolean bankOpen,
		long epochSec)
	{
		bankQuantities.clear();
		if (newBankQtyById != null)
		{
			bankQuantities.putAll(newBankQtyById);
		}
		if (namesById != null)
		{
			itemNames.putAll(namesById);
		}
		this.lastBankScanEpochSec = epochSec;
		this.bankDataState = bankOpen ? BankDataState.LIVE_OPEN : BankDataState.SNAPSHOT_CLOSED;
	}

	public synchronized void updateInventoryContents(
		Map<Integer, Long> newUnnotedQtyById,
		Map<Integer, Long> newNotedQtyById,
		Map<Integer, String> namesById,
		long epochSec)
	{
		invUnnotedQuantities.clear();
		invNotedQuantities.clear();
		if (newUnnotedQtyById != null)
		{
			invUnnotedQuantities.putAll(newUnnotedQtyById);
		}
		if (newNotedQtyById != null)
		{
			invNotedQuantities.putAll(newNotedQtyById);
		}
		if (namesById != null)
		{
			itemNames.putAll(namesById);
		}
		this.lastInventoryScanEpochSec = epochSec;
	}

	public synchronized void onBankClosed()
	{
		if (this.bankDataState == BankDataState.LIVE_OPEN)
		{
			this.bankDataState = BankDataState.SNAPSHOT_CLOSED;
		}
	}

	public synchronized void resetSessionBankState()
	{
		bankQuantities.clear();
		invUnnotedQuantities.clear();
		invNotedQuantities.clear();
		this.bankDataState = BankDataState.UNAVAILABLE;
		this.lastBankScanEpochSec = 0L;
		this.lastInventoryScanEpochSec = 0L;
	}

	public synchronized SnapshotView getSnapshotView()
	{
		Map<Integer, OwnedItemCount> combined = new LinkedHashMap<>();
		for (Integer id : bankQuantities.keySet())
		{
			mergeEntry(combined, id);
		}
		for (Integer id : invUnnotedQuantities.keySet())
		{
			mergeEntry(combined, id);
		}
		for (Integer id : invNotedQuantities.keySet())
		{
			mergeEntry(combined, id);
		}
		for (Integer id : manualOwnedOverrides.keySet())
		{
			mergeEntry(combined, id);
		}

		return SnapshotView.builder()
			.bankDataState(bankDataState)
			.lastBankScanEpochSec(lastBankScanEpochSec)
			.lastInventoryScanEpochSec(lastInventoryScanEpochSec)
			.items(Collections.unmodifiableMap(combined))
			.build();
	}

	private void mergeEntry(Map<Integer, OwnedItemCount> combined, int id)
	{
		if (combined.containsKey(id))
		{
			return;
		}
		long b = bankQuantities.getOrDefault(id, 0L);
		long iu = invUnnotedQuantities.getOrDefault(id, 0L);
		long in = invNotedQuantities.getOrDefault(id, 0L);
		long man = manualOwnedOverrides.getOrDefault(id, 0L);
		if (b + iu + in + man <= 0L)
		{
			return;
		}
		combined.put(id, OwnedItemCount.builder()
			.itemId(id)
			.itemName(itemNames.getOrDefault(id, "Item #" + id))
			.bankQty(b)
			.inventoryUnnotedQty(iu)
			.inventoryNotedQty(in)
			.manualAdjustmentQty(man)
			.build());
	}
}

package com.craftwise.calculator;

import com.craftwise.data.CraftingRecipe;
import com.craftwise.data.CraftingRecipe.RecipeInput;
import com.craftwise.data.CraftingRecipe.RecipeOutput;
import com.craftwise.model.CraftingResult.BreakEvenStatus;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.Builder;
import lombok.Data;

/**
 * Exact Grand Exchange break-even calculator.
 * Accounts for integer per-item GE tax rounding, exemptions, and multi-output scaling,
 * validating every break-even price directly against {@link GETransactionCalculator}.
 */
public final class BreakEvenCalculator
{
	@Data
	@Builder
	public static class InputBreakEvenLimit
	{
		private final int itemId;
		private final String itemName;
		private final double quantityRequired;
		private final long currentUnitPrice;
		private final long maxAffordableUnitPrice;
	}

	@Data
	@Builder
	public static class MarginPresetTarget
	{
		private final String label;
		private final double marginPercent;
		private final long targetSellPrice;
		private final long taxAtTargetSellPrice;
		private final long netProfitAtTarget;
	}

	@Data
	@Builder
	public static class BreakEvenAnalysis
	{
		private final boolean available;
		private final long totalMaterialCost;
		private final long currentPrimarySellPrice;
		private final long breakEvenPrimarySellPrice;
		private final long maxTotalMaterialCost;
		private final long currentTaxPerPrimaryUnit;
		private final long breakEvenTaxPerPrimaryUnit;
		private final long currentNetProfit;
		private final double maxAcceptableSellDropPercent;
		private final double maxAcceptableCostRisePercent;
		private final BreakEvenStatus status;
		@Builder.Default
		private final List<InputBreakEvenLimit> inputLimits = Collections.emptyList();
		@Builder.Default
		private final List<MarginPresetTarget> marginTargets = Collections.emptyList();
	}

	private BreakEvenCalculator()
	{
	}

	/**
	 * Finds the minimum integer selling price per single primary output item such that
	 * {@code expectedPrimaryQty * netRevenuePerUnit(price) + secondaryNetRevenue >= materialCost}.
	 * Validated directly against {@link GETransactionCalculator#calculateNetRevenuePerItem}.
	 */
	public static Long calculateMinSellingPrice(
		double totalMaterialCost,
		double expectedPrimaryOutputQty,
		double secondaryNetRevenue,
		int primaryItemId,
		boolean primaryTaxExempt,
		boolean includeGeTax)
	{
		if (expectedPrimaryOutputQty <= 0.0 || totalMaterialCost < 0.0)
		{
			return null;
		}

		double neededPrimaryNet = Math.max(0.0, totalMaterialCost - secondaryNetRevenue);
		if (neededPrimaryNet <= 0.0)
		{
			return 1L;
		}

		double neededNetPerUnit = neededPrimaryNet / expectedPrimaryOutputQty;
		long targetNetPerUnit = (long) Math.ceil(neededNetPerUnit - 1e-9);
		if (targetNetPerUnit <= 0L)
		{
			return 1L;
		}

		if (!includeGeTax || GETransactionCalculator.isItemTaxExempt(primaryItemId, primaryTaxExempt))
		{
			return targetNetPerUnit;
		}

		// Below 50 GP there is 0 tax
		if (targetNetPerUnit < GETransactionCalculator.MIN_TAXABLE_PRICE_GP)
		{
			return targetNetPerUnit;
		}

		// Estimate upper bound for binary search (accounting for 2% tax and 5M cap)
		long low = targetNetPerUnit;
		long high = targetNetPerUnit > (245_000_000L)
			? targetNetPerUnit + GETransactionCalculator.MAX_TAX_PER_ITEM_GP + 10L
			: (long) Math.ceil(targetNetPerUnit / 0.98) + 100L;

		// Ensure high actually satisfies the condition
		while (netTotal(high, expectedPrimaryOutputQty, primaryItemId, primaryTaxExempt, includeGeTax) + 1e-9 < neededPrimaryNet)
		{
			low = high;
			high = high * 2L;
			if (high > 10_000_000_000L)
			{
				break;
			}
		}

		// Binary search for exact minimum integer selling price validated with actual tax function
		long answer = high;
		while (low <= high)
		{
			long mid = low + (high - low) / 2L;
			double net = netTotal(mid, expectedPrimaryOutputQty, primaryItemId, primaryTaxExempt, includeGeTax);
			if (net + 1e-9 >= neededPrimaryNet)
			{
				answer = mid;
				high = mid - 1L;
			}
			else
			{
				low = mid + 1L;
			}
		}
		return answer;
	}

	private static double netTotal(
		long sellPrice,
		double qty,
		int itemId,
		boolean taxExempt,
		boolean includeGeTax)
	{
		long netPerUnit = GETransactionCalculator.calculateNetRevenuePerItem(sellPrice, itemId, taxExempt, includeGeTax);
		return netPerUnit * qty;
	}

	/**
	 * Performs full break-even analysis for a recipe at specified material cost and output selling price.
	 */
	public static BreakEvenAnalysis analyze(
		CraftingRecipe recipe,
		double materialCostPerCraft,
		long customOrCurrentPrimarySellPrice,
		double secondaryNetRevenue,
		List<Long> inputUnitPrices,
		boolean includeGeTax)
	{
		if (recipe == null || recipe.getPrimaryOutput() == null || !recipe.isTradeableOutput())
		{
			return BreakEvenAnalysis.builder()
				.available(false)
				.status(BreakEvenStatus.UNAVAILABLE)
				.build();
		}

		RecipeOutput primary = recipe.getPrimaryOutput();
		double expectedQty = primary.getExpectedQuantity();
		Long breakEvenPrice = calculateMinSellingPrice(
			materialCostPerCraft,
			expectedQty,
			secondaryNetRevenue,
			primary.getItemId(),
			primary.isTaxExempt(),
			includeGeTax
		);
		if (breakEvenPrice == null)
		{
			return BreakEvenAnalysis.builder()
				.available(false)
				.status(BreakEvenStatus.UNAVAILABLE)
				.build();
		}

		long currentTaxPerUnit = GETransactionCalculator.calculateTaxPerItem(
			customOrCurrentPrimarySellPrice, primary.getItemId(), primary.isTaxExempt(), includeGeTax);
		long breakEvenTaxPerUnit = GETransactionCalculator.calculateTaxPerItem(
			breakEvenPrice, primary.getItemId(), primary.isTaxExempt(), includeGeTax);

		double netAtCurrent = (customOrCurrentPrimarySellPrice - currentTaxPerUnit) * expectedQty + secondaryNetRevenue;
		long roundedNetProfit = Math.round(netAtCurrent - materialCostPerCraft);
		long roundedMatCost = Math.round(materialCostPerCraft);
		long maxMatCost = Math.max(0L, (long) Math.floor(netAtCurrent));

		double maxSellDropPct = customOrCurrentPrimarySellPrice > 0L
			? ((customOrCurrentPrimarySellPrice - breakEvenPrice) * 100.0) / customOrCurrentPrimarySellPrice
			: 0.0;
		double maxCostRisePct = materialCostPerCraft > 0.0
			? ((netAtCurrent - materialCostPerCraft) * 100.0) / materialCostPerCraft
			: 0.0;

		BreakEvenStatus status = classifyStatus(netAtCurrent - materialCostPerCraft, materialCostPerCraft);

		List<InputBreakEvenLimit> limits = new ArrayList<>();
		List<RecipeInput> inputs = recipe.getInputs();
		if (inputs != null && inputUnitPrices != null && inputs.size() == inputUnitPrices.size())
		{
			for (int i = 0; i < inputs.size(); i++)
			{
				RecipeInput in = inputs.get(i);
				if (!in.isConsumed() || in.getItemId() == net.runelite.api.ItemID.COINS_995)
				{
					continue;
				}
				long unitPrice = inputUnitPrices.get(i);
				double otherCost = materialCostPerCraft - (in.getQuantity() * unitPrice);
				double remainingForThisInput = Math.max(0.0, netAtCurrent - otherCost);
				long maxUnit = in.getQuantity() > 0.0 ? (long) Math.floor(remainingForThisInput / in.getQuantity()) : 0L;
				limits.add(InputBreakEvenLimit.builder()
					.itemId(in.getItemId())
					.itemName(in.getItemName())
					.quantityRequired(in.getQuantity())
					.currentUnitPrice(unitPrice)
					.maxAffordableUnitPrice(maxUnit)
					.build());
			}
		}

		double[] marginPresets = new double[]{0.0, 1.0, 5.0, 10.0, 20.0};
		List<MarginPresetTarget> marginTargets = new ArrayList<>(marginPresets.length);
		for (double pct : marginPresets)
		{
			double targetCostPlusProfit = materialCostPerCraft * (1.0 + (pct / 100.0));
			Long targetSell = calculateMinSellingPrice(
				targetCostPlusProfit, expectedQty, secondaryNetRevenue,
				primary.getItemId(), primary.isTaxExempt(), includeGeTax);
			if (targetSell != null)
			{
				long taxAtTarget = GETransactionCalculator.calculateTaxPerItem(
					targetSell, primary.getItemId(), primary.isTaxExempt(), includeGeTax);
				double netAtTarget = (targetSell - taxAtTarget) * expectedQty + secondaryNetRevenue;
				marginTargets.add(MarginPresetTarget.builder()
					.label(pct == 0.0 ? "0 GP (Break-Even)" : String.format("+%.0f%% Margin", pct))
					.marginPercent(pct)
					.targetSellPrice(targetSell)
					.taxAtTargetSellPrice(taxAtTarget)
					.netProfitAtTarget(Math.round(netAtTarget - materialCostPerCraft))
					.build());
			}
		}

		return BreakEvenAnalysis.builder()
			.available(true)
			.totalMaterialCost(roundedMatCost)
			.currentPrimarySellPrice(customOrCurrentPrimarySellPrice)
			.breakEvenPrimarySellPrice(breakEvenPrice)
			.maxTotalMaterialCost(maxMatCost)
			.currentTaxPerPrimaryUnit(currentTaxPerUnit)
			.breakEvenTaxPerPrimaryUnit(breakEvenTaxPerUnit)
			.currentNetProfit(roundedNetProfit)
			.maxAcceptableSellDropPercent(maxSellDropPct)
			.maxAcceptableCostRisePercent(maxCostRisePct)
			.status(status)
			.inputLimits(Collections.unmodifiableList(limits))
			.marginTargets(Collections.unmodifiableList(marginTargets))
			.build();
	}

	public static BreakEvenStatus classifyStatus(double profitPerCraft, double materialCost)
	{
		double nearThreshold = Math.max(10.0, Math.abs(materialCost) * 0.02);
		if (Math.abs(profitPerCraft) <= nearThreshold)
		{
			return BreakEvenStatus.NEAR_BREAK_EVEN;
		}
		return profitPerCraft > 0.0 ? BreakEvenStatus.PROFITABLE : BreakEvenStatus.LOSS;
	}
}

package com.craftwise.calculator;

import com.craftwise.model.CraftingResult;
import com.craftwise.model.TrainingPlan.OptimizationObjective;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import lombok.Builder;
import lombok.Data;

/**
 * Evaluates and ranks Crafting methods strictly within a player's available GP budget.
 * Accounts for total material requirements (not just per-item margin) and never recommends
 * a method whose upfront material requirement exceeds the budget.
 */
public final class BudgetCalculator
{
	@Data
	@Builder
	public static class BudgetMethodEvaluation
	{
		private final CraftingResult result;
		private final long maxAffordableActions;
		private final long actionsNeededForTarget;
		private final boolean reachesTargetWithinBudget;
		private final double totalMaterialSpend;
		private final double totalXpAchievable;
		private final double totalNetProfit;
		private final double estimatedHours;
	}

	private BudgetCalculator()
	{
	}

	/**
	 * Evaluates all unlocked, complete-price methods against {@code budgetGp} and {@code xpToTarget}.
	 * Only returns methods where at least 1 craft can be funded within {@code budgetGp} (or for
	 * target-bound objectives, optionally filters strictly to methods that can reach the target or
	 * caps achievable crafts by budget).
	 */
	public static List<BudgetMethodEvaluation> evaluateWithinBudget(
		List<CraftingResult> allResults,
		int playerLevel,
		long xpToTarget,
		long budgetGp,
		OptimizationObjective objective,
		long maxAcceptableLossGp,
		double minDesiredXpPerHour)
	{
		if (allResults == null || allResults.isEmpty() || budgetGp <= 0L)
		{
			return List.of();
		}

		List<BudgetMethodEvaluation> evaluations = new ArrayList<>();
		for (CraftingResult r : allResults)
		{
			if (r == null || !r.isPriceDataComplete())
			{
				continue;
			}
			if (r.getRecipe().getRequiredLevel() > playerLevel)
			{
				continue;
			}
			if (r.getXpPerAction() <= 0.0 || r.getXpPerHour() < minDesiredXpPerHour)
			{
				continue;
			}
			double matCost = r.getMaterialCostPerCraft();
			if (matCost <= 0.0)
			{
				continue;
			}

			long maxAffordable = (long) Math.floor(budgetGp / matCost);
			if (maxAffordable <= 0L)
			{
				continue;
			}

			long actionsForTarget = xpToTarget > 0L
				? (long) Math.ceil(xpToTarget / r.getXpPerAction())
				: maxAffordable;
			boolean reachesTarget = xpToTarget <= 0L || maxAffordable >= actionsForTarget;
			long plannedActions = Math.min(maxAffordable, actionsForTarget);

			double totalSpend = plannedActions * matCost;
			double totalProfit = plannedActions * r.getProfitPerCraft();
			if (maxAcceptableLossGp >= 0L && (-totalProfit) > maxAcceptableLossGp)
			{
				continue;
			}

			double totalXp = plannedActions * r.getXpPerAction();
			double hours = r.getActionsPerHour() > 0.0 ? plannedActions / r.getActionsPerHour() : 0.0;

			evaluations.add(BudgetMethodEvaluation.builder()
				.result(r)
				.maxAffordableActions(maxAffordable)
				.actionsNeededForTarget(actionsForTarget)
				.reachesTargetWithinBudget(reachesTarget)
				.totalMaterialSpend(totalSpend)
				.totalXpAchievable(totalXp)
				.totalNetProfit(totalProfit)
				.estimatedHours(hours)
				.build());
		}

		Comparator<BudgetMethodEvaluation> comparator = comparatorForObjective(objective);
		evaluations.sort(comparator);
		return evaluations;
	}

	private static Comparator<BudgetMethodEvaluation> comparatorForObjective(OptimizationObjective objective)
	{
		OptimizationObjective safe = objective != null ? objective : OptimizationObjective.MAX_XP_WITHIN_BUDGET;
		switch (safe)
		{
			case MIN_COST_TO_TARGET:
				// Prefer reaching target within budget, then lowest net cost (highest net profit)
				return Comparator.comparing(BudgetMethodEvaluation::isReachesTargetWithinBudget).reversed()
					.thenComparing(Comparator.comparingDouble(BudgetMethodEvaluation::getTotalNetProfit).reversed())
					.thenComparing(Comparator.comparingDouble(BudgetMethodEvaluation::getTotalXpAchievable).reversed());
			case MAX_PROFIT_WHILE_TRAINING:
				return Comparator.comparingDouble(BudgetMethodEvaluation::getTotalNetProfit).reversed()
					.thenComparing(Comparator.comparingDouble(BudgetMethodEvaluation::getTotalXpAchievable).reversed());
			case FASTEST_WITHIN_BUDGET:
				return Comparator.comparing(BudgetMethodEvaluation::isReachesTargetWithinBudget).reversed()
					.thenComparing(Comparator.comparingDouble((BudgetMethodEvaluation e) -> e.getResult().getXpPerHour()).reversed());
			case LOWEST_LOSS:
				return Comparator.comparingDouble((BudgetMethodEvaluation e) -> -e.getResult().getGpPerXp())
					.thenComparing(Comparator.comparingDouble(BudgetMethodEvaluation::getTotalNetProfit).reversed());
			case MAX_XP_WITHIN_BUDGET:
			default:
				return Comparator.comparingDouble(BudgetMethodEvaluation::getTotalXpAchievable).reversed()
					.thenComparing(Comparator.comparingDouble((BudgetMethodEvaluation e) -> e.getResult().getXpPerHour()).reversed());
		}
	}
}

package com.craftwise.calculator;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.ItemID;

/**
 * Implements official Old School RuneScape Grand Exchange transaction tax rules:
 * - Seller pays 2% tax, rounded down to the nearest whole GP per individual item sold.
 * - Items sold below 50 GP incur 0 GP tax (floor(49 * 0.02) = 0).
 * - Tax is capped at 5,000,000 GP per single item (sales >= 250,000,000 GP).
 * - Buying on the Grand Exchange never incurs GE tax.
 * - Exempt items (Old School Bonds, starter tools, untradeables, Coins) incur 0 GP tax.
 */
public final class GETransactionCalculator
{
	public static final double TAX_RATE = 0.02;
	public static final long TAX_DIVISOR = 50L;
	public static final long MIN_TAXABLE_PRICE_GP = 50L;
	public static final long MAX_TAX_PER_ITEM_GP = 5_000_000L;

	private static final Set<Integer> EXEMPT_ITEM_IDS;

	static
	{
		// Official OSRS Wiki Grand Exchange#Exempt_from_tax list (post May 2025 2% update)
		Set<Integer> exempt = new HashSet<>();
		exempt.add(ItemID.COINS_995);
		exempt.add(ItemID.PLATINUM_TOKEN);
		exempt.add(ItemID.OLD_SCHOOL_BOND);
		// Tools
		exempt.add(ItemID.CHISEL);
		exempt.add(ItemID.GARDENING_TROWEL);
		exempt.add(ItemID.GLASSBLOWING_PIPE);
		exempt.add(ItemID.HAMMER);
		exempt.add(ItemID.NEEDLE);
		exempt.add(ItemID.PESTLE_AND_MORTAR);
		exempt.add(ItemID.RAKE);
		exempt.add(ItemID.SAW);
		exempt.add(ItemID.SECATEURS);
		exempt.add(ItemID.SEED_DIBBER);
		exempt.add(ItemID.SHEARS);
		exempt.add(ItemID.SPADE);
		exempt.add(ItemID.WATERING_CAN);
		// Teleport items (including craftable/enchantable jewellery)
		exempt.add(ItemID.GAMES_NECKLACE8);
		exempt.add(ItemID.RING_OF_DUELING8);
		exempt.add(ItemID.TELEPORT_TO_HOUSE);
		exempt.add(ItemID.VARROCK_TELEPORT);
		exempt.add(ItemID.LUMBRIDGE_TELEPORT);
		exempt.add(ItemID.FALADOR_TELEPORT);
		exempt.add(ItemID.CAMELOT_TELEPORT);
		exempt.add(ItemID.ARDOUGNE_TELEPORT);
		exempt.add(19651); // Kourend castle teleport (tablet)
		exempt.add(28824); // Civitas illa fortis teleport
		// Energy potions
		exempt.add(ItemID.ENERGY_POTION4);
		exempt.add(ItemID.ENERGY_POTION3);
		exempt.add(ItemID.ENERGY_POTION2);
		exempt.add(ItemID.ENERGY_POTION1);
		// Low level combat consumables
		exempt.add(ItemID.BRONZE_ARROW);
		exempt.add(ItemID.IRON_ARROW);
		exempt.add(ItemID.STEEL_ARROW);
		exempt.add(ItemID.BRONZE_DART);
		exempt.add(ItemID.IRON_DART);
		exempt.add(ItemID.STEEL_DART);
		exempt.add(ItemID.MIND_RUNE);
		// Low level food
		exempt.add(ItemID.BASS);
		exempt.add(ItemID.BREAD);
		exempt.add(ItemID.CAKE);
		exempt.add(ItemID.COOKED_CHICKEN);
		exempt.add(ItemID.COOKED_MEAT);
		exempt.add(ItemID.HERRING);
		exempt.add(ItemID.LOBSTER);
		exempt.add(ItemID.MACKEREL);
		exempt.add(ItemID.MEAT_PIE);
		exempt.add(ItemID.PIKE);
		exempt.add(ItemID.SALMON);
		exempt.add(ItemID.SHRIMPS);
		exempt.add(ItemID.TUNA);
		EXEMPT_ITEM_IDS = Collections.unmodifiableSet(exempt);
	}

	private GETransactionCalculator()
	{
	}

	public static boolean isItemTaxExempt(int itemId, boolean recipeTaxExempt)
	{
		return recipeTaxExempt || itemId <= 0 || EXEMPT_ITEM_IDS.contains(itemId);
	}

	/**
	 * Calculates the GE seller tax in whole GP for a single item sold at {@code unitSellPrice}.
	 */
	public static long calculateTaxPerItem(long unitSellPrice, int itemId, boolean recipeTaxExempt, boolean includeGeTax)
	{
		if (!includeGeTax || unitSellPrice < MIN_TAXABLE_PRICE_GP || isItemTaxExempt(itemId, recipeTaxExempt))
		{
			return 0L;
		}
		long tax = unitSellPrice / TAX_DIVISOR;
		return Math.min(MAX_TAX_PER_ITEM_GP, Math.max(0L, tax));
	}

	/**
	 * Calculates the net GP received by the seller for a single item after GE tax.
	 */
	public static long calculateNetRevenuePerItem(long unitSellPrice, int itemId, boolean recipeTaxExempt, boolean includeGeTax)
	{
		long safePrice = Math.max(0L, unitSellPrice);
		return safePrice - calculateTaxPerItem(safePrice, itemId, recipeTaxExempt, includeGeTax);
	}

	/**
	 * Calculates total GE tax for selling {@code quantity} items at {@code unitSellPrice} each.
	 * Rounding is applied per individual item before multiplying by quantity.
	 */
	public static long calculateTotalTax(long unitSellPrice, long quantity, int itemId, boolean recipeTaxExempt, boolean includeGeTax)
	{
		if (quantity <= 0L)
		{
			return 0L;
		}
		return calculateTaxPerItem(unitSellPrice, itemId, recipeTaxExempt, includeGeTax) * quantity;
	}

	/**
	 * Calculates expected GE tax for fractional/probability-weighted output quantities.
	 */
	public static double calculateExpectedTax(long unitSellPrice, double expectedQuantity, int itemId, boolean recipeTaxExempt, boolean includeGeTax)
	{
		if (expectedQuantity <= 0.0)
		{
			return 0.0;
		}
		return calculateTaxPerItem(unitSellPrice, itemId, recipeTaxExempt, includeGeTax) * expectedQuantity;
	}
}

package com.craftwise.calculator;

import com.craftwise.data.CraftingRecipe;
import com.craftwise.data.CraftingRecipe.RecipeInput;
import com.craftwise.data.CraftingRecipe.RecipeOutput;
import com.craftwise.model.CraftingResult;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.Builder;
import lombok.Data;
import net.runelite.api.ItemID;

/**
 * Calculates inventory capacity, trips, input materials, outputs, GE tax, net profit,
 * and XP gained for individual crafting sessions (1/5/10 inventories or arbitrary item counts).
 */
public final class InventoryCalculator
{
	public static final int OSRS_INVENTORY_SLOTS = 28;

	@Data
	@Builder
	public static class SessionMaterial
	{
		private final int itemId;
		private final String itemName;
		private final double exactQuantity;
		private final long purchaseQuantity;
		private final boolean stackable;
	}

	@Data
	@Builder
	public static class SessionOutput
	{
		private final int itemId;
		private final String itemName;
		private final double expectedQuantity;
	}

	@Data
	@Builder
	public static class InventorySessionResult
	{
		private final boolean available;
		private final CraftingRecipe recipe;
		private final int craftsPerInventory;
		private final long inventoriesNeeded;
		private final long actionsRequested;
		private final double totalMaterialCost;
		private final double totalGrossRevenue;
		private final double totalGeTax;
		private final double totalNetProfit;
		private final double totalXpGained;
		private final double estimatedMinutes;
		@Builder.Default
		private final List<SessionMaterial> materials = Collections.emptyList();
		@Builder.Default
		private final List<SessionOutput> outputs = Collections.emptyList();
	}

	private InventoryCalculator()
	{
	}

	/**
	 * Computes how many craft actions fit in a single 28-slot inventory for {@code recipe},
	 * accounting for non-consumed tools and stackable vs non-stackable ingredients.
	 */
	public static int calculateCraftsPerInventory(CraftingRecipe recipe)
	{
		if (recipe == null)
		{
			return 0;
		}
		int freeSlots = Math.max(1, OSRS_INVENTORY_SLOTS - Math.max(0, recipe.getToolSlotsRequired()));
		int stackableInputSlots = 0;
		int nonStackableSlotsPerAction = 0;

		for (RecipeInput input : recipe.getInputs())
		{
			if (input.getItemId() == ItemID.COINS_995 || input.getItemId() == ItemID.THREAD)
			{
				// Coins or Thread are already counted in toolSlotsRequired (or shared pouch/slot)
				continue;
			}
			if (input.isStackable())
			{
				stackableInputSlots++;
			}
			else
			{
				nonStackableSlotsPerAction += Math.max(1, (int) Math.ceil(input.getQuantity()));
			}
		}

		// If all inputs are stackable (e.g. Xerician fabric), output items take 1 non-stackable slot each
		if (nonStackableSlotsPerAction == 0)
		{
			int usable = Math.max(1, freeSlots - stackableInputSlots);
			return usable;
		}

		int usableSlots = Math.max(1, freeSlots - stackableInputSlots);
		return Math.max(1, usableSlots / nonStackableSlotsPerAction);
	}

	public static InventorySessionResult calculateForInventories(CraftingResult result, int inventories)
	{
		if (result == null || result.getRecipe() == null || inventories <= 0)
		{
			return InventorySessionResult.builder().available(false).build();
		}
		int perInv = calculateCraftsPerInventory(result.getRecipe());
		return calculateForActions(result, (long) perInv * inventories);
	}

	public static InventorySessionResult calculateForActions(CraftingResult result, long actions)
	{
		if (result == null || result.getRecipe() == null || actions <= 0L)
		{
			return InventorySessionResult.builder().available(false).build();
		}

		CraftingRecipe recipe = result.getRecipe();
		int perInv = calculateCraftsPerInventory(recipe);
		long inventories = (long) Math.ceil((double) actions / Math.max(1, perInv));

		List<SessionMaterial> mats = new ArrayList<>();
		for (RecipeInput in : recipe.getInputs())
		{
			double exact = actions * in.getQuantity();
			long purchase = (long) Math.ceil(exact - 1e-9);
			mats.add(SessionMaterial.builder()
				.itemId(in.getItemId())
				.itemName(in.getItemName())
				.exactQuantity(exact)
				.purchaseQuantity(purchase)
				.stackable(in.isStackable())
				.build());
		}

		List<SessionOutput> outs = new ArrayList<>();
		for (RecipeOutput out : recipe.getOutputs())
		{
			outs.add(SessionOutput.builder()
				.itemId(out.getItemId())
				.itemName(out.getItemName())
				.expectedQuantity(actions * out.getExpectedQuantity())
				.build());
		}

		double totalXp = actions * recipe.getXpPerAction();
		double minutes = result.getActionsPerHour() > 0.0
			? (actions / result.getActionsPerHour()) * 60.0
			: 0.0;

		if (!result.isPriceDataComplete())
		{
			return InventorySessionResult.builder()
				.available(false)
				.recipe(recipe)
				.craftsPerInventory(perInv)
				.inventoriesNeeded(inventories)
				.actionsRequested(actions)
				.totalXpGained(totalXp)
				.estimatedMinutes(minutes)
				.materials(Collections.unmodifiableList(mats))
				.outputs(Collections.unmodifiableList(outs))
				.build();
		}

		return InventorySessionResult.builder()
			.available(true)
			.recipe(recipe)
			.craftsPerInventory(perInv)
			.inventoriesNeeded(inventories)
			.actionsRequested(actions)
			.totalMaterialCost(actions * result.getMaterialCostPerCraft())
			.totalGrossRevenue(actions * result.getGrossRevenuePerCraft())
			.totalGeTax(actions * result.getGeTaxPerCraft())
			.totalNetProfit(actions * result.getProfitPerCraft())
			.totalXpGained(totalXp)
			.estimatedMinutes(minutes)
			.materials(Collections.unmodifiableList(mats))
			.outputs(Collections.unmodifiableList(outs))
			.build();
	}
}

package com.craftwise.calculator;

import com.craftwise.model.ItemPrice;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.Builder;
import lombok.Data;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Evaluates real Grand Exchange liquidity, spread, and recency risk
 * strictly from observed OSRS Wiki price endpoints (/latest, /5m, /1h).
 * Never fabricates volume metrics when the API reports none.
 */
public final class MarketConfidenceEvaluator
{
	@Getter
	@RequiredArgsConstructor
	public enum PriceConfidence
	{
		HIGH("High", "Active 1h volume, tight spread, and recent trades."),
		MEDIUM("Medium", "Moderate trade volume or spread; watch GE offer fill speed."),
		LOW("Low", "Thin volume, wide bid-ask spread, or aged market data."),
		UNAVAILABLE("Unavailable", "Missing market price data.");

		private final String label;
		private final String description;

		@Override
		public String toString()
		{
			return label;
		}
	}

	@Data
	@Builder
	public static class MarketEvaluation
	{
		private final PriceConfidence confidence;
		private final long min1hVolume;
		private final long primaryOutput1hVolume;
		private final double worstSpreadPercent;
		private final long oldestPriceAgeSeconds;
		private final boolean lowLiquidityWarning;
		private final boolean wideSpreadWarning;
		private final boolean stalePriceWarning;
		@Builder.Default
		private final List<String> warnings = Collections.emptyList();
	}

	public static final String GE_EXECUTION_DISCLAIMER =
		"Note: Execution at displayed GE prices is not guaranteed; verify live offer margins and trade volume before bulk trades.";

	private MarketConfidenceEvaluator()
	{
	}

	public static MarketEvaluation evaluate(
		boolean priceDataComplete,
		List<ItemPrice> tradedPrices,
		ItemPrice primaryOutputPrice,
		long nowEpochSeconds)
	{
		if (!priceDataComplete)
		{
			return MarketEvaluation.builder()
				.confidence(PriceConfidence.UNAVAILABLE)
				.min1hVolume(0L)
				.primaryOutput1hVolume(primaryOutputPrice != null ? primaryOutputPrice.getTotal1hVolume() : 0L)
				.worstSpreadPercent(0.0)
				.oldestPriceAgeSeconds(0L)
				.lowLiquidityWarning(true)
				.warnings(Collections.singletonList("Market price missing for one or more required items."))
				.build();
		}

		long primaryVol = primaryOutputPrice != null ? primaryOutputPrice.getTotal1hVolume() : 0L;
		if (tradedPrices == null || tradedPrices.isEmpty())
		{
			return MarketEvaluation.builder()
				.confidence(PriceConfidence.MEDIUM)
				.min1hVolume(primaryVol)
				.primaryOutput1hVolume(primaryVol)
				.worstSpreadPercent(0.0)
				.oldestPriceAgeSeconds(0L)
				.warnings(Collections.emptyList())
				.build();
		}

		PriceConfidence worst = PriceConfidence.HIGH;
		long minVol = Long.MAX_VALUE;
		double maxSpreadPct = 0.0;
		long maxAgeSec = 0L;
		boolean lowLiquidity = false;
		boolean wideSpread = false;
		boolean stale = false;
		List<String> warnings = new ArrayList<>();

		for (ItemPrice price : tradedPrices)
		{
			if (price == null)
			{
				continue;
			}
			long vol1h = price.getTotal1hVolume();
			if (vol1h < minVol)
			{
				minVol = vol1h;
			}

			String itemLabel = price.getName() != null && !price.getName().trim().isEmpty()
				? price.getName()
				: "Item #" + price.getItemId();

			if (vol1h == 0L)
			{
				lowLiquidity = true;
				worst = lowerOf(worst, PriceConfidence.LOW);
				warnings.add("Low/no 1h GE volume reported for " + itemLabel + ".");
			}
			else if (vol1h < 10L)
			{
				lowLiquidity = true;
				worst = lowerOf(worst, PriceConfidence.LOW);
				warnings.add("Very low liquidity (" + vol1h + "/hr) for " + itemLabel + ".");
			}
			else if (vol1h < 100L)
			{
				worst = lowerOf(worst, PriceConfidence.MEDIUM);
			}

			Long high = price.getHighPrice();
			Long low = price.getLowPrice();
			if (high != null && low != null && high > 0L && low > 0L && high >= low)
			{
				double mid = (high + low) / 2.0;
				double spreadPct = mid > 0.0 ? ((high - low) * 100.0) / mid : 0.0;
				if (spreadPct > maxSpreadPct)
				{
					maxSpreadPct = spreadPct;
				}
				if (spreadPct > 15.0)
				{
					wideSpread = true;
					worst = lowerOf(worst, PriceConfidence.LOW);
					warnings.add(String.format("Wide bid-ask spread (%.1f%%) on %s.", spreadPct, itemLabel));
				}
				else if (spreadPct > 6.0)
				{
					wideSpread = true;
					worst = lowerOf(worst, PriceConfidence.MEDIUM);
					warnings.add(String.format("Moderate spread (%.1f%%) on %s.", spreadPct, itemLabel));
				}
			}

			long latestTradeEpoch = Math.max(price.getHighTime(), price.getLowTime());
			if (nowEpochSeconds > 0L && latestTradeEpoch > 0L && nowEpochSeconds >= latestTradeEpoch)
			{
				long ageSec = nowEpochSeconds - latestTradeEpoch;
				if (ageSec > maxAgeSec)
				{
					maxAgeSec = ageSec;
				}
				if (ageSec > 21_600L) // > 6 hours old
				{
					stale = true;
					worst = lowerOf(worst, PriceConfidence.LOW);
					warnings.add("Latest trade for " + itemLabel + " is over 6 hours old.");
				}
				else if (ageSec > 3_600L) // > 1 hour old
				{
					stale = true;
					worst = lowerOf(worst, PriceConfidence.MEDIUM);
				}
			}
		}

		if (minVol == Long.MAX_VALUE)
		{
			minVol = 0L;
		}

		return MarketEvaluation.builder()
			.confidence(worst)
			.min1hVolume(minVol)
			.primaryOutput1hVolume(primaryVol)
			.worstSpreadPercent(maxSpreadPct)
			.oldestPriceAgeSeconds(maxAgeSec)
			.lowLiquidityWarning(lowLiquidity)
			.wideSpreadWarning(wideSpread)
			.stalePriceWarning(stale)
			.warnings(Collections.unmodifiableList(warnings))
			.build();
	}

	private static PriceConfidence lowerOf(PriceConfidence a, PriceConfidence b)
	{
		return a.ordinal() >= b.ordinal() ? a : b;
	}
}

package com.craftwise.calculator;

import com.craftwise.CraftWiseConfig.PriceCalculationMode;
import com.craftwise.calculator.ProfitCalculator.CustomPriceOverride;
import com.craftwise.data.CraftingDataRepository;
import com.craftwise.data.CraftingRecipe;
import com.craftwise.data.CraftingRecipe.RecipeInput;
import com.craftwise.data.CraftingRecipe.RecipeOutput;
import com.craftwise.model.CraftingResult;
import com.craftwise.model.ItemPrice;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Builder;
import lombok.Data;
import net.runelite.api.ItemID;

/**
 * Phase 4: Multi-Step Crafting Calculator.
 * Compares buying finished/intermediate materials directly on the GE vs
 * crafting upstream Crafting stages from raw materials, with zero double-counting
 * of material costs, intermediate outputs, GE tax, or XP.
 */
public final class MultiStepCalculator
{
	@Data
	@Builder
	public static class StageSummary
	{
		private final int stageIndex;
		private final CraftingRecipe recipe;
		private final double multiplierForOneFinal;
		private final double stageXpTotal;
		private final double standaloneProfitPerAction;
	}

	@Data
	@Builder
	public static class MultiStepAnalysis
	{
		private final boolean hasMultiStepChain;
		private final CraftingRecipe finalRecipe;
		@Builder.Default
		private final List<StageSummary> stages = Collections.emptyList();

		// Strategy A: Buy immediate inputs for the final recipe directly
		private final boolean buyIntermediateAvailable;
		private final double buyIntermediateCost;
		private final double buyIntermediateNetRevenue;
		private final double buyIntermediateProfit;
		private final double buyIntermediateXp;
		private final double buyIntermediateGpPerXp;

		// Strategy B: Craft upstream Crafting stage(s) + final recipe from raw inputs
		private final boolean makeAllStepsAvailable;
		private final double makeAllRawCost;
		private final double makeAllSecondaryNetRevenue;
		private final double makeAllFinalNetRevenue;
		private final double makeAllProfit;
		private final double makeAllXp;
		private final double makeAllGpPerXp;

		private final String recommendation; // "MAKE INTERMEDIATE", "BUY INTERMEDIATE", "SINGLE STEP", "UNAVAILABLE"
		private final double profitAdvantageMakeVsBuy;
		private final double xpGainMakeVsBuy;
		private final String summaryText;
		@Builder.Default
		private final Map<Integer, Double> makeAllRawMaterialQuantities = Collections.emptyMap();
		@Builder.Default
		private final Map<Integer, Double> buyDirectMaterialQuantities = Collections.emptyMap();
	}

	private MultiStepCalculator()
	{
	}

	public static MultiStepAnalysis analyze(
		CraftingRecipe finalRecipe,
		List<CraftingRecipe> allRecipes,
		Map<Integer, ItemPrice> prices,
		Map<String, Integer> nameToIdIndex,
		PriceCalculationMode mode,
		boolean includeGeTax,
		Map<Integer, CustomPriceOverride> customPrices)
	{
		if (finalRecipe == null)
		{
			return MultiStepAnalysis.builder()
				.hasMultiStepChain(false)
				.recommendation("UNAVAILABLE")
				.summaryText("No recipe selected.")
				.build();
		}

		// Collect direct recipe buy-intermediate economics using single-step ProfitCalculator
		CraftingResult directResult = ProfitCalculator.evaluate(
			finalRecipe, prices, nameToIdIndex, mode, includeGeTax, customPrices, null, null);

		Map<Integer, Double> buyDirectQty = new LinkedHashMap<>();
		for (RecipeInput in : finalRecipe.getInputs())
		{
			if (in.isConsumed())
			{
				buyDirectQty.merge(in.getItemId(), in.getQuantity(), Double::sum);
			}
		}

		// Build upstream stage map: outputItemId -> producer CraftingRecipe
		// Prioritize explicit intermediateRecipeIds, then safe direct single-step Crafting producers
		Map<Integer, CraftingRecipe> producerByItemId = buildProducerIndex(allRecipes);
		List<StageSummary> chain = buildChainStages(finalRecipe, producerByItemId, prices, nameToIdIndex, mode, includeGeTax, customPrices);

		if (chain.size() <= 1)
		{
			return MultiStepAnalysis.builder()
				.hasMultiStepChain(false)
				.finalRecipe(finalRecipe)
				.stages(chain)
				.buyIntermediateAvailable(directResult.isPriceDataComplete())
				.buyIntermediateCost(directResult.getMaterialCostPerCraft())
				.buyIntermediateNetRevenue(directResult.getNetRevenuePerCraft())
				.buyIntermediateProfit(directResult.getProfitPerCraft())
				.buyIntermediateXp(finalRecipe.getXpPerAction())
				.buyIntermediateGpPerXp(directResult.getGpPerXp())
				.makeAllStepsAvailable(false)
				.recommendation("SINGLE STEP")
				.summaryText("Single-step method (no upstream Crafting stage applies).")
				.buyDirectMaterialQuantities(Collections.unmodifiableMap(buyDirectQty))
				.build();
		}

		// Compute full raw-to-final net cost & revenue WITHOUT double-counting intermediate items!
		// Because stages[0 .. N-2] are crafted solely to supply stages downstream, their internal
		// outputs are NOT sold on GE (only unconsumed secondary byproducts are sold), and downstream
		// recipes do NOT pay GP for self-crafted intermediate inputs.
		double makeRawCost = 0.0;
		double makeSecondaryNet = 0.0;
		double makeTotalXp = 0.0;
		boolean makeComplete = true;
		Map<Integer, Double> rawQtyMap = new LinkedHashMap<>();
		Set<Integer> internallyCraftedOutputs = new LinkedHashSet<>();

		for (int idx = 0; idx < chain.size() - 1; idx++)
		{
			RecipeOutput primaryOut = chain.get(idx).getRecipe().getPrimaryOutput();
			if (primaryOut != null)
			{
				internallyCraftedOutputs.add(primaryOut.getItemId());
			}
		}

		for (int idx = 0; idx < chain.size(); idx++)
		{
			StageSummary stage = chain.get(idx);
			CraftingRecipe r = stage.getRecipe();
			double scale = stage.getMultiplierForOneFinal();
			makeTotalXp += stage.getStageXpTotal();

			for (RecipeInput in : r.getInputs())
			{
				if (!in.isConsumed())
				{
					continue;
				}
				// Do NOT pay GE buy cost if this input is supplied by an earlier Crafting stage in the chain
				if (idx > 0 && internallyCraftedOutputs.contains(in.getItemId()))
				{
					continue;
				}
				double qty = in.getQuantity() * scale;
				rawQtyMap.merge(in.getItemId(), qty, Double::sum);
				if (in.getItemId() == ItemID.COINS_995)
				{
					makeRawCost += qty;
					continue;
				}
				ItemPrice ip = ProfitCalculator.resolveItemPrice(in.getItemId(), in.getItemName(), prices, nameToIdIndex);
				Long buy = resolveBuy(ip, mode, customPrices, in.getItemId());
				if (buy == null || buy <= 0L)
				{
					makeComplete = false;
				}
				else
				{
					makeRawCost += qty * buy;
				}
			}

			// Secondary outputs of any stage (or all non-final stage secondary byproducts) contribute net value
			List<RecipeOutput> outs = r.getOutputs();
			for (int oi = 0; oi < outs.size(); oi++)
			{
				RecipeOutput out = outs.get(oi);
				boolean isIntermediateForNext = (idx < chain.size() - 1) && oi == 0;
				if (isIntermediateForNext || !out.isTradeable())
				{
					continue;
				}
				if (idx == chain.size() - 1)
				{
					// Handled in final revenue below
					continue;
				}
				ItemPrice ip = ProfitCalculator.resolveItemPrice(out.getItemId(), out.getItemName(), prices, nameToIdIndex);
				Long sell = resolveSell(ip, mode, customPrices, out.getItemId());
				if (sell != null && sell > 0L)
				{
					double outQty = out.getExpectedQuantity() * scale;
					double tax = GETransactionCalculator.calculateExpectedTax(
						sell, outQty, out.getItemId(), out.isTaxExempt(), includeGeTax);
					makeSecondaryNet += (outQty * sell) - tax;
				}
			}
		}

		double makeFinalNetRev = directResult.isPriceDataComplete()
			? directResult.getNetRevenuePerCraft() + makeSecondaryNet
			: Double.NaN;
		if (!directResult.isPriceDataComplete())
		{
			makeComplete = false;
		}

		double makeProfit = makeComplete ? (makeFinalNetRev - makeRawCost) : Double.NaN;
		double makeGpPerXp = (makeComplete && makeTotalXp > 0.0) ? (makeProfit / makeTotalXp) : Double.NaN;
		double deltaProfit = (makeComplete && directResult.isPriceDataComplete())
			? (makeProfit - directResult.getProfitPerCraft())
			: Double.NaN;
		double xpGain = makeTotalXp - finalRecipe.getXpPerAction();

		String rec = "UNAVAILABLE";
		String summary = "Incomplete market prices for multi-step comparison.";
		if (makeComplete && directResult.isPriceDataComplete())
		{
			if (deltaProfit >= 0.0)
			{
				rec = "MAKE INTERMEDIATE";
				summary = String.format(java.util.Locale.US,
					"Making upstream stage(s) yields %+,.0f GP and +%.1f XP per final craft vs buying intermediates.",
					deltaProfit, xpGain);
			}
			else
			{
				rec = "BUY INTERMEDIATE";
				summary = String.format(java.util.Locale.US,
					"Buying intermediate(s) saves %,.0f GP per craft (skips +%.1f upstream XP).",
					Math.abs(deltaProfit), xpGain);
			}
		}

		return MultiStepAnalysis.builder()
			.hasMultiStepChain(true)
			.finalRecipe(finalRecipe)
			.stages(Collections.unmodifiableList(chain))
			.buyIntermediateAvailable(directResult.isPriceDataComplete())
			.buyIntermediateCost(directResult.getMaterialCostPerCraft())
			.buyIntermediateNetRevenue(directResult.getNetRevenuePerCraft())
			.buyIntermediateProfit(directResult.getProfitPerCraft())
			.buyIntermediateXp(finalRecipe.getXpPerAction())
			.buyIntermediateGpPerXp(directResult.getGpPerXp())
			.makeAllStepsAvailable(makeComplete)
			.makeAllRawCost(makeRawCost)
			.makeAllSecondaryNetRevenue(makeSecondaryNet)
			.makeAllFinalNetRevenue(makeFinalNetRev)
			.makeAllProfit(makeProfit)
			.makeAllXp(makeTotalXp)
			.makeAllGpPerXp(makeGpPerXp)
			.recommendation(rec)
			.profitAdvantageMakeVsBuy(deltaProfit)
			.xpGainMakeVsBuy(xpGain)
			.summaryText(summary)
			.makeAllRawMaterialQuantities(Collections.unmodifiableMap(rawQtyMap))
			.buyDirectMaterialQuantities(Collections.unmodifiableMap(buyDirectQty))
			.build();
	}

	private static Map<Integer, CraftingRecipe> buildProducerIndex(List<CraftingRecipe> allRecipes)
	{
		Map<Integer, CraftingRecipe> index = new HashMap<>();
		if (allRecipes == null)
		{
			return index;
		}
		for (CraftingRecipe r : allRecipes)
		{
			if (r == null || r.getPrimaryOutput() == null || r.hasVariableOutcome())
			{
				continue;
			}
			// Avoid choosing multi-step enchantment chains or massive batches as upstream single-item producers
			if (r.getId().endsWith("_chain"))
			{
				continue;
			}
			int outId = r.getPrimaryOutput().getItemId();
			// Prefer simpler single-output deterministic recipes (e.g. cut gems, molten glass, leather body, ball of wool)
			CraftingRecipe existing = index.get(outId);
			if (existing == null || r.getInputs().size() < existing.getInputs().size())
			{
				index.put(outId, r);
			}
		}
		return index;
	}

	private static List<StageSummary> buildChainStages(
		CraftingRecipe finalRecipe,
		Map<Integer, CraftingRecipe> producerByItemId,
		Map<Integer, ItemPrice> prices,
		Map<String, Integer> nameToIdIndex,
		PriceCalculationMode mode,
		boolean includeGeTax,
		Map<Integer, CustomPriceOverride> customPrices)
	{
		List<StageSummary> reversed = new ArrayList<>();
		Set<String> visitedIds = new LinkedHashSet<>();

		// Start with final stage
		reversed.add(StageSummary.builder()
			.stageIndex(0)
			.recipe(finalRecipe)
			.multiplierForOneFinal(1.0)
			.stageXpTotal(finalRecipe.getXpPerAction())
			.build());
		visitedIds.add(finalRecipe.getId());

		// Check explicit intermediateRecipeIds first
		if (finalRecipe.getIntermediateRecipeIds() != null && !finalRecipe.getIntermediateRecipeIds().isEmpty())
		{
			List<String> interIds = finalRecipe.getIntermediateRecipeIds();
			for (int i = interIds.size() - 1; i >= 0; i--)
			{
				CraftingRecipe inter = CraftingDataRepository.getById(interIds.get(i));
				if (inter != null && visitedIds.add(inter.getId()))
				{
					double mult = inferScaleMultiplier(inter, finalRecipe);
					CraftingResult sr = ProfitCalculator.evaluate(
						inter, prices, nameToIdIndex, mode, includeGeTax, customPrices, null, null);
					reversed.add(StageSummary.builder()
						.stageIndex(reversed.size())
						.recipe(inter)
						.multiplierForOneFinal(mult)
						.stageXpTotal(inter.getXpPerAction() * mult)
						.standaloneProfitPerAction(sr.isPriceDataComplete() ? sr.getProfitPerCraft() : Double.NaN)
						.build());
				}
			}
		}
		else
		{
			// Auto-discover up to 2 direct Crafting upstream producers (e.g. Amulet -> Amulet (u) -> Cut Gem)
			CraftingRecipe current = finalRecipe;
			double cumulativeScale = 1.0;
			for (int depth = 0; depth < 2; depth++)
			{
				CraftingRecipe upstream = null;
				double neededFromUpstream = 1.0;
				for (RecipeInput in : current.getInputs())
				{
					if (!in.isConsumed())
					{
						continue;
					}
					CraftingRecipe candidate = producerByItemId.get(in.getItemId());
					if (candidate != null && visitedIds.add(candidate.getId()))
					{
						upstream = candidate;
						double outQty = candidate.getPrimaryOutput() != null
							? Math.max(1e-6, candidate.getPrimaryOutput().getExpectedQuantity())
							: 1.0;
						neededFromUpstream = in.getQuantity() / outQty;
						break;
					}
				}
				if (upstream == null)
				{
					break;
				}
				cumulativeScale *= neededFromUpstream;
				CraftingResult sr = ProfitCalculator.evaluate(
					upstream, prices, nameToIdIndex, mode, includeGeTax, customPrices, null, null);
				reversed.add(StageSummary.builder()
					.stageIndex(reversed.size())
					.recipe(upstream)
					.multiplierForOneFinal(cumulativeScale)
					.stageXpTotal(upstream.getXpPerAction() * cumulativeScale)
					.standaloneProfitPerAction(sr.isPriceDataComplete() ? sr.getProfitPerCraft() : Double.NaN)
					.build());
				current = upstream;
			}
		}

		// Reverse so upstream raw stage comes first (0 -> N-1)
		Collections.reverse(reversed);
		List<StageSummary> ordered = new ArrayList<>(reversed.size());
		for (int i = 0; i < reversed.size(); i++)
		{
			StageSummary s = reversed.get(i);
			ordered.add(StageSummary.builder()
				.stageIndex(i + 1)
				.recipe(s.getRecipe())
				.multiplierForOneFinal(s.getMultiplierForOneFinal())
				.stageXpTotal(s.getStageXpTotal())
				.standaloneProfitPerAction(s.getStandaloneProfitPerAction())
				.build());
		}
		return ordered;
	}

	private static double inferScaleMultiplier(CraftingRecipe upstream, CraftingRecipe downstream)
	{
		if (upstream.getPrimaryOutput() == null)
		{
			return 1.0;
		}
		int producedId = upstream.getPrimaryOutput().getItemId();
		double outQty = Math.max(1e-6, upstream.getPrimaryOutput().getExpectedQuantity());
		for (RecipeInput in : downstream.getInputs())
		{
			if (in.isConsumed() && in.getItemId() == producedId)
			{
				return in.getQuantity() / outQty;
			}
		}
		return 1.0;
	}

	private static Long resolveBuy(
		ItemPrice ip,
		PriceCalculationMode mode,
		Map<Integer, CustomPriceOverride> customPrices,
		int itemId)
	{
		if (customPrices != null)
		{
			CustomPriceOverride ov = customPrices.get(itemId);
			if (ov != null && ov.getBuyPrice() != null && ov.getBuyPrice() > 0L)
			{
				return ov.getBuyPrice();
			}
		}
		if (ip == null)
		{
			return null;
		}
		if (mode == PriceCalculationMode.CUSTOM)
		{
			return ip.getAverageMarketPrice();
		}
		return ip.resolveBuyPrice(mode, null);
	}

	private static Long resolveSell(
		ItemPrice ip,
		PriceCalculationMode mode,
		Map<Integer, CustomPriceOverride> customPrices,
		int itemId)
	{
		if (customPrices != null)
		{
			CustomPriceOverride ov = customPrices.get(itemId);
			if (ov != null && ov.getSellPrice() != null && ov.getSellPrice() > 0L)
			{
				return ov.getSellPrice();
			}
		}
		if (ip == null)
		{
			return null;
		}
		if (mode == PriceCalculationMode.CUSTOM)
		{
			return ip.getAverageMarketPrice();
		}
		return ip.resolveSellPrice(mode, null);
	}
}

package com.craftwise.calculator;

import com.craftwise.CraftWiseConfig.PriceCalculationMode;
import com.craftwise.data.CraftingRecipe;
import com.craftwise.data.CraftingRecipe.RecipeInput;
import com.craftwise.data.CraftingRecipe.RecipeOutput;
import com.craftwise.model.CraftingResult;
import com.craftwise.model.CraftingResult.BreakEvenStatus;
import com.craftwise.model.CraftingResult.XpRateSource;
import com.craftwise.model.ItemPrice;
import com.craftwise.model.PlayerCraftingStats;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import lombok.AllArgsConstructor;
import lombok.Data;
import net.runelite.api.ItemID;

/**
 * Calculates per-craft, batch, hourly, and target-level financial and XP results
 * for every {@link CraftingRecipe}.
 * Never substitutes 0 GP for missing market prices; incomplete recipes are explicitly flagged.
 */
public final class ProfitCalculator
{
	@Data
	@AllArgsConstructor
	public static class CustomPriceOverride
	{
		private final Long buyPrice;
		private final Long sellPrice;
	}

	private ProfitCalculator()
	{
	}

	public static CraftingResult evaluate(
		CraftingRecipe recipe,
		Map<Integer, ItemPrice> prices,
		PriceCalculationMode mode,
		boolean includeGeTax,
		Map<Integer, CustomPriceOverride> customPrices,
		Map<String, Double> customActionsPerHour,
		PlayerCraftingStats playerStats)
	{
		return evaluate(recipe, prices, Collections.emptyMap(), mode, includeGeTax,
			customPrices, customActionsPerHour, playerStats);
	}

	public static CraftingResult evaluate(
		CraftingRecipe recipe,
		Map<Integer, ItemPrice> prices,
		Map<String, Integer> nameToIdIndex,
		PriceCalculationMode mode,
		boolean includeGeTax,
		Map<Integer, CustomPriceOverride> customPrices,
		Map<String, Double> customActionsPerHour,
		PlayerCraftingStats playerStats)
	{
		PriceCalculationMode safeMode = mode != null ? mode : PriceCalculationMode.INSTANT_BUY_SELL;
		Map<Integer, ItemPrice> safePrices = prices != null ? prices : Collections.emptyMap();

		List<Integer> missingIds = new ArrayList<>();
		List<String> missingNames = new ArrayList<>();
		boolean usingStale = false;
		boolean usingCustom = false;

		double materialCost = 0.0;
		long minInput1hVol = Long.MAX_VALUE;
		boolean hasTrackedInputVol = false;

		for (RecipeInput input : recipe.getInputs())
		{
			if (!input.isConsumed())
			{
				continue;
			}
			if (input.getItemId() == ItemID.COINS_995)
			{
				materialCost += input.getQuantity();
				continue;
			}

			ItemPrice ip = resolveItemPrice(input.getItemId(), input.getItemName(), safePrices, nameToIdIndex);
			if (ip != null && ip.isStale())
			{
				usingStale = true;
			}
			if (ip != null && ip.getTotal1hVolume() > 0L)
			{
				minInput1hVol = Math.min(minInput1hVol, ip.getTotal1hVolume());
				hasTrackedInputVol = true;
			}

			Long customBuy = getCustomBuy(customPrices, input.getItemId());
			Long resolvedBuy = resolveUnitBuyPrice(ip, safeMode, customBuy);
			if (customBuy != null && customBuy > 0L && (safeMode == PriceCalculationMode.CUSTOM || resolvedBuy.equals(customBuy)))
			{
				usingCustom = true;
			}

			if (resolvedBuy == null || resolvedBuy <= 0L)
			{
				missingIds.add(input.getItemId());
				missingNames.add(input.getItemName());
			}
			else
			{
				materialCost += input.getQuantity() * resolvedBuy;
			}
		}

		double grossRevenue = 0.0;
		double geTax = 0.0;
		double secondaryNetRevenue = 0.0;
		Long primarySellPrice = null;
		long primary1hVol = 0L;

		List<RecipeOutput> outputs = recipe.getOutputs();
		for (int i = 0; i < outputs.size(); i++)
		{
			RecipeOutput output = outputs.get(i);
			if (!output.isTradeable())
			{
				if (i == 0)
				{
					primarySellPrice = 0L;
				}
				continue;
			}

			ItemPrice ip = resolveItemPrice(output.getItemId(), output.getItemName(), safePrices, nameToIdIndex);
			if (ip != null && ip.isStale())
			{
				usingStale = true;
			}
			if (i == 0 && ip != null)
			{
				primary1hVol = ip.getTotal1hVolume();
			}

			Long customSell = getCustomSell(customPrices, output.getItemId());
			Long resolvedSell = resolveUnitSellPrice(ip, safeMode, customSell);
			if (customSell != null && customSell > 0L && (safeMode == PriceCalculationMode.CUSTOM || resolvedSell != null && resolvedSell.equals(customSell)))
			{
				usingCustom = true;
			}

			// Crushed gem is effectively ~1 gp vendor/worthless if missing on GE; don't invalidate semi-precious gem if crushed gem has no recent GE trade
			if ((resolvedSell == null || resolvedSell <= 0L) && output.getItemId() == ItemID.CRUSHED_GEM)
			{
				resolvedSell = 1L;
			}

			if (resolvedSell == null || resolvedSell <= 0L)
			{
				missingIds.add(output.getItemId());
				missingNames.add(output.getItemName());
			}
			else
			{
				double expectedQty = output.getExpectedQuantity();
				double grossForOut = expectedQty * resolvedSell;
				double taxForOut = GETransactionCalculator.calculateExpectedTax(
					resolvedSell, expectedQty, output.getItemId(), output.isTaxExempt(), includeGeTax);
				grossRevenue += grossForOut;
				geTax += taxForOut;
				if (i == 0)
				{
					primarySellPrice = resolvedSell;
				}
				else
				{
					secondaryNetRevenue += (grossForOut - taxForOut);
				}
			}
		}

		// Realistic XP rate & inventory breakdown (Phase 10)
		Double customActionOverride = (customActionsPerHour != null) ? customActionsPerHour.get(recipe.getId()) : null;
		RealisticXpRateCalculator.XpRateBreakdown xpBreakdown = RealisticXpRateCalculator.calculate(
			recipe, customActionOverride != null ? customActionOverride : 0.0);
		double actionsPerHour = xpBreakdown.getActionsPerHour();
		XpRateSource xpSource = xpBreakdown.getXpRateSource();
		double xpPerAction = xpBreakdown.getXpPerAction();
		double xpPerHour = xpBreakdown.getXpPerHour();

		// Market liquidity, spread & recency confidence (Phase 7)
		List<ItemPrice> tradedPrices = new ArrayList<>();
		ItemPrice primaryOutputPrice = null;
		for (RecipeInput input : recipe.getInputs())
		{
			if (input.isConsumed() && input.getItemId() != ItemID.COINS_995)
			{
				ItemPrice ip = resolveItemPrice(input.getItemId(), input.getItemName(), safePrices, nameToIdIndex);
				if (ip != null)
				{
					tradedPrices.add(ip);
				}
			}
		}
		for (int i = 0; i < outputs.size(); i++)
		{
			RecipeOutput output = outputs.get(i);
			if (output.isTradeable())
			{
				ItemPrice ip = resolveItemPrice(output.getItemId(), output.getItemName(), safePrices, nameToIdIndex);
				if (i == 0)
				{
					primaryOutputPrice = ip;
				}
				if (ip != null)
				{
					tradedPrices.add(ip);
				}
			}
		}
		long nowEpochSeconds = System.currentTimeMillis() / 1000L;
		MarketConfidenceEvaluator.MarketEvaluation marketEval = MarketConfidenceEvaluator.evaluate(
			missingIds.isEmpty(), tradedPrices, primaryOutputPrice, nowEpochSeconds);

		boolean complete = missingIds.isEmpty();
		if (!complete)
		{
			return CraftingResult.builder()
				.recipe(recipe)
				.priceMode(safeMode)
				.geTaxApplied(includeGeTax)
				.priceDataComplete(false)
				.usingStalePrices(usingStale)
				.usingCustomOverrides(usingCustom)
				.missingPriceItemIds(Collections.unmodifiableList(missingIds))
				.missingPriceItemNames(Collections.unmodifiableList(missingNames))
				.xpPerAction(xpPerAction)
				.actionsPerHour(actionsPerHour)
				.xpPerHour(xpPerHour)
				.xpRateSource(xpSource)
				.itemsPerInventory(xpBreakdown.getItemsPerInventory())
				.actionsPerMinute(xpBreakdown.getActionsPerMinute())
				.gpPerXp(Double.NaN)
				.breakEvenStatus(BreakEvenStatus.UNAVAILABLE)
				.primaryOutput1hVolume(primary1hVol)
				.minInput1hVolume(hasTrackedInputVol ? minInput1hVol : 0L)
				.min1hVolume(marketEval.getMin1hVolume())
				.worstSpreadPercent(marketEval.getWorstSpreadPercent())
				.oldestPriceAgeSeconds(marketEval.getOldestPriceAgeSeconds())
				.priceConfidence(marketEval.getConfidence())
				.marketWarnings(marketEval.getWarnings())
				.variableOutcome(recipe.hasVariableOutcome())
				.calculationNotice(MarketConfidenceEvaluator.GE_EXECUTION_DISCLAIMER)
				.build();
		}

		// Snap deterministic integer-quantity crafts to exact integer GP totals to eliminate float noise
		if (!recipe.hasVariableOutcome())
		{
			materialCost = Math.round(materialCost);
			grossRevenue = Math.round(grossRevenue);
			geTax = Math.round(geTax);
		}

		double netRevenue = grossRevenue - geTax;
		double profitPerCraft = netRevenue - materialCost;
		double profitPerInventory = profitPerCraft * xpBreakdown.getItemsPerInventory();
		double profitPerHour = profitPerCraft * actionsPerHour;
		double gpPerXp = xpPerAction > 0.0 ? profitPerCraft / xpPerAction : Double.NaN;

		Long breakEvenSell = null;
		BreakEvenStatus beStatus = BreakEvenStatus.UNAVAILABLE;
		if (recipe.isTradeableOutput() && recipe.getPrimaryOutput() != null)
		{
			RecipeOutput primary = recipe.getPrimaryOutput();
			breakEvenSell = BreakEvenCalculator.calculateMinSellingPrice(
				materialCost,
				primary.getExpectedQuantity(),
				secondaryNetRevenue,
				primary.getItemId(),
				primary.isTaxExempt(),
				includeGeTax
			);
			beStatus = BreakEvenCalculator.classifyStatus(profitPerCraft, materialCost);
		}
		else if (!recipe.isTradeableOutput())
		{
			beStatus = materialCost > 0.0 ? BreakEvenStatus.LOSS : BreakEvenStatus.PROFITABLE;
		}

		long actionsToTarget = 0L;
		double totalCostToTarget = 0.0;
		double totalProfitToTarget = 0.0;
		double hoursToTarget = 0.0;
		if (playerStats != null && playerStats.getXpToTarget() > 0L && xpPerAction > 0.0)
		{
			actionsToTarget = (long) Math.ceil(playerStats.getXpToTarget() / xpPerAction);
			totalCostToTarget = actionsToTarget * materialCost;
			totalProfitToTarget = actionsToTarget * profitPerCraft;
			hoursToTarget = actionsPerHour > 0.0 ? actionsToTarget / actionsPerHour : 0.0;
		}

		List<String> breakdown = buildBreakdownLines(
			recipe, safeMode, includeGeTax, materialCost, grossRevenue, geTax, netRevenue,
			profitPerCraft, profitPerInventory, breakEvenSell, primarySellPrice, xpBreakdown, marketEval);

		return CraftingResult.builder()
			.recipe(recipe)
			.priceMode(safeMode)
			.geTaxApplied(includeGeTax)
			.priceDataComplete(true)
			.usingStalePrices(usingStale)
			.usingCustomOverrides(usingCustom)
			.materialCostPerCraft(materialCost)
			.grossRevenuePerCraft(grossRevenue)
			.geTaxPerCraft(geTax)
			.netRevenuePerCraft(netRevenue)
			.profitPerCraft(profitPerCraft)
			.profit10(profitPerCraft * 10.0)
			.profit100(profitPerCraft * 100.0)
			.profit1000(profitPerCraft * 1000.0)
			.xpPerAction(xpPerAction)
			.actionsPerHour(actionsPerHour)
			.xpPerHour(xpPerHour)
			.xpRateSource(xpSource)
			.profitPerHour(profitPerHour)
			.gpPerXp(gpPerXp)
			.breakEvenSellPrice(breakEvenSell)
			.primaryOutputMarketPrice(primarySellPrice)
			.breakEvenStatus(beStatus)
			.actionsToTarget(actionsToTarget)
			.totalCostToTarget(totalCostToTarget)
			.totalProfitToTarget(totalProfitToTarget)
			.hoursToTarget(hoursToTarget)
			.primaryOutput1hVolume(primary1hVol)
			.minInput1hVolume(hasTrackedInputVol ? minInput1hVol : 0L)
			.min1hVolume(marketEval.getMin1hVolume())
			.worstSpreadPercent(marketEval.getWorstSpreadPercent())
			.oldestPriceAgeSeconds(marketEval.getOldestPriceAgeSeconds())
			.priceConfidence(marketEval.getConfidence())
			.marketWarnings(marketEval.getWarnings())
			.itemsPerInventory(xpBreakdown.getItemsPerInventory())
			.actionsPerMinute(xpBreakdown.getActionsPerMinute())
			.profitPerInventory(profitPerInventory)
			.variableOutcome(recipe.hasVariableOutcome())
			.calculationNotice(MarketConfidenceEvaluator.GE_EXECUTION_DISCLAIMER)
			.calculationBreakdown(breakdown)
			.build();
	}

	private static List<String> buildBreakdownLines(
		CraftingRecipe recipe,
		PriceCalculationMode mode,
		boolean includeGeTax,
		double materialCost,
		double grossRevenue,
		double geTax,
		double netRevenue,
		double profitPerCraft,
		double profitPerInventory,
		Long breakEvenSell,
		Long primarySellPrice,
		RealisticXpRateCalculator.XpRateBreakdown xpBreakdown,
		MarketConfidenceEvaluator.MarketEvaluation marketEval)
	{
		List<String> lines = new ArrayList<>();
		lines.add("Pricing Scenario: " + (mode != null ? mode.getLabel() : PriceCalculationMode.INSTANT_BUY_SELL.getLabel()));
		lines.add(String.format(java.util.Locale.US, "1. Consumed Materials Cost: %,.0f GP / action", materialCost));
		lines.add(String.format(java.util.Locale.US, "2. Gross GE Output Value: %,.0f GP%s",
			grossRevenue, recipe.hasVariableOutcome() ? " (expected average value)" : ""));
		lines.add(String.format(java.util.Locale.US, "3. Grand Exchange Tax: %,.0f GP (%s)",
			geTax, includeGeTax ? "2% per unit >= 50 GP, 5M cap, tools/low items exempt" : "disabled"));
		lines.add(String.format(java.util.Locale.US, "4. Net Revenue After Tax: %,.0f GP", netRevenue));
		lines.add(String.format(java.util.Locale.US, "5. Net Profit / Action: %+,.0f GP (%+,.0f GP / inventory of %d)",
			profitPerCraft, profitPerInventory, xpBreakdown.getItemsPerInventory()));
		if (breakEvenSell != null && primarySellPrice != null)
		{
			lines.add(String.format(java.util.Locale.US, "6. Primary Sell Price: %,d GP vs Exact Break-Even: %,d GP",
				primarySellPrice, breakEvenSell));
		}
		lines.add("7. Throughput Model (" + xpBreakdown.getXpRateSource().getLabel() + "): " + xpBreakdown.getModelExplanation());
		lines.add(String.format(java.util.Locale.US, "8. Market Confidence: %s (Min 1h vol: %,d, Worst spread: %.1f%%)",
			marketEval.getConfidence().getLabel(), marketEval.getMin1hVolume(), marketEval.getWorstSpreadPercent()));
		lines.add(MarketConfidenceEvaluator.GE_EXECUTION_DISCLAIMER);
		return Collections.unmodifiableList(lines);
	}

	public static ItemPrice resolveItemPrice(
		int itemId,
		String itemName,
		Map<Integer, ItemPrice> prices,
		Map<String, Integer> nameToIdIndex)
	{
		if (prices == null || prices.isEmpty())
		{
			return null;
		}
		ItemPrice direct = prices.get(itemId);
		if (direct != null && direct.hasAnyMarketPrice())
		{
			return direct;
		}
		if (itemName != null && nameToIdIndex != null && !nameToIdIndex.isEmpty())
		{
			Integer mappedId = nameToIdIndex.get(itemName.trim().toLowerCase(java.util.Locale.ROOT));
			if (mappedId != null)
			{
				ItemPrice byName = prices.get(mappedId);
				if (byName != null)
				{
					return byName;
				}
			}
		}
		return direct;
	}

	private static Long getCustomBuy(Map<Integer, CustomPriceOverride> customPrices, int itemId)
	{
		if (customPrices == null)
		{
			return null;
		}
		CustomPriceOverride ov = customPrices.get(itemId);
		return ov != null ? ov.getBuyPrice() : null;
	}

	private static Long getCustomSell(Map<Integer, CustomPriceOverride> customPrices, int itemId)
	{
		if (customPrices == null)
		{
			return null;
		}
		CustomPriceOverride ov = customPrices.get(itemId);
		return ov != null ? ov.getSellPrice() : null;
	}

	private static Long resolveUnitBuyPrice(ItemPrice ip, PriceCalculationMode mode, Long customBuy)
	{
		if (customBuy != null && customBuy > 0L)
		{
			return customBuy;
		}
		if (ip == null)
		{
			return null;
		}
		if (mode == PriceCalculationMode.CUSTOM)
		{
			// Fallback to average market price for un-overridden ingredients in Custom mode
			return ip.getAverageMarketPrice();
		}
		return ip.resolveBuyPrice(mode, null);
	}

	private static Long resolveUnitSellPrice(ItemPrice ip, PriceCalculationMode mode, Long customSell)
	{
		if (customSell != null && customSell > 0L)
		{
			return customSell;
		}
		if (ip == null)
		{
			return null;
		}
		if (mode == PriceCalculationMode.CUSTOM)
		{
			return ip.getAverageMarketPrice();
		}
		return ip.resolveSellPrice(mode, null);
	}
}

package com.craftwise.calculator;

import com.craftwise.data.CraftingRecipe;
import com.craftwise.model.CraftingResult.XpRateSource;
import lombok.Builder;
import lombok.Data;

/**
 * Computes transparent crafting throughput (actions/min, items/inventory, actions/hour, XP/hour)
 * distinguishing explicitly between user-configured overrides and realistic bank-inclusive estimates.
 */
public final class RealisticXpRateCalculator
{
	@Data
	@Builder
	public static class XpRateBreakdown
	{
		private final double actionsPerHour;
		private final double actionsPerMinute;
		private final int itemsPerInventory;
		private final double xpPerAction;
		private final double xpPerHour;
		private final XpRateSource xpRateSource;
		private final String modelExplanation;
	}

	private RealisticXpRateCalculator()
	{
	}

	public static XpRateBreakdown calculate(CraftingRecipe recipe, double customActionsPerHour)
	{
		int perInv = Math.max(1, InventoryCalculator.calculateCraftsPerInventory(recipe));
		double xpPerAction = Math.max(0.0, recipe.getXpPerAction());

		if (customActionsPerHour > 0.0)
		{
			return XpRateBreakdown.builder()
				.actionsPerHour(customActionsPerHour)
				.actionsPerMinute(customActionsPerHour / 60.0)
				.itemsPerInventory(perInv)
				.xpPerAction(xpPerAction)
				.xpPerHour(customActionsPerHour * xpPerAction)
				.xpRateSource(XpRateSource.USER_CONFIGURED)
				.modelExplanation(String.format(
					"User override: %.0f actions/hr (%.1f/min), %d actions/inv.",
					customActionsPerHour, customActionsPerHour / 60.0, perInv))
				.build();
		}

		double baselineActionsPerHour = Math.max(1.0, recipe.getEstimatedActionsPerHour());
		double actionsPerMin = baselineActionsPerHour / 60.0;
		double xpPerHour = baselineActionsPerHour * xpPerAction;

		XpRateSource source = recipe.getEstimatedActionsPerHour() > 0
			? XpRateSource.ESTIMATED
			: XpRateSource.ESTIMATED;

		String explanation = String.format(
			"Estimated practical rate: %.0f actions/hr (%.1f/min) across %d crafts/inv (includes banking overhead).",
			baselineActionsPerHour, actionsPerMin, perInv);

		return XpRateBreakdown.builder()
			.actionsPerHour(baselineActionsPerHour)
			.actionsPerMinute(actionsPerMin)
			.itemsPerInventory(perInv)
			.xpPerAction(xpPerAction)
			.xpPerHour(xpPerHour)
			.xpRateSource(source)
			.modelExplanation(explanation)
			.build();
	}
}

package com.craftwise.calculator;

import com.craftwise.CraftWiseConfig.PriceCalculationMode;
import com.craftwise.calculator.ProfitCalculator.CustomPriceOverride;
import com.craftwise.data.CraftingRecipe;
import com.craftwise.data.CraftingRecipe.RecipeInput;
import com.craftwise.model.ItemPrice;
import com.craftwise.model.TrainingPlan;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import lombok.Builder;
import lombok.Data;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.ItemID;

/**
 * Phase 11: Material Shopping List generator & exporter.
 * Aggregates and deduplicates consumed materials across recipes, multi-step chains,
 * or multi-stage training plans, subtracts player-owned quantities, and computes
 * remaining buy quantities and exact GP costs.
 */
public final class ShoppingListCalculator
{
	@Getter
	@RequiredArgsConstructor
	public enum ShoppingSortOrder
	{
		TOTAL_COST_DESC("Highest Cost"),
		QUANTITY_DESC("Largest Quantity"),
		STAGE_ORDER("Crafting Order"),
		NAME_ASC("Name (A-Z)");

		private final String label;
	}

	@Data
	@Builder
	public static class ShoppingListItem
	{
		private final int itemId;
		private final String itemName;
		private final String stageLabel;
		private final int firstStageOrder;
		private final long totalRequiredQty;
		private final long ownedQty;
		private final long remainingToBuyQty;
		private final long unitBuyPrice;
		private final boolean priceAvailable;
		private final long totalRemainingCostGp;
		private final boolean tradeable;
	}

	@Data
	@Builder
	public static class ShoppingListSummary
	{
		@Builder.Default
		private final List<ShoppingListItem> items = Collections.emptyList();
		@Builder.Default
		private final List<String> requiredToolsAndMoulds = Collections.emptyList();
		private final long totalRemainingCostGp;
		private final long totalUniqueMaterials;
		private final boolean allPricesAvailable;
	}

	private static final class Accumulator
	{
		final int itemId;
		final String itemName;
		final String stageLabel;
		final int stageOrder;
		final boolean tradeable;
		double totalQty;

		Accumulator(int itemId, String itemName, String stageLabel, int stageOrder, boolean tradeable)
		{
			this.itemId = itemId;
			this.itemName = itemName;
			this.stageLabel = stageLabel;
			this.stageOrder = stageOrder;
			this.tradeable = tradeable;
		}
	}

	private ShoppingListCalculator()
	{
	}

	public static ShoppingListSummary fromSingleRecipe(
		CraftingRecipe recipe,
		long actions,
		Map<Integer, Long> ownedByItemId,
		Map<Integer, ItemPrice> prices,
		Map<String, Integer> nameToIdIndex,
		PriceCalculationMode mode,
		Map<Integer, CustomPriceOverride> customPrices,
		ShoppingSortOrder sortOrder)
	{
		if (recipe == null || actions <= 0L)
		{
			return ShoppingListSummary.builder().allPricesAvailable(true).build();
		}
		Map<Integer, Accumulator> acc = new LinkedHashMap<>();
		List<String> tools = new ArrayList<>();
		collectTools(recipe, tools);

		for (RecipeInput in : recipe.getInputs())
		{
			if (!in.isConsumed())
			{
				continue;
			}
			Accumulator existing = acc.get(in.getItemId());
			if (existing == null)
			{
				existing = new Accumulator(in.getItemId(), in.getItemName(), recipe.getName(), 1, true);
				acc.put(in.getItemId(), existing);
			}
			existing.totalQty += in.getQuantity() * actions;
		}
		return finalizeSummary(acc, tools, ownedByItemId, prices, nameToIdIndex, mode, customPrices, sortOrder);
	}

	public static ShoppingListSummary fromTrainingPlan(
		TrainingPlan plan,
		Map<Integer, Long> ownedByItemId,
		Map<Integer, ItemPrice> prices,
		Map<String, Integer> nameToIdIndex,
		PriceCalculationMode mode,
		Map<Integer, CustomPriceOverride> customPrices,
		ShoppingSortOrder sortOrder)
	{
		if (plan == null || plan.getStages() == null || plan.getStages().isEmpty())
		{
			return ShoppingListSummary.builder().allPricesAvailable(true).build();
		}
		Map<Integer, Accumulator> acc = new LinkedHashMap<>();
		List<String> tools = new ArrayList<>();
		int stageIdx = 1;
		for (TrainingPlan.TrainingStage step : plan.getStages())
		{
			CraftingRecipe r = step.getRecipe();
			if (r == null || step.getActionsNeeded() <= 0L)
			{
				continue;
			}
			collectTools(r, tools);
			String stageLbl = "Lvl " + step.getFromLevel() + "-" + step.getToLevel() + " (" + r.getName() + ")";
			for (RecipeInput in : r.getInputs())
			{
				if (!in.isConsumed())
				{
					continue;
				}
				Accumulator existing = acc.get(in.getItemId());
				if (existing == null)
				{
					existing = new Accumulator(in.getItemId(), in.getItemName(), stageLbl, stageIdx, true);
					acc.put(in.getItemId(), existing);
				}
				existing.totalQty += in.getQuantity() * step.getActionsNeeded();
			}
			stageIdx++;
		}
		return finalizeSummary(acc, tools, ownedByItemId, prices, nameToIdIndex, mode, customPrices, sortOrder);
	}

	private static void collectTools(CraftingRecipe recipe, List<String> tools)
	{
		for (String t : recipe.getAllToolsAndMoulds())
		{
			if (t != null && !t.trim().isEmpty() && !tools.contains(t.trim()))
			{
				tools.add(t.trim());
			}
		}
	}

	private static ShoppingListSummary finalizeSummary(
		Map<Integer, Accumulator> accMap,
		List<String> tools,
		Map<Integer, Long> ownedByItemId,
		Map<Integer, ItemPrice> prices,
		Map<String, Integer> nameToIdIndex,
		PriceCalculationMode mode,
		Map<Integer, CustomPriceOverride> customPrices,
		ShoppingSortOrder sortOrder)
	{
		List<ShoppingListItem> items = new ArrayList<>(accMap.size());
		long totalCost = 0L;
		boolean allAvail = true;

		for (Accumulator a : accMap.values())
		{
			long required = Math.max(0L, (long) Math.ceil(a.totalQty - 1e-9));
			long owned = ownedByItemId != null ? Math.max(0L, ownedByItemId.getOrDefault(a.itemId, 0L)) : 0L;
			long remaining = Math.max(0L, required - owned);

			long unitPrice = 0L;
			boolean priceAvail = true;
			if (a.itemId == ItemID.COINS_995)
			{
				unitPrice = 1L;
			}
			else if (!a.tradeable)
			{
				unitPrice = 0L;
			}
			else
			{
				ItemPrice ip = ProfitCalculator.resolveItemPrice(a.itemId, a.itemName, prices, nameToIdIndex);
				Long buy = null;
				if (customPrices != null && customPrices.containsKey(a.itemId))
				{
					CustomPriceOverride ov = customPrices.get(a.itemId);
					if (ov != null && ov.getBuyPrice() != null && ov.getBuyPrice() > 0L)
					{
						buy = ov.getBuyPrice();
					}
				}
				if (buy == null && ip != null)
				{
					buy = mode == PriceCalculationMode.CUSTOM
						? ip.getAverageMarketPrice()
						: ip.resolveBuyPrice(mode, null);
				}
				if (buy == null || buy <= 0L)
				{
					priceAvail = false;
					allAvail = false;
				}
				else
				{
					unitPrice = buy;
				}
			}

			long rowCost = priceAvail ? remaining * unitPrice : 0L;
			totalCost += rowCost;

			items.add(ShoppingListItem.builder()
				.itemId(a.itemId)
				.itemName(a.itemName)
				.stageLabel(a.stageLabel)
				.firstStageOrder(a.stageOrder)
				.totalRequiredQty(required)
				.ownedQty(owned)
				.remainingToBuyQty(remaining)
				.unitBuyPrice(unitPrice)
				.priceAvailable(priceAvail)
				.totalRemainingCostGp(rowCost)
				.tradeable(a.tradeable)
				.build());
		}

		ShoppingSortOrder effectiveSort = sortOrder != null ? sortOrder : ShoppingSortOrder.TOTAL_COST_DESC;
		switch (effectiveSort)
		{
			case QUANTITY_DESC:
				items.sort(Comparator.comparingLong(ShoppingListItem::getRemainingToBuyQty).reversed());
				break;
			case STAGE_ORDER:
				items.sort(Comparator.comparingInt(ShoppingListItem::getFirstStageOrder));
				break;
			case NAME_ASC:
				items.sort(Comparator.comparing(ShoppingListItem::getItemName, String.CASE_INSENSITIVE_ORDER));
				break;
			case TOTAL_COST_DESC:
			default:
				items.sort(Comparator.comparingLong(ShoppingListItem::getTotalRemainingCostGp).reversed());
				break;
		}

		return ShoppingListSummary.builder()
			.items(Collections.unmodifiableList(items))
			.requiredToolsAndMoulds(Collections.unmodifiableList(tools))
			.totalRemainingCostGp(totalCost)
			.totalUniqueMaterials(items.size())
			.allPricesAvailable(allAvail)
			.build();
	}

	public static String formatPlainText(ShoppingListSummary summary, String title)
	{
		StringBuilder sb = new StringBuilder();
		sb.append("=== CraftWise Shopping List");
		if (title != null && !title.trim().isEmpty())
		{
			sb.append(": ").append(title.trim());
		}
		sb.append(" ===\n");
		if (!summary.getRequiredToolsAndMoulds().isEmpty())
		{
			sb.append("Required Tools/Moulds (not consumed): ")
				.append(String.join(", ", summary.getRequiredToolsAndMoulds()))
				.append("\n");
		}
		for (ShoppingListItem item : summary.getItems())
		{
			sb.append(String.format(Locale.US,
				"- %-26s Need: %,8d | Owned: %,7d | Buy: %,8d | Unit: %s GP | Total: %,d GP%n",
				item.getItemName(),
				item.getTotalRequiredQty(),
				item.getOwnedQty(),
				item.getRemainingToBuyQty(),
				item.isPriceAvailable() ? String.format(Locale.US, "%,d", item.getUnitBuyPrice()) : "N/A",
				item.getTotalRemainingCostGp()));
		}
		sb.append(String.format(Locale.US, "Total Estimated Remaining Cost: %,d GP%s%n",
			summary.getTotalRemainingCostGp(),
			summary.isAllPricesAvailable() ? "" : " (incomplete market prices)"));
		return sb.toString();
	}
}

package com.craftwise.calculator;

import com.craftwise.model.CraftingResult;
import com.craftwise.model.TrainingPlan;
import com.craftwise.model.TrainingPlan.OptimizationObjective;
import com.craftwise.model.TrainingPlan.TrainingStage;
import com.craftwise.util.XPTable;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.TreeSet;

/**
 * Optimizes multi-stage Crafting progression from the player's current XP/level to a target level.
 * Respects budget limits, minimum XP/hour, and maximum acceptable loss, combining multiple methods
 * across unlock breakpoints (e.g., Level 1-20, 20-43, 43-66, 66-84, 84-99).
 */
public final class TrainingOptimizer
{
	private TrainingOptimizer()
	{
	}

	public static TrainingPlan optimize(
		List<CraftingResult> evaluatedRecipes,
		long startXp,
		int targetLevel,
		long availableBudgetGp,
		OptimizationObjective objective,
		long maxAcceptableLossGp,
		double minDesiredXpPerHour)
	{
		long safeStartXp = Math.max(0L, Math.min(XPTable.MAX_XP, startXp));
		int startLvl = XPTable.getLevelForXp(safeStartXp);
		int safeTargetLvl = XPTable.clampLevel(targetLevel);
		long targetXp = XPTable.getXpForLevel(safeTargetLvl);
		long xpReq = Math.max(0L, targetXp - safeStartXp);
		OptimizationObjective safeObjective = objective != null ? objective : OptimizationObjective.MAX_XP_WITHIN_BUDGET;

		if (xpReq <= 0L)
		{
			return TrainingPlan.builder()
				.startLevel(startLvl)
				.startXp(safeStartXp)
				.targetLevel(safeTargetLvl)
				.targetXp(targetXp)
				.xpRequired(0L)
				.availableBudgetGp(availableBudgetGp)
				.objective(safeObjective)
				.feasible(true)
				.statusMessage("Target level already reached.")
				.stages(Collections.emptyList())
				.build();
		}

		// Collect valid XP-granting candidates with complete price data
		List<CraftingResult> candidates = new ArrayList<>();
		TreeSet<Integer> breakpoints = new TreeSet<>();
		breakpoints.add(startLvl);
		breakpoints.add(safeTargetLvl);

		if (evaluatedRecipes != null)
		{
			for (CraftingResult r : evaluatedRecipes)
			{
				if (r == null || !r.isPriceDataComplete())
				{
					continue;
				}
				if (r.getXpPerAction() <= 0.0 || r.getXpPerHour() < minDesiredXpPerHour)
				{
					continue;
				}
				if (r.getMaterialCostPerCraft() <= 0.0)
				{
					continue;
				}
				candidates.add(r);
				int req = r.getRecipe().getRequiredLevel();
				if (req > startLvl && req < safeTargetLvl)
				{
					breakpoints.add(req);
				}
			}
		}

		if (candidates.isEmpty())
		{
			return TrainingPlan.builder()
				.startLevel(startLvl)
				.startXp(safeStartXp)
				.targetLevel(safeTargetLvl)
				.targetXp(targetXp)
				.xpRequired(xpReq)
				.availableBudgetGp(availableBudgetGp)
				.objective(safeObjective)
				.feasible(false)
				.statusMessage("No methods match the selected price data and minimum XP/hr constraints.")
				.stages(Collections.emptyList())
				.build();
		}

		List<Integer> bpList = new ArrayList<>(breakpoints);
		List<TrainingStage> rawStages = new ArrayList<>();

		double remainingBudget = Math.max(0L, availableBudgetGp);
		double cumulativeLoss = 0.0;
		long runningXp = safeStartXp;
		boolean budgetExhausted = false;

		for (int i = 0; i < bpList.size() - 1; i++)
		{
			int segFromLvl = bpList.get(i);
			int segToLvl = bpList.get(i + 1);
			long segStartXp = Math.max(runningXp, XPTable.getXpForLevel(segFromLvl));
			long segEndXp = XPTable.getXpForLevel(segToLvl);
			long segXpNeeded = Math.max(0L, segEndXp - segStartXp);
			if (segXpNeeded <= 0L)
			{
				continue;
			}

			CraftingResult best = pickBestForSegment(
				candidates, segFromLvl, segXpNeeded, remainingBudget,
				safeObjective, maxAcceptableLossGp, cumulativeLoss);

			if (best == null)
			{
				// Try partial actions with remaining budget before stopping
				CraftingResult partialBest = pickBestPartialForBudget(
					candidates, segFromLvl, remainingBudget, safeObjective, maxAcceptableLossGp, cumulativeLoss);
				if (partialBest != null)
				{
					long maxAffordable = (long) Math.floor(remainingBudget / partialBest.getMaterialCostPerCraft());
					if (maxAffordable > 0L)
					{
						double gainedXp = maxAffordable * partialBest.getXpPerAction();
						int reachedLvl = XPTable.getLevelForXp(Math.min(targetXp, segStartXp + Math.round(gainedXp)));
						double matCost = maxAffordable * partialBest.getMaterialCostPerCraft();
						double grossRev = maxAffordable * partialBest.getGrossRevenuePerCraft();
						double tax = maxAffordable * partialBest.getGeTaxPerCraft();
						double netProfit = maxAffordable * partialBest.getProfitPerCraft();
						double hours = partialBest.getActionsPerHour() > 0.0 ? maxAffordable / partialBest.getActionsPerHour() : 0.0;

						rawStages.add(TrainingStage.builder()
							.fromLevel(segFromLvl)
							.toLevel(Math.max(segFromLvl, reachedLvl))
							.recipe(partialBest.getRecipe())
							.result(partialBest)
							.actionsNeeded(maxAffordable)
							.xpGained(gainedXp)
							.totalMaterialCost(matCost)
							.totalGrossRevenue(grossRev)
							.totalGeTax(tax)
							.totalNetProfit(netProfit)
							.estimatedHours(hours)
							.build());

						remainingBudget -= matCost;
						runningXp += Math.round(gainedXp);
					}
				}
				budgetExhausted = true;
				break;
			}

			long actions = (long) Math.ceil(segXpNeeded / best.getXpPerAction());
			double gainedXp = actions * best.getXpPerAction();
			double matCost = actions * best.getMaterialCostPerCraft();
			double grossRev = actions * best.getGrossRevenuePerCraft();
			double tax = actions * best.getGeTaxPerCraft();
			double netProfit = actions * best.getProfitPerCraft();
			double hours = best.getActionsPerHour() > 0.0 ? actions / best.getActionsPerHour() : 0.0;

			rawStages.add(TrainingStage.builder()
				.fromLevel(segFromLvl)
				.toLevel(segToLvl)
				.recipe(best.getRecipe())
				.result(best)
				.actionsNeeded(actions)
				.xpGained(gainedXp)
				.totalMaterialCost(matCost)
				.totalGrossRevenue(grossRev)
				.totalGeTax(tax)
				.totalNetProfit(netProfit)
				.estimatedHours(hours)
				.build());

			remainingBudget -= matCost;
			if (netProfit < 0.0)
			{
				cumulativeLoss += (-netProfit);
			}
			runningXp += Math.round(gainedXp);
			if (runningXp >= targetXp)
			{
				break;
			}
		}

		List<TrainingStage> mergedStages = mergeAdjacentStages(rawStages);
		long totalActions = 0L;
		double totalXp = 0.0;
		double totalCost = 0.0;
		double totalGross = 0.0;
		double totalTax = 0.0;
		double totalProfit = 0.0;
		double totalHours = 0.0;
		double peakStageCost = 0.0;

		for (TrainingStage st : mergedStages)
		{
			totalActions += st.getActionsNeeded();
			totalXp += st.getXpGained();
			totalCost += st.getTotalMaterialCost();
			totalGross += st.getTotalGrossRevenue();
			totalTax += st.getTotalGeTax();
			totalProfit += st.getTotalNetProfit();
			totalHours += st.getEstimatedHours();
			if (st.getTotalMaterialCost() > peakStageCost)
			{
				peakStageCost = st.getTotalMaterialCost();
			}
		}

		boolean feasible = !budgetExhausted && (safeStartXp + Math.round(totalXp) >= targetXp) && !mergedStages.isEmpty();
		double avgXpHr = totalHours > 0.0 ? totalXp / totalHours : 0.0;

		String status;
		if (feasible)
		{
			status = "Complete " + mergedStages.size() + "-stage plan within "
				+ com.craftwise.util.CurrencyFormatter.formatGp(availableBudgetGp, true) + " budget.";
		}
		else if (mergedStages.isEmpty())
		{
			status = "Budget or constraints too restrictive to start any qualifying Crafting method.";
		}
		else
		{
			int reached = XPTable.getLevelForXp(safeStartXp + Math.round(totalXp));
			status = "Budget reached at Level " + reached + " (" + Math.round((totalXp * 100.0) / xpReq)
				+ "% of XP goal). Increase budget or choose a cheaper method.";
		}

		return TrainingPlan.builder()
			.startLevel(startLvl)
			.startXp(safeStartXp)
			.targetLevel(safeTargetLvl)
			.targetXp(targetXp)
			.xpRequired(xpReq)
			.availableBudgetGp(availableBudgetGp)
			.objective(safeObjective)
			.feasible(feasible)
			.statusMessage(status)
			.stages(Collections.unmodifiableList(mergedStages))
			.totalActions(totalActions)
			.totalXpGained(totalXp)
			.totalMaterialCost(totalCost)
			.totalGrossRevenue(totalGross)
			.totalGeTax(totalTax)
			.totalNetProfit(totalProfit)
			.totalEstimatedHours(totalHours)
			.peakUpfrontCost(peakStageCost)
			.averageXpPerHour(avgXpHr)
			.build();
	}

	private static CraftingResult pickBestForSegment(
		List<CraftingResult> candidates,
		int availableLevel,
		long segXpNeeded,
		double remainingBudget,
		OptimizationObjective objective,
		long maxAcceptableLossGp,
		double cumulativeLossSoFar)
	{
		List<CraftingResult> eligible = new ArrayList<>();
		for (CraftingResult r : candidates)
		{
			if (r.getRecipe().getRequiredLevel() > availableLevel)
			{
				continue;
			}
			long actions = (long) Math.ceil(segXpNeeded / r.getXpPerAction());
			double cost = actions * r.getMaterialCostPerCraft();
			if (cost > remainingBudget + 1e-6)
			{
				continue;
			}
			double profit = actions * r.getProfitPerCraft();
			if (maxAcceptableLossGp >= 0L && profit < 0.0 && (cumulativeLossSoFar - profit) > maxAcceptableLossGp + 1e-6)
			{
				continue;
			}
			eligible.add(r);
		}
		if (eligible.isEmpty())
		{
			return null;
		}
		eligible.sort(comparatorForSegment(objective));
		return eligible.get(0);
	}

	private static CraftingResult pickBestPartialForBudget(
		List<CraftingResult> candidates,
		int availableLevel,
		double remainingBudget,
		OptimizationObjective objective,
		long maxAcceptableLossGp,
		double cumulativeLossSoFar)
	{
		List<CraftingResult> eligible = new ArrayList<>();
		for (CraftingResult r : candidates)
		{
			if (r.getRecipe().getRequiredLevel() > availableLevel)
			{
				continue;
			}
			if (r.getMaterialCostPerCraft() > remainingBudget)
			{
				continue;
			}
			if (maxAcceptableLossGp >= 0L && r.getProfitPerCraft() < 0.0
				&& (cumulativeLossSoFar - r.getProfitPerCraft()) > maxAcceptableLossGp)
			{
				continue;
			}
			eligible.add(r);
		}
		if (eligible.isEmpty())
		{
			return null;
		}
		eligible.sort(comparatorForSegment(objective));
		return eligible.get(0);
	}

	private static Comparator<CraftingResult> comparatorForSegment(OptimizationObjective objective)
	{
		switch (objective)
		{
			case FASTEST_WITHIN_BUDGET:
			case MAX_XP_WITHIN_BUDGET:
				return Comparator.comparingDouble(CraftingResult::getXpPerHour).reversed()
					.thenComparing(Comparator.comparingDouble(CraftingResult::getGpPerXp).reversed());
			case MAX_PROFIT_WHILE_TRAINING:
				return Comparator.comparingDouble(CraftingResult::getProfitPerHour).reversed()
					.thenComparing(Comparator.comparingDouble(CraftingResult::getXpPerHour).reversed());
			case MIN_COST_TO_TARGET:
			case LOWEST_LOSS:
				// Highest gpPerXp (most profitable or smallest GP loss per XP gained)
				return Comparator.comparingDouble(CraftingResult::getGpPerXp).reversed()
					.thenComparing(Comparator.comparingDouble(CraftingResult::getXpPerHour).reversed());
			default:
				return Comparator.comparingDouble(CraftingResult::getXpPerHour).reversed();
		}
	}

	private static List<TrainingStage> mergeAdjacentStages(List<TrainingStage> raw)
	{
		if (raw.size() <= 1)
		{
			return raw;
		}
		List<TrainingStage> merged = new ArrayList<>();
		TrainingStage prev = raw.get(0);
		for (int i = 1; i < raw.size(); i++)
		{
			TrainingStage curr = raw.get(i);
			if (prev.getRecipe().getId().equals(curr.getRecipe().getId()))
			{
				prev = TrainingStage.builder()
					.fromLevel(prev.getFromLevel())
					.toLevel(curr.getToLevel())
					.recipe(prev.getRecipe())
					.result(prev.getResult())
					.actionsNeeded(prev.getActionsNeeded() + curr.getActionsNeeded())
					.xpGained(prev.getXpGained() + curr.getXpGained())
					.totalMaterialCost(prev.getTotalMaterialCost() + curr.getTotalMaterialCost())
					.totalGrossRevenue(prev.getTotalGrossRevenue() + curr.getTotalGrossRevenue())
					.totalGeTax(prev.getTotalGeTax() + curr.getTotalGeTax())
					.totalNetProfit(prev.getTotalNetProfit() + curr.getTotalNetProfit())
					.estimatedHours(prev.getEstimatedHours() + curr.getEstimatedHours())
					.build();
			}
			else
			{
				merged.add(prev);
				prev = curr;
			}
		}
		merged.add(prev);
		return merged;
	}
}

package com.craftwise.calculator;

import com.craftwise.data.CraftingRecipe;
import com.craftwise.data.CraftingRecipe.VerificationStatus;
import com.craftwise.model.CraftingResult;
import com.craftwise.model.TrainingPlan;
import com.craftwise.model.TrainingPlan.OptimizationObjective;
import com.craftwise.model.TrainingPlan.TrainingStage;
import com.craftwise.util.XPTable;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import lombok.Builder;
import lombok.Data;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Phase 9: Training Optimiser 2.0.
 * Evaluates Plans A–E side-by-side over verified recipes, enforcing F2P/members,
 * explicit temporary Crafting boosts (only on boostable recipes), quest/unlock gating
 * (never assumes completed quests/unlocks), and total capital budget constraints.
 */
public final class TrainingPlanComparisonCalculator
{
	@Getter
	@RequiredArgsConstructor
	public enum PlanStrategy
	{
		PLAN_A_FASTEST("Plan A: Fastest XP", "Maximizes XP/hour at current prices."),
		PLAN_B_CHEAPEST("Plan B: Cheapest Loss", "Minimizes total GP cost to reach target level."),
		PLAN_C_MOST_PROFITABLE("Plan C: Most Profitable", "Maximizes total net GP earned while reaching target."),
		PLAN_D_BEST_BALANCE("Plan D: Best Balance", "Balances high XP/hour with favorable GP/XP cost."),
		PLAN_E_UNDER_BUDGET("Plan E: Best Under Budget", "Fastest feasible method within available GP budget.");

		private final String label;
		private final String description;
	}

	@Getter
	@RequiredArgsConstructor
	public enum LevelRangePreset
	{
		CURRENT_TO_99("Current -> 99"),
		RANGE_70_99("70 -> 99"),
		RANGE_80_99("80 -> 99"),
		RANGE_90_99("90 -> 99"),
		CUSTOM("Custom Range");

		private final String label;
	}

	@Data
	@Builder
	public static class OptimizerOptions
	{
		private final int currentLevel;
		private final long currentXp;
		private final int targetLevel;
		private final int temporaryBoost; // 0 to +5 explicit boost
		private final boolean membersAllowed;
		private final boolean includeQuestLocked;
		private final boolean includeUnlockRequired;
		private final long availableBudgetGp; // <= 0 means unlimited for non-budget plans, or explicit check for Plan E
		@Builder.Default
		private final boolean enforceProgressionSteps = true;
	}

	@Data
	@Builder
	public static class ComparedPlan
	{
		private final PlanStrategy strategy;
		private final TrainingPlan plan;
		private final boolean feasible;
		private final String statusReason;
	}

	private TrainingPlanComparisonCalculator()
	{
	}

	public static List<ComparedPlan> buildSideBySidePlans(
		List<CraftingResult> allResults,
		OptimizerOptions options)
	{
		if (options == null || allResults == null || allResults.isEmpty())
		{
			return Collections.emptyList();
		}

		int startLvl = Math.max(1, Math.min(99, options.getCurrentLevel()));
		int targetLvl = Math.max(startLvl + 1, Math.min(99, options.getTargetLevel()));
		long startXp = Math.max(options.getCurrentXp(), XPTable.getXpForLevel(startLvl));
		long targetXp = XPTable.getXpForLevel(targetLvl);
		long neededXp = Math.max(0L, targetXp - startXp);
		if (neededXp <= 0L)
		{
			return Collections.emptyList();
		}

		List<CraftingResult> eligible = filterEligible(allResults, options);
		List<ComparedPlan> plans = new ArrayList<>(5);

		plans.add(buildPlanForStrategy(PlanStrategy.PLAN_A_FASTEST, eligible, startLvl, startXp, targetLvl, targetXp, options));
		plans.add(buildPlanForStrategy(PlanStrategy.PLAN_B_CHEAPEST, eligible, startLvl, startXp, targetLvl, targetXp, options));
		plans.add(buildPlanForStrategy(PlanStrategy.PLAN_C_MOST_PROFITABLE, eligible, startLvl, startXp, targetLvl, targetXp, options));
		plans.add(buildPlanForStrategy(PlanStrategy.PLAN_D_BEST_BALANCE, eligible, startLvl, startXp, targetLvl, targetXp, options));
		plans.add(buildPlanForStrategy(PlanStrategy.PLAN_E_UNDER_BUDGET, eligible, startLvl, startXp, targetLvl, targetXp, options));

		return Collections.unmodifiableList(plans);
	}

	private static List<CraftingResult> filterEligible(List<CraftingResult> results, OptimizerOptions options)
	{
		List<CraftingResult> filtered = new ArrayList<>();
		int boost = Math.max(0, Math.min(5, options.getTemporaryBoost()));
		for (CraftingResult r : results)
		{
			if (r == null || !r.isPriceDataComplete() || r.getRecipe() == null)
			{
				continue;
			}
			CraftingRecipe recipe = r.getRecipe();
			if (recipe.getVerificationStatus() == VerificationStatus.UNSUPPORTED)
			{
				continue;
			}
			if (recipe.getXpPerAction() <= 0.0)
			{
				continue;
			}
			if (!options.isMembersAllowed() && recipe.isMembers())
			{
				continue;
			}
			// Do not assume quest/unlock completions unless user explicitly enabled them
			if (!options.isIncludeQuestLocked() && recipe.hasQuestRequirement())
			{
				continue;
			}
			if (!options.isIncludeUnlockRequired() && recipe.hasUnlockRequirement())
			{
				continue;
			}
			int effectiveStartCap = recipe.isBoostable()
				? Math.min(99, options.getTargetLevel() - 1 + boost)
				: (options.getTargetLevel() - 1);
			if (recipe.getRequiredLevel() > effectiveStartCap)
			{
				continue;
			}
			filtered.add(r);
		}
		return filtered;
	}

	private static ComparedPlan buildPlanForStrategy(
		PlanStrategy strategy,
		List<CraftingResult> eligible,
		int startLevel,
		long startXp,
		int targetLevel,
		long targetXp,
		OptimizerOptions options)
	{
		if (eligible.isEmpty())
		{
			return ComparedPlan.builder()
				.strategy(strategy)
				.feasible(false)
				.statusReason("No verified recipes match level, members, and unlock filters.")
				.build();
		}

		// Collect transition milestones where higher-level methods unlock inside [startLevel, targetLevel)
		List<Integer> breakpoints = new ArrayList<>();
		breakpoints.add(startLevel);
		if (options.isEnforceProgressionSteps())
		{
			int boost = Math.max(0, Math.min(5, options.getTemporaryBoost()));
			for (CraftingResult r : eligible)
			{
				int effectiveUnlockLvl = r.getRecipe().isBoostable()
					? Math.max(1, r.getRecipe().getRequiredLevel() - boost)
					: r.getRecipe().getRequiredLevel();
				if (effectiveUnlockLvl > startLevel && effectiveUnlockLvl < targetLevel && !breakpoints.contains(effectiveUnlockLvl))
				{
					breakpoints.add(effectiveUnlockLvl);
				}
			}
			Collections.sort(breakpoints);
		}

		long cursorXp = startXp;
		int cursorLvl = startLevel;
		List<TrainingStage> stages = new ArrayList<>();
		double totalHours = 0.0;
		double totalProfit = 0.0;
		double totalMaterialCost = 0.0;
		double totalGrossRev = 0.0;
		double totalGeTax = 0.0;
		long totalActions = 0L;

		for (int b = 0; b < breakpoints.size(); b++)
		{
			int segStartLvl = breakpoints.get(b);
			int segEndLvl = (b + 1 < breakpoints.size()) ? breakpoints.get(b + 1) : targetLevel;
			long segTargetXp = Math.min(targetXp, XPTable.getXpForLevel(segEndLvl));
			long segXpNeeded = Math.max(0L, segTargetXp - cursorXp);
			if (segXpNeeded <= 0L)
			{
				continue;
			}

			int effLvl = Math.max(cursorLvl, segStartLvl);
			CraftingResult best = pickBestForSegment(strategy, eligible, effLvl, segXpNeeded, options);
			if (best == null)
			{
				return ComparedPlan.builder()
					.strategy(strategy)
					.feasible(false)
					.statusReason(strategy == PlanStrategy.PLAN_E_UNDER_BUDGET
						? "No eligible method fits within your " + options.getAvailableBudgetGp() + " GP budget."
						: "No unlocked recipe available at Crafting level " + effLvl + ".")
					.build();
			}

			// Merge consecutive stages if the same recipe stays optimal across adjacent level thresholds
			long actions = (long) Math.ceil(segXpNeeded / best.getXpPerAction());
			double xpGained = actions * best.getXpPerAction();
			double matCost = actions * best.getMaterialCostPerCraft();
			double grossRev = actions * best.getGrossRevenuePerCraft();
			double geTax = actions * best.getGeTaxPerCraft();
			double netProfit = actions * best.getProfitPerCraft();
			double hrs = best.getActionsPerHour() > 0.0 ? actions / best.getActionsPerHour() : 0.0;

			if (!stages.isEmpty() && Objects.equals(stages.get(stages.size() - 1).getRecipe().getId(), best.getRecipe().getId()))
			{
				TrainingStage prev = stages.remove(stages.size() - 1);
				long combinedActions = prev.getActionsNeeded() + actions;
				double combinedXp = prev.getXpGained() + xpGained;
				double combinedCost = prev.getTotalMaterialCost() + matCost;
				double combinedProfit = prev.getTotalNetProfit() + netProfit;
				double combinedHours = prev.getEstimatedHours() + hrs;
				stages.add(TrainingStage.builder()
					.fromLevel(prev.getFromLevel())
					.toLevel(segEndLvl)
					.recipe(best.getRecipe())
					.result(best)
					.actionsNeeded(combinedActions)
					.xpGained(combinedXp)
					.totalMaterialCost(combinedCost)
					.totalNetProfit(combinedProfit)
					.estimatedHours(combinedHours)
					.build());
			}
			else
			{
				stages.add(TrainingStage.builder()
					.fromLevel(segStartLvl)
					.toLevel(segEndLvl)
					.recipe(best.getRecipe())
					.result(best)
					.actionsNeeded(actions)
					.xpGained(xpGained)
					.totalMaterialCost(matCost)
					.totalNetProfit(netProfit)
					.estimatedHours(hrs)
					.build());
			}

			totalActions += actions;
			totalHours += hrs;
			totalProfit += netProfit;
			totalMaterialCost += matCost;
			totalGrossRev += grossRev;
			totalGeTax += geTax;
			cursorXp += Math.round(xpGained);
			cursorLvl = segEndLvl;
			if (cursorXp >= targetXp)
			{
				break;
			}
		}

		if (stages.isEmpty())
		{
			return ComparedPlan.builder()
				.strategy(strategy)
				.feasible(false)
				.statusReason("Could not construct training stages.")
				.build();
		}

		// For Plan E, check net capital loss feasibility cleanly
		if (strategy == PlanStrategy.PLAN_E_UNDER_BUDGET && options.getAvailableBudgetGp() > 0L)
		{
			double netRequiredGp = totalProfit < 0.0 ? -totalProfit : 0.0;
			if (netRequiredGp > options.getAvailableBudgetGp())
			{
				return ComparedPlan.builder()
					.strategy(strategy)
					.feasible(false)
					.statusReason(String.format(java.util.Locale.US,
						"Cheapest plan net loss (%,.0f GP) exceeds %,d GP budget.",
						netRequiredGp, options.getAvailableBudgetGp()))
					.build();
			}
		}

		long totalXpGained = Math.max(0L, cursorXp - startXp);
		double avgXpPerHr = totalHours > 0.0 ? totalXpGained / totalHours : 0.0;

		TrainingPlan builtPlan = TrainingPlan.builder()
			.objective(mapStrategyToObjective(strategy))
			.startLevel(startLevel)
			.targetLevel(targetLevel)
			.xpRequired(targetXp - startXp)
			.totalEstimatedHours(totalHours)
			.totalMaterialCost(totalMaterialCost)
			.totalGrossRevenue(totalGrossRev)
			.totalGeTax(totalGeTax)
			.totalNetProfit(totalProfit)
			.totalActions(totalActions)
			.averageXpPerHour(avgXpPerHr)
			.feasible(true)
			.statusMessage(strategy.getDescription())
			.stages(Collections.unmodifiableList(stages))
			.build();

		return ComparedPlan.builder()
			.strategy(strategy)
			.plan(builtPlan)
			.feasible(true)
			.statusReason("Ready")
			.build();
	}

	private static CraftingResult pickBestForSegment(
		PlanStrategy strategy,
		List<CraftingResult> eligible,
		int effectiveLevel,
		long xpNeeded,
		OptimizerOptions options)
	{
		int boost = Math.max(0, Math.min(5, options.getTemporaryBoost()));
		List<CraftingResult> unlocked = new ArrayList<>();
		for (CraftingResult r : eligible)
		{
			int usableLvl = r.getRecipe().isBoostable() ? effectiveLevel + boost : effectiveLevel;
			if (r.getRecipe().getRequiredLevel() <= usableLvl && r.getXpPerAction() > 0.0)
			{
				unlocked.add(r);
			}
		}
		if (unlocked.isEmpty())
		{
			return null;
		}

		switch (strategy)
		{
			case PLAN_A_FASTEST:
				return Collections.max(unlocked, Comparator.comparingDouble(CraftingResult::getXpPerHour));

			case PLAN_B_CHEAPEST:
				return Collections.max(unlocked, Comparator.comparingDouble(r ->
				{
					double gpPerXp = r.getGpPerXp();
					return Double.isNaN(gpPerXp) ? -Double.MAX_VALUE : gpPerXp;
				}));

			case PLAN_C_MOST_PROFITABLE:
				return Collections.max(unlocked, Comparator.comparingDouble(r ->
				{
					long acts = (long) Math.ceil(xpNeeded / r.getXpPerAction());
					return acts * r.getProfitPerCraft();
				}));

			case PLAN_D_BEST_BALANCE:
			{
				double maxXpHr = unlocked.stream().mapToDouble(CraftingResult::getXpPerHour).max().orElse(1.0);
				if (maxXpHr <= 0.0)
				{
					maxXpHr = 1.0;
				}
				final double normMaxXp = maxXpHr;
				return Collections.max(unlocked, Comparator.comparingDouble(r ->
				{
					double xpScore = r.getXpPerHour() / normMaxXp; // 0..1
					double gpPerXp = Double.isNaN(r.getGpPerXp()) ? -20.0 : Math.max(-20.0, Math.min(10.0, r.getGpPerXp()));
					double gpScore = (gpPerXp + 20.0) / 30.0; // normalized ~0..1
					return (0.55 * xpScore) + (0.45 * gpScore);
				}));
			}

			case PLAN_E_UNDER_BUDGET:
			{
				long budget = options.getAvailableBudgetGp();
				List<CraftingResult> affordable = new ArrayList<>();
				for (CraftingResult r : unlocked)
				{
					long acts = (long) Math.ceil(xpNeeded / r.getXpPerAction());
					double netLoss = -(acts * r.getProfitPerCraft());
					if (budget <= 0L || netLoss <= budget)
					{
						affordable.add(r);
					}
				}
				if (affordable.isEmpty())
				{
					// Fall back to cheapest GP/XP method if none strictly fits full budget upfront
					return Collections.max(unlocked, Comparator.comparingDouble(r ->
						Double.isNaN(r.getGpPerXp()) ? -Double.MAX_VALUE : r.getGpPerXp()));
				}
				return Collections.max(affordable, Comparator.comparingDouble(CraftingResult::getXpPerHour));
			}

			default:
				return unlocked.get(0);
		}
	}

	private static OptimizationObjective mapStrategyToObjective(PlanStrategy strategy)
	{
		switch (strategy)
		{
			case PLAN_A_FASTEST:
				return OptimizationObjective.MAX_XP_WITHIN_BUDGET;
			case PLAN_B_CHEAPEST:
				return OptimizationObjective.LOWEST_LOSS;
			case PLAN_C_MOST_PROFITABLE:
				return OptimizationObjective.MAX_PROFIT_WHILE_TRAINING;
			case PLAN_E_UNDER_BUDGET:
				return OptimizationObjective.FASTEST_WITHIN_BUDGET;
			case PLAN_D_BEST_BALANCE:
			default:
				return OptimizationObjective.MIN_COST_TO_TARGET;
		}
	}
}

package com.craftwise.calculator;

import com.craftwise.data.CraftingRecipe;
import com.craftwise.data.CraftingRecipe.RecipeInput;
import com.craftwise.model.CraftingResult;
import com.craftwise.model.CraftingResult.XpRateSource;
import com.craftwise.util.XPTable;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.Builder;
import lombok.Data;

/**
 * Calculates required actions, materials, GP cost/profit, and time to reach a target
 * Crafting level or XP goal using a selected {@link CraftingRecipe}.
 */
public final class XPCalculator
{
	@Data
	@Builder
	public static class MaterialRequirement
	{
		private final int itemId;
		private final String itemName;
		private final double exactQuantity;
		private final long purchaseQuantity;
	}

	@Data
	@Builder
	public static class XPGoalProjection
	{
		private final boolean available;
		private final CraftingRecipe recipe;
		private final int startLevel;
		private final long startXp;
		private final int targetLevel;
		private final long targetXp;
		private final long xpRequired;
		private final long actionsRequired;
		private final double totalXpGained;
		private final double totalMaterialCost;
		private final double totalGrossRevenue;
		private final double totalGeTax;
		private final double totalNetProfit;
		private final double xpPerHour;
		private final XpRateSource xpRateSource;
		private final double estimatedHours;
		@Builder.Default
		private final List<MaterialRequirement> materials = Collections.emptyList();
	}

	private XPCalculator()
	{
	}

	public static XPGoalProjection calculate(
		CraftingResult result,
		long currentXp,
		int targetLevel)
	{
		if (result == null || result.getRecipe() == null)
		{
			return XPGoalProjection.builder().available(false).build();
		}

		CraftingRecipe recipe = result.getRecipe();
		long safeStartXp = Math.max(0L, Math.min(XPTable.MAX_XP, currentXp));
		int startLvl = XPTable.getLevelForXp(safeStartXp);
		int safeTarget = XPTable.clampLevel(targetLevel);
		long targetXp = XPTable.getXpForLevel(safeTarget);
		long xpReq = Math.max(0L, targetXp - safeStartXp);

		double xpPerAction = recipe.getXpPerAction();
		if (xpReq == 0L || xpPerAction <= 0.0)
		{
			return XPGoalProjection.builder()
				.available(result.isPriceDataComplete())
				.recipe(recipe)
				.startLevel(startLvl)
				.startXp(safeStartXp)
				.targetLevel(safeTarget)
				.targetXp(targetXp)
				.xpRequired(xpReq)
				.actionsRequired(0L)
				.xpPerHour(result.getXpPerHour())
				.xpRateSource(result.getXpRateSource())
				.build();
		}

		long actions = (long) Math.ceil(xpReq / xpPerAction);
		double totalXp = actions * xpPerAction;
		double hours = result.getActionsPerHour() > 0.0 ? actions / result.getActionsPerHour() : 0.0;

		List<MaterialRequirement> materials = new ArrayList<>();
		for (RecipeInput input : recipe.getInputs())
		{
			double exactQty = actions * input.getQuantity();
			long purchaseQty = (long) Math.ceil(exactQty - 1e-9);
			materials.add(MaterialRequirement.builder()
				.itemId(input.getItemId())
				.itemName(input.getItemName())
				.exactQuantity(exactQty)
				.purchaseQuantity(purchaseQty)
				.build());
		}

		if (!result.isPriceDataComplete())
		{
			return XPGoalProjection.builder()
				.available(false)
				.recipe(recipe)
				.startLevel(startLvl)
				.startXp(safeStartXp)
				.targetLevel(safeTarget)
				.targetXp(targetXp)
				.xpRequired(xpReq)
				.actionsRequired(actions)
				.totalXpGained(totalXp)
				.xpPerHour(result.getXpPerHour())
				.xpRateSource(result.getXpRateSource())
				.estimatedHours(hours)
				.materials(Collections.unmodifiableList(materials))
				.build();
		}

		return XPGoalProjection.builder()
			.available(true)
			.recipe(recipe)
			.startLevel(startLvl)
			.startXp(safeStartXp)
			.targetLevel(safeTarget)
			.targetXp(targetXp)
			.xpRequired(xpReq)
			.actionsRequired(actions)
			.totalXpGained(totalXp)
			.totalMaterialCost(actions * result.getMaterialCostPerCraft())
			.totalGrossRevenue(actions * result.getGrossRevenuePerCraft())
			.totalGeTax(actions * result.getGeTaxPerCraft())
			.totalNetProfit(actions * result.getProfitPerCraft())
			.xpPerHour(result.getXpPerHour())
			.xpRateSource(result.getXpRateSource())
			.estimatedHours(hours)
			.materials(Collections.unmodifiableList(materials))
			.build();
	}
}

