package com.craftwise.data;

import java.util.Collections;
import java.util.List;
import lombok.Builder;
import lombok.Data;

/**
 * Immutable definition of a single OSRS Crafting recipe or method variant.
 * Supports multiple inputs, multiple outputs, probability-based/variable outputs,
 * equipment/quest requirements, and explicit data verification status.
 */
@Data
@Builder(toBuilder = true)
public class CraftingRecipe
{
	public enum VerificationStatus
	{
		VERIFIED("Verified"),
		NEEDS_REVIEW("Needs Review"),
		UNSUPPORTED("Unsupported");

		private final String label;

		VerificationStatus(String label)
		{
			this.label = label;
		}

		public String getLabel()
		{
			return label;
		}
	}

	@Data
	@Builder
	public static class RecipeInput
	{
		private final int itemId;
		private final String itemName;
		private final double quantity;
		@Builder.Default
		private final boolean stackable = false;
		@Builder.Default
		private final boolean consumed = true;
	}

	@Data
	@Builder
	public static class RecipeOutput
	{
		private final int itemId;
		private final String itemName;
		private final double quantity;
		/**
		 * Probability of receiving this output per craft action (1.0 for deterministic outputs).
		 * Expected output quantity per action = quantity * probability.
		 */
		@Builder.Default
		private final double probability = 1.0;
		@Builder.Default
		private final boolean tradeable = true;
		@Builder.Default
		private final boolean taxExempt = false;

		public double getExpectedQuantity()
		{
			return quantity * probability;
		}
	}

	private final String id;
	private final String name;
	private final CraftingCategory category;
	private final int requiredLevel;

	@Builder.Default
	private final List<RecipeInput> inputs = Collections.emptyList();
	@Builder.Default
	private final List<RecipeOutput> outputs = Collections.emptyList();

	private final double xpPerAction;
	private final double xpPerOutputItem;

	@Builder.Default
	private final List<String> requiredEquipment = Collections.emptyList();
	@Builder.Default
	private final int toolSlotsRequired = 0;
	@Builder.Default
	private final List<String> questRequirements = Collections.emptyList();
	@Builder.Default
	private final List<String> additionalRequirements = Collections.emptyList();

	private final String specialMechanics;
	private final String wikiReference;
	@Builder.Default
	private final VerificationStatus verificationStatus = VerificationStatus.VERIFIED;
	@Builder.Default
	private final boolean members = true;
	@Builder.Default
	private final boolean boostable = true;
	@Builder.Default
	private final List<String> requiredTools = Collections.emptyList();
	@Builder.Default
	private final List<String> requiredMoulds = Collections.emptyList();
	@Builder.Default
	private final List<String> unlockRequirements = Collections.emptyList();
	@Builder.Default
	private final String processStage = "Single-Step";
	@Builder.Default
	private final List<String> intermediateRecipeIds = Collections.emptyList();

	@Builder.Default
	private final String methodVariant = "Standard";
	private final double estimatedActionsPerHour;
	private final String xpRateBasis;
	@Builder.Default
	private final boolean xpRateVerified = false;

	public List<String> getAllToolsAndMoulds()
	{
		java.util.LinkedHashSet<String> all = new java.util.LinkedHashSet<>();
		if (requiredTools != null)
		{
			all.addAll(requiredTools);
		}
		if (requiredMoulds != null)
		{
			all.addAll(requiredMoulds);
		}
		if (requiredEquipment != null)
		{
			all.addAll(requiredEquipment);
		}
		return Collections.unmodifiableList(new java.util.ArrayList<>(all));
	}

	public RecipeOutput getPrimaryOutput()
	{
		if (outputs == null || outputs.isEmpty())
		{
			return null;
		}
		return outputs.get(0);
	}

	public int getPrimaryItemId()
	{
		RecipeOutput primary = getPrimaryOutput();
		return primary != null ? primary.getItemId() : -1;
	}

	public double getExpectedTotalOutputQuantity()
	{
		if (outputs == null || outputs.isEmpty())
		{
			return 0.0;
		}
		double sum = 0.0;
		for (RecipeOutput output : outputs)
		{
			sum += output.getExpectedQuantity();
		}
		return sum;
	}

	public boolean isMultiInput()
	{
		return inputs != null && inputs.size() > 1;
	}

	public boolean isMultiOutput()
	{
		return outputs != null && outputs.size() > 1;
	}

	public boolean hasVariableOutcome()
	{
		if (outputs == null)
		{
			return false;
		}
		for (RecipeOutput output : outputs)
		{
			if (output.getProbability() < 0.9999)
			{
				return true;
			}
		}
		return false;
	}

	public boolean isTradeableOutput()
	{
		if (outputs == null || outputs.isEmpty())
		{
			return false;
		}
		for (RecipeOutput output : outputs)
		{
			if (output.isTradeable())
			{
				return true;
			}
		}
		return false;
	}

	public double getEstimatedXpPerHour()
	{
		return Math.max(0.0, xpPerAction * estimatedActionsPerHour);
	}

	public boolean hasQuestRequirement()
	{
		return questRequirements != null && !questRequirements.isEmpty();
	}

	public boolean hasUnlockRequirement()
	{
		return unlockRequirements != null && !unlockRequirements.isEmpty();
	}
}

package com.craftwise.data;

import com.craftwise.data.CraftingRecipe.RecipeInput;
import com.craftwise.data.CraftingRecipe.RecipeOutput;
import com.craftwise.data.CraftingRecipe.VerificationStatus;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import lombok.Builder;
import lombok.Data;

/**
 * Startup and test-time integrity checker for {@link CraftingDataRepository} recipes.
 * Validates structural consistency, OSRS bounds, non-negative XP/quantities, probability sums,
 * verification status coverage, and Wiki references without blocking startup on non-fatal warnings.
 */
public final class DataIntegrityChecker
{
	@Data
	@Builder
	public static class IntegrityReport
	{
		private final int totalRecipes;
		private final int verifiedCount;
		private final int needsReviewCount;
		private final int unsupportedCount;
		@Builder.Default
		private final List<String> errors = Collections.emptyList();
		@Builder.Default
		private final List<String> warnings = Collections.emptyList();

		public boolean isPassed()
		{
			return errors == null || errors.isEmpty();
		}
	}

	private DataIntegrityChecker()
	{
	}

	public static IntegrityReport check(List<CraftingRecipe> recipes)
	{
		return check(recipes, Collections.emptyMap());
	}

	/**
	 * Runs full structural and optional live Wiki item-name cross-checks on {@code recipes}.
	 */
	public static IntegrityReport check(List<CraftingRecipe> recipes, Map<Integer, String> liveMappingNamesById)
	{
		if (recipes == null || recipes.isEmpty())
		{
			return IntegrityReport.builder()
				.totalRecipes(0)
				.errors(Collections.singletonList("Recipe repository is empty."))
				.build();
		}

		List<String> errors = new ArrayList<>(RecipeValidator.validateAll(recipes));
		List<String> warnings = new ArrayList<>();
		Set<String> seenNamesByVariant = new HashSet<>();
		int verified = 0;
		int needsReview = 0;
		int unsupported = 0;

		for (CraftingRecipe recipe : recipes)
		{
			if (recipe == null)
			{
				continue;
			}
			VerificationStatus status = recipe.getVerificationStatus();
			if (status == VerificationStatus.VERIFIED)
			{
				verified++;
			}
			else if (status == VerificationStatus.NEEDS_REVIEW)
			{
				needsReview++;
			}
			else if (status == VerificationStatus.UNSUPPORTED)
			{
				unsupported++;
			}

			String dedupKey = (recipe.getName() + "|" + recipe.getMethodVariant()).toLowerCase(Locale.ROOT);
			if (!seenNamesByVariant.add(dedupKey))
			{
				warnings.add("Duplicate name+variant key: " + recipe.getName() + " (" + recipe.getMethodVariant() + ")");
			}

			// Verify exclusive probability sums on variable outputs don't exceed 1.0 + eps
			if (recipe.hasVariableOutcome() && recipe.getOutputs() != null)
			{
				double probSum = 0.0;
				for (RecipeOutput out : recipe.getOutputs())
				{
					probSum += out.getProbability();
				}
				if (probSum > 1.001)
				{
					errors.add("Variable outcome probability sum exceeds 1.0 (" + probSum + ") for " + recipe.getId());
				}
			}

			// Verify optional /mapping names match our curated names cleanly
			if (liveMappingNamesById != null && !liveMappingNamesById.isEmpty())
			{
				if (recipe.getInputs() != null)
				{
					for (RecipeInput in : recipe.getInputs())
					{
						if (in.isConsumed() && in.getItemId() != 995)
						{
							String mapped = liveMappingNamesById.get(in.getItemId());
							if (mapped == null)
							{
								warnings.add("Unmapped tradeable input ID " + in.getItemId() + " (" + in.getItemName() + ") in " + recipe.getId());
							}
						}
					}
				}
				if (recipe.getOutputs() != null)
				{
					for (RecipeOutput out : recipe.getOutputs())
					{
						if (out.isTradeable())
						{
							String mapped = liveMappingNamesById.get(out.getItemId());
							if (mapped == null)
							{
								errors.add("Missing GE mapping for tradeable output ID " + out.getItemId() + " (" + out.getItemName() + ") in " + recipe.getId());
							}
						}
					}
				}
			}
		}

		return IntegrityReport.builder()
			.totalRecipes(recipes.size())
			.verifiedCount(verified)
			.needsReviewCount(needsReview)
			.unsupportedCount(unsupported)
			.errors(Collections.unmodifiableList(errors))
			.warnings(Collections.unmodifiableList(warnings))
			.build();
	}

	public static Map<Integer, String> toNameMap(Map<Integer, com.craftwise.model.ItemPrice> mapping)
	{
		if (mapping == null || mapping.isEmpty())
		{
			return Collections.emptyMap();
		}
		Map<Integer, String> out = new HashMap<>(mapping.size());
		for (Map.Entry<Integer, com.craftwise.model.ItemPrice> e : mapping.entrySet())
		{
			if (e.getValue() != null && e.getValue().getName() != null)
			{
				out.put(e.getKey(), e.getValue().getName());
			}
		}
		return out;
	}
}

package com.craftwise.data;

import com.craftwise.data.CraftingRecipe.RecipeInput;
import com.craftwise.data.CraftingRecipe.RecipeOutput;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Validates structural and OSRS game-mechanic integrity of {@link CraftingRecipe} definitions.
 */
public final class RecipeValidator
{
	private RecipeValidator()
	{
	}

	public static List<String> validateRecipe(CraftingRecipe recipe)
	{
		if (recipe == null)
		{
			return Collections.singletonList("Recipe is null.");
		}
		List<String> errors = new ArrayList<>();

		if (recipe.getId() == null || recipe.getId().trim().isEmpty())
		{
			errors.add("Missing recipe id.");
		}
		if (recipe.getName() == null || recipe.getName().trim().isEmpty())
		{
			errors.add("Missing recipe name for " + recipe.getId());
		}
		if (recipe.getCategory() == null)
		{
			errors.add("Missing category for " + recipe.getId());
		}
		if (recipe.getRequiredLevel() < 1 || recipe.getRequiredLevel() > 99)
		{
			errors.add("Invalid requiredLevel (" + recipe.getRequiredLevel() + ") for " + recipe.getId());
		}
		if (recipe.getXpPerAction() < 0.0)
		{
			errors.add("Negative xpPerAction for " + recipe.getId());
		}
		if (recipe.getXpPerOutputItem() < 0.0)
		{
			errors.add("Negative xpPerOutputItem for " + recipe.getId());
		}
		if (recipe.getInputs() == null || recipe.getInputs().isEmpty())
		{
			errors.add("Recipe has no inputs: " + recipe.getId());
		}
		else
		{
			for (RecipeInput input : recipe.getInputs())
			{
				if (input.getItemId() <= 0)
				{
					errors.add("Invalid input itemId in " + recipe.getId() + ": " + input.getItemName());
				}
				if (input.getQuantity() <= 0.0)
				{
					errors.add("Non-positive input quantity in " + recipe.getId() + ": " + input.getItemName());
				}
				if (input.getItemName() == null || input.getItemName().trim().isEmpty())
				{
					errors.add("Missing input itemName in " + recipe.getId());
				}
			}
		}

		if (recipe.getOutputs() == null || recipe.getOutputs().isEmpty())
		{
			errors.add("Recipe has no outputs: " + recipe.getId());
		}
		else
		{
			for (RecipeOutput output : recipe.getOutputs())
			{
				if (output.getItemId() <= 0)
				{
					errors.add("Invalid output itemId in " + recipe.getId() + ": " + output.getItemName());
				}
				if (output.getQuantity() <= 0.0)
				{
					errors.add("Non-positive output quantity in " + recipe.getId() + ": " + output.getItemName());
				}
				if (output.getProbability() <= 0.0 || output.getProbability() > 1.0)
				{
					errors.add("Invalid output probability (" + output.getProbability() + ") in " + recipe.getId());
				}
				if (output.getItemName() == null || output.getItemName().trim().isEmpty())
				{
					errors.add("Missing output itemName in " + recipe.getId());
				}
			}
		}

		if (recipe.getWikiReference() == null || !recipe.getWikiReference().startsWith("https://oldschool.runescape.wiki/"))
		{
			errors.add("Missing or invalid OSRS Wiki reference URL for " + recipe.getId());
		}
		if (recipe.getVerificationStatus() == null)
		{
			errors.add("Missing verificationStatus for " + recipe.getId());
		}
		if (recipe.getEstimatedActionsPerHour() <= 0.0)
		{
			errors.add("Non-positive estimatedActionsPerHour for " + recipe.getId());
		}

		return errors;
	}

	public static List<String> validateAll(List<CraftingRecipe> recipes)
	{
		if (recipes == null || recipes.isEmpty())
		{
			return Collections.singletonList("Recipe list is empty.");
		}
		List<String> allErrors = new ArrayList<>();
		Set<String> seenIds = new HashSet<>();
		for (CraftingRecipe recipe : recipes)
		{
			if (recipe != null && recipe.getId() != null && !seenIds.add(recipe.getId()))
			{
				allErrors.add("Duplicate recipe ID: " + recipe.getId());
			}
			allErrors.addAll(validateRecipe(recipe));
		}
		return allErrors;
	}
}

package com.craftwise.market;

import com.craftwise.CraftWiseConfig.PriceCalculationMode;
import com.craftwise.bank.BankCraftingCalculator;
import com.craftwise.bank.BankCraftingCalculator.BankRecipeMatch;
import com.craftwise.bank.OwnedMaterialSnapshot.SnapshotView;
import com.craftwise.calculator.ProfitCalculator.CustomPriceOverride;
import com.craftwise.data.CraftingRecipe;
import com.craftwise.market.MarketOpportunity.OpportunityStatus;
import com.craftwise.model.CraftingResult;
import com.craftwise.model.ItemPrice;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import lombok.Builder;
import lombok.Data;

/**
 * Feature 3: Integrates live Crafting Market Watcher opportunities with Bank-Aware Crafting.
 * Surfaces recipes that are simultaneously profitable on current GE prices AND craftable
 * using the player's owned bank/inventory materials, highlighting the Best Opportunity Using Your Bank.
 */
public final class BankMarketIntegrator
{
	@Data
	@Builder
	public static class IntegratedOpportunity
	{
		private final MarketOpportunity opportunity;
		private final BankRecipeMatch bankMatch;
		private final long maxCraftableFromBank;
		private final boolean profitableWithMyBank;
		private final double immediateProfitFromBankGp;
		private final double immediateXpFromBank;
		private final long missingBuyCostGp;
		private final boolean bankDataAvailable;
	}

	@Data
	@Builder
	public static class IntegratedMarketView
	{
		private final boolean bankDataAvailable;
		@Builder.Default
		private final List<IntegratedOpportunity> items = Collections.emptyList();
		private final IntegratedOpportunity bestOpportunityUsingYourBank;
		private final IntegratedOpportunity topNewlyProfitableWithBank;
		private final int craftableCount;
		private final int profitableWithBankCount;
	}

	private BankMarketIntegrator()
	{
	}

	public static IntegratedMarketView integrate(
		List<MarketOpportunity> opportunities,
		SnapshotView snapshot,
		long targetCraftsForMissingCalc,
		boolean includeNotedFromInventory,
		int playerLevel,
		boolean membersAllowed,
		boolean includeQuestLocked,
		boolean includeUnlockRequired,
		Map<Integer, ItemPrice> prices,
		Map<String, Integer> nameToIdIndex,
		PriceCalculationMode mode,
		Map<Integer, CustomPriceOverride> customPrices)
	{
		boolean bankAvailable = snapshot != null && snapshot.isBankScanned();
		if (opportunities == null || opportunities.isEmpty())
		{
			return IntegratedMarketView.builder()
				.bankDataAvailable(bankAvailable)
				.items(Collections.emptyList())
				.craftableCount(0)
				.profitableWithBankCount(0)
				.build();
		}

		List<IntegratedOpportunity> combined = new ArrayList<>(opportunities.size());
		IntegratedOpportunity bestWithBank = null;
		IntegratedOpportunity topNewlyWithBank = null;
		int craftableCount = 0;
		int profitableWithBankCount = 0;

		for (MarketOpportunity opp : opportunities)
		{
			if (opp == null || opp.getResult() == null || opp.getResult().getRecipe() == null)
			{
				continue;
			}
			CraftingResult res = opp.getResult();
			CraftingRecipe rec = res.getRecipe();

			BankRecipeMatch match = bankAvailable
				? BankCraftingCalculator.matchRecipe(
					rec, res, snapshot, targetCraftsForMissingCalc, includeNotedFromInventory,
					prices, nameToIdIndex, mode, customPrices)
				: null;

			long maxCrafts = match != null ? match.getMaxCompleteCrafts() : 0L;
			boolean eligibleForPlayer = rec.getRequiredLevel() <= playerLevel
				&& (membersAllowed || !rec.isMembers())
				&& (includeQuestLocked || !rec.hasQuestRequirement())
				&& (includeUnlockRequired || !rec.hasUnlockRequirement());

			boolean profWithBank = bankAvailable
				&& eligibleForPlayer
				&& maxCrafts > 0L
				&& opp.isProfitable();

			double immediateProfit = match != null ? match.getTotalProfitFromOwnedStock() : 0.0;
			double immediateXp = match != null ? match.getTotalXpFromOwnedStock() : 0.0;
			long missingCost = match != null ? match.getMissingForTargetCostGp() : 0L;

			if (bankAvailable && maxCrafts > 0L && eligibleForPlayer)
			{
				craftableCount++;
			}
			if (profWithBank)
			{
				profitableWithBankCount++;
			}

			IntegratedOpportunity item = IntegratedOpportunity.builder()
				.opportunity(opp)
				.bankMatch(match)
				.maxCraftableFromBank(maxCrafts)
				.profitableWithMyBank(profWithBank)
				.immediateProfitFromBankGp(immediateProfit)
				.immediateXpFromBank(immediateXp)
				.missingBuyCostGp(missingCost)
				.bankDataAvailable(bankAvailable)
				.build();
			combined.add(item);

			if (profWithBank)
			{
				if (bestWithBank == null || compareBestBankCandidate(item, bestWithBank) < 0)
				{
					bestWithBank = item;
				}
				if (opp.getStatus() == OpportunityStatus.NEWLY_PROFITABLE)
				{
					if (topNewlyWithBank == null
						|| item.getImmediateProfitFromBankGp() > topNewlyWithBank.getImmediateProfitFromBankGp())
					{
						topNewlyWithBank = item;
					}
				}
			}
		}

		return IntegratedMarketView.builder()
			.bankDataAvailable(bankAvailable)
			.items(Collections.unmodifiableList(combined))
			.bestOpportunityUsingYourBank(bestWithBank)
			.topNewlyProfitableWithBank(topNewlyWithBank)
			.craftableCount(craftableCount)
			.profitableWithBankCount(profitableWithBankCount)
			.build();
	}

	private static int compareBestBankCandidate(IntegratedOpportunity a, IntegratedOpportunity b)
	{
		// Prioritize newly profitable / high profit when profits are strong, otherwise total immediate profit
		int cmpProfit = Double.compare(b.getImmediateProfitFromBankGp(), a.getImmediateProfitFromBankGp());
		if (cmpProfit != 0)
		{
			return cmpProfit;
		}
		int aBoost = a.getOpportunity().getStatus() == OpportunityStatus.NEWLY_PROFITABLE ? 1 : 0;
		int bBoost = b.getOpportunity().getStatus() == OpportunityStatus.NEWLY_PROFITABLE ? 1 : 0;
		if (aBoost != bBoost)
		{
			return Integer.compare(bBoost, aBoost);
		}
		return Comparator.<Double>reverseOrder().compare(a.getImmediateXpFromBank(), b.getImmediateXpFromBank());
	}

	public static List<IntegratedOpportunity> filter(
		List<IntegratedOpportunity> all,
		boolean onlyProfitableWithMyBank)
	{
		if (all == null || all.isEmpty())
		{
			return Collections.emptyList();
		}
		if (!onlyProfitableWithMyBank)
		{
			return all;
		}
		List<IntegratedOpportunity> filtered = new ArrayList<>();
		for (IntegratedOpportunity item : all)
		{
			if (item != null && item.isProfitableWithMyBank())
			{
				filtered.add(item);
			}
		}
		return Collections.unmodifiableList(filtered);
	}
}

