package com.craftwise.util;

import java.util.Locale;

/**
 * Formatting and parsing utilities for OSRS GP amounts and GP/XP ratios.
 */
public final class CurrencyFormatter
{
	private CurrencyFormatter()
	{
	}

	public static String formatGp(long gp, boolean compact)
	{
		if (compact && Math.abs(gp) >= 10_000L)
		{
			return NumberFormatter.formatCompact(gp, true) + " gp";
		}
		return NumberFormatter.formatInt(gp) + " gp";
	}

	public static String formatSignedGp(long gp, boolean compact)
	{
		if (gp > 0L)
		{
			return "+" + formatGp(gp, compact);
		}
		return formatGp(gp, compact);
	}

	public static String formatSignedGp(double gp, boolean compact)
	{
		if (Double.isNaN(gp) || Double.isInfinite(gp))
		{
			return "N/A";
		}
		long rounded = Math.round(gp);
		return formatSignedGp(rounded, compact);
	}

	public static String formatGpPerXp(double gpPerXp)
	{
		if (Double.isNaN(gpPerXp) || Double.isInfinite(gpPerXp))
		{
			return "N/A";
		}
		String sign = gpPerXp > 0.005 ? "+" : "";
		return sign + NumberFormatter.formatDecimal(gpPerXp, 2) + " gp/xp";
	}

	/**
	 * Parses user-entered GP strings supporting suffixes like "k", "m", "b" (e.g., "500k", "1.5m", "10,000").
	 * Returns null if the input cannot be parsed as a valid non-negative GP amount.
	 */
	public static Long parseGpAmount(String raw)
	{
		if (raw == null)
		{
			return null;
		}
		String cleaned = raw.trim().toLowerCase(Locale.ROOT)
			.replace(",", "")
			.replace("_", "")
			.replace("gp", "")
			.trim();
		if (cleaned.isEmpty())
		{
			return null;
		}
		double multiplier = 1.0;
		if (cleaned.endsWith("k"))
		{
			multiplier = 1_000.0;
			cleaned = cleaned.substring(0, cleaned.length() - 1).trim();
		}
		else if (cleaned.endsWith("m"))
		{
			multiplier = 1_000_000.0;
			cleaned = cleaned.substring(0, cleaned.length() - 1).trim();
		}
		else if (cleaned.endsWith("b"))
		{
			multiplier = 1_000_000_000.0;
			cleaned = cleaned.substring(0, cleaned.length() - 1).trim();
		}
		try
		{
			double val = Double.parseDouble(cleaned);
			if (Double.isNaN(val) || Double.isInfinite(val) || val < 0.0)
			{
				return null;
			}
			double scaled = val * multiplier;
			if (scaled > Long.MAX_VALUE)
			{
				return Long.MAX_VALUE;
			}
			return Math.round(scaled);
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}
}

package com.craftwise.util;

import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.text.NumberFormat;
import java.util.Locale;

/**
 * Number, XP, percentage, and duration formatting utilities for CraftWise.
 */
public final class NumberFormatter
{
	private static final NumberFormat INT_FORMAT = NumberFormat.getIntegerInstance(Locale.US);
	private static final DecimalFormat ONE_DEC_FORMAT = new DecimalFormat("#,##0.0", DecimalFormatSymbols.getInstance(Locale.US));
	private static final DecimalFormat TWO_DEC_FORMAT = new DecimalFormat("#,##0.00", DecimalFormatSymbols.getInstance(Locale.US));

	private NumberFormatter()
	{
	}

	public static synchronized String formatInt(long value)
	{
		return INT_FORMAT.format(value);
	}

	public static synchronized String formatDecimal(double value, int decimals)
	{
		if (Double.isNaN(value) || Double.isInfinite(value))
		{
			return "N/A";
		}
		if (decimals <= 0)
		{
			return INT_FORMAT.format(Math.round(value));
		}
		if (decimals == 1)
		{
			return ONE_DEC_FORMAT.format(value);
		}
		return TWO_DEC_FORMAT.format(value);
	}

	public static String formatCompact(double value, boolean useCompact)
	{
		if (Double.isNaN(value) || Double.isInfinite(value))
		{
			return "N/A";
		}
		if (!useCompact)
		{
			return formatInt(Math.round(value));
		}
		double abs = Math.abs(value);
		String sign = value < 0 ? "-" : "";
		if (abs >= 1_000_000_000.0)
		{
			return sign + formatDecimal(abs / 1_000_000_000.0, 2) + "B";
		}
		if (abs >= 1_000_000.0)
		{
			return sign + formatDecimal(abs / 1_000_000.0, 2) + "M";
		}
		if (abs >= 10_000.0)
		{
			return sign + formatDecimal(abs / 1_000.0, 1) + "K";
		}
		return formatInt(Math.round(value));
	}

	public static String formatXp(double xp, boolean compact)
	{
		if (Double.isNaN(xp) || Double.isInfinite(xp))
		{
			return "N/A";
		}
		if (compact && Math.abs(xp) >= 10_000.0)
		{
			return formatCompact(xp, true) + " XP";
		}
		if (Math.abs(xp - Math.rint(xp)) < 1e-6)
		{
			return formatInt(Math.round(xp)) + " XP";
		}
		return formatDecimal(xp, 1) + " XP";
	}

	public static String formatXpPerHour(double xpPerHour, boolean compact)
	{
		if (Double.isNaN(xpPerHour) || Double.isInfinite(xpPerHour) || xpPerHour <= 0.0)
		{
			return "N/A";
		}
		return formatCompact(xpPerHour, compact) + " XP/hr";
	}

	public static String formatPercent(double percent)
	{
		if (Double.isNaN(percent) || Double.isInfinite(percent))
		{
			return "N/A";
		}
		return formatDecimal(percent, 1) + "%";
	}

	/**
	 * Formats a duration in hours into a concise readable string (e.g. "12m", "2h 15m", "3d 4h").
	 */
	public static String formatHours(double hours)
	{
		if (Double.isNaN(hours) || Double.isInfinite(hours) || hours < 0.0)
		{
			return "N/A";
		}
		long totalMinutes = Math.round(hours * 60.0);
		if (totalMinutes < 1L)
		{
			return "<1m";
		}
		long days = totalMinutes / (24L * 60L);
		long remHours = (totalMinutes % (24L * 60L)) / 60L;
		long mins = totalMinutes % 60L;
		if (days > 0L)
		{
			return days + "d " + remHours + "h";
		}
		if (remHours > 0L)
		{
			return remHours + "h " + mins + "m";
		}
		return mins + "m";
	}

	/**
	 * Formats an epoch timestamp (seconds) into a relative age label like "12s ago", "4m ago", "2h ago".
	 */
	public static String formatRelativeAge(long epochSeconds, long nowEpochSeconds)
	{
		if (epochSeconds <= 0L)
		{
			return "Never";
		}
		long diff = Math.max(0L, nowEpochSeconds - epochSeconds);
		if (diff < 60L)
		{
			return diff + "s ago";
		}
		if (diff < 3600L)
		{
			return (diff / 60L) + "m ago";
		}
		if (diff < 86400L)
		{
			return (diff / 3600L) + "h ago";
		}
		return (diff / 86400L) + "d ago";
	}
}

package com.craftwise.util;

/**
 * Official Old School RuneScape XP progression table covering levels 1 to 99.
 * Uses the exact Jagex integer floor formula:
 * {@code XP(L) = floor( (1/4) * sum_{i=1}^{L-1} floor(i + 300 * 2^(i/7)) )}.
 */
public final class XPTable
{
	public static final int MIN_LEVEL = 1;
	public static final int MAX_LEVEL = 99;
	public static final long MAX_XP = 200_000_000L;

	private static final long[] XP_FOR_LEVEL = new long[MAX_LEVEL + 1];

	static
	{
		XP_FOR_LEVEL[1] = 0L;
		long points = 0L;
		for (int level = 1; level < MAX_LEVEL; level++)
		{
			points += (long) Math.floor(level + 300.0 * Math.pow(2.0, level / 7.0));
			XP_FOR_LEVEL[level + 1] = points / 4L;
		}
	}

	private XPTable()
	{
	}

	/**
	 * Returns the minimum total XP required to reach the specified level (1..99).
	 */
	public static long getXpForLevel(int level)
	{
		int clamped = clampLevel(level);
		return XP_FOR_LEVEL[clamped];
	}

	/**
	 * Returns the Crafting level (1..99) corresponding to the given total XP.
	 */
	public static int getLevelForXp(long xp)
	{
		if (xp <= 0L)
		{
			return MIN_LEVEL;
		}
		for (int level = MAX_LEVEL; level >= MIN_LEVEL; level--)
		{
			if (xp >= XP_FOR_LEVEL[level])
			{
				return level;
			}
		}
		return MIN_LEVEL;
	}

	/**
	 * Returns XP remaining from {@code currentXp} to reach {@code targetLevel}.
	 * Returns 0 if {@code currentXp} already meets or exceeds {@code targetLevel}.
	 */
	public static long getXpRemainingToLevel(long currentXp, int targetLevel)
	{
		long targetXp = getXpForLevel(targetLevel);
		return Math.max(0L, targetXp - Math.max(0L, currentXp));
	}

	/**
	 * Returns XP remaining until the next level (returns 0 if already level 99+).
	 */
	public static long getXpToNextLevel(long currentXp)
	{
		int currentLevel = getLevelForXp(currentXp);
		if (currentLevel >= MAX_LEVEL)
		{
			return 0L;
		}
		return getXpRemainingToLevel(currentXp, currentLevel + 1);
	}

	/**
	 * Returns progress percentage (0.0 to 100.0) within the current level toward the next level.
	 */
	public static double getProgressToNextLevelPercent(long currentXp)
	{
		long safeXp = Math.max(0L, currentXp);
		int currentLevel = getLevelForXp(safeXp);
		if (currentLevel >= MAX_LEVEL)
		{
			return 100.0;
		}
		long levelStartXp = getXpForLevel(currentLevel);
		long nextLevelXp = getXpForLevel(currentLevel + 1);
		long span = nextLevelXp - levelStartXp;
		if (span <= 0L)
		{
			return 100.0;
		}
		return Math.min(100.0, Math.max(0.0, ((safeXp - levelStartXp) * 100.0) / span));
	}

	/**
	 * Returns overall progress percentage (0.0 to 100.0) from {@code currentXp} toward {@code targetLevel}.
	 */
	public static double getProgressToTargetPercent(long currentXp, int targetLevel)
	{
		long safeXp = Math.max(0L, currentXp);
		long targetXp = getXpForLevel(targetLevel);
		if (targetXp <= 0L || safeXp >= targetXp)
		{
			return 100.0;
		}
		return Math.min(100.0, Math.max(0.0, (safeXp * 100.0) / targetXp));
	}

	public static int clampLevel(int level)
	{
		return Math.max(MIN_LEVEL, Math.min(MAX_LEVEL, level));
	}
}

