		Assert.assertEquals(8, InventoryCalculator.calculateCraftsPerInventory(CraftingDataRepository.getById("black_dhide_body")));
		// Air battlestaff: 0 tool slots, 2 items/staff -> 28 / 2 = 14 staves/inventory
